let SESSIONS_FILE = path.join(DATA_DIR, 'manager_sessions.json');
let BACKUP_DIR = path.join(DATA_DIR, 'backups');
let AUDIT_LOG_FILE = path.join(DATA_DIR, 'manager_audit.jsonl');
