// V3-11: Cấu hình SSRF fail-closed trên production
const DISABLE_SSRF_CHECK = !isProdRuntime && String(process.env.DISABLE_SSRF_CHECK || '').toLowerCase() === 'true';
const ALLOW_PRIVATE_BOT_IPS = isProdRuntime
    ? String(process.env.ALLOW_PRIVATE_BOT_IPS || 'false').toLowerCase() === 'true'
    : String(process.env.ALLOW_PRIVATE_BOT_IPS || 'true').toLowerCase() !== 'false';

async function validateSafeBotUrl(rawUrl) {
    const raw = String(rawUrl || '').trim();
    if (!raw) return '';

    let url;
    try {
        url = new URL(raw);
    } catch (_) {
        throw new Error('URL bot không hợp lệ.');
    }

    if (!['http:', 'https:'].includes(url.protocol)) {
        throw new Error('URL bot phải dùng http:// hoặc https://.');
    }

    if (url.username || url.password) {
        throw new Error('URL bot không được chứa username/password.');
    }

    const hostname = url.hostname.toLowerCase();

    // Luôn chặn endpoint Cloud Metadata (AWS 169.254.169.254 / GCP metadata.google.internal)
    if (hostname === '169.254.169.254' || hostname === 'metadata.google.internal' || hostname.endsWith('.metadata.google.internal')) {
        throw new Error(`Hostname '${hostname}' bị chặn do chính sách bảo mật đám mây.`);
    }

    if (DISABLE_SSRF_CHECK || ALLOWED_INTERNAL_HOSTS.has(hostname)) {
        url.hash = '';
        url.search = '';
        return url.toString().replace(/\/+$/, '');
    }

    if (net.isIP(hostname) !== 0) {
        if (!ALLOW_PRIVATE_BOT_IPS && isPrivateOrBlockedIp(hostname)) {
            if (!ALLOWED_INTERNAL_HOSTS.has(hostname)) {
                throw new Error(`Địa chỉ IP '${hostname}' là địa chỉ nội bộ bị chặn (SSRF).`);
            }
        }
    } else {
        try {
            const records = await dns.promises.lookup(hostname, { all: true });
            for (const rec of records) {
                if (rec.address === '169.254.169.254' || rec.address.startsWith('169.254.')) {
                    throw new Error(`Hostname '${hostname}' trỏ về Cloud Metadata IP '${rec.address}' bị chặn.`);
                }
                if (!ALLOW_PRIVATE_BOT_IPS && isPrivateOrBlockedIp(rec.address)) {
                    if (!ALLOWED_INTERNAL_HOSTS.has(hostname)) {
                        throw new Error(`Hostname '${hostname}' trỏ về IP nội bộ '${rec.address}' bị chặn (SSRF).`);
                    }
                }
            }
        } catch (e) {
            if (e.message.includes('SSRF') || e.message.includes('bị chặn')) throw e;
            if (ALLOW_PRIVATE_BOT_IPS && (e.code === 'ENOTFOUND' || e.code === 'EAI_AGAIN')) {
                // Cho phép hostname nội bộ trong môi trường Docker/Wispbyte node
            } else {
                throw new Error(`Lỗi phân giải DNS cho '${hostname}': ${e.message}`);
            }
        }
    }

    url.hash = '';
    url.search = '';
    return url.toString().replace(/\/+$/, '');
}

function normalizeBotUrl(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';

    let url;
    try {
        url = new URL(raw);
    } catch (_) {
        throw new Error('URL không hợp lệ.');
    }

    if (!['http:', 'https:'].includes(url.protocol)) {
        throw new Error('URL bot phải dùng http:// hoặc https://.');
    }

    if (url.username || url.password) {
        throw new Error('URL bot không được chứa username/password.');
    }

    const hostname = url.hostname.toLowerCase();
    if (hostname === '169.254.169.254' || hostname === 'metadata.google.internal' || hostname.endsWith('.metadata.google.internal')) {
        throw new Error(`Hostname '${hostname}' bị chặn do chính sách bảo mật đám mây.`);
    }

    if (!DISABLE_SSRF_CHECK && !ALLOWED_INTERNAL_HOSTS.has(hostname)) {
        if (!ALLOW_PRIVATE_BOT_IPS && net.isIP(hostname) !== 0 && isPrivateOrBlockedIp(hostname)) {
            throw new Error(`Địa chỉ IP '${hostname}' là địa chỉ nội bộ bị chặn (SSRF).`);
        }
    }

    url.hash = '';
    url.search = '';
    return url.toString().replace(/\/+$/, '');
}

function envBotConfig() {
    const result = [];
    const seenUrls = new Set();

    const labels = String(process.env.BOT_LABELS || MANAGER_CONFIG.BOT_LABELS || '')
        .split(/[,\n]+/)
        .map(value => value.trim());

    function addEntry(rawUrl, rawLabel = '', meta = {}) {
        const value = String(rawUrl || '').trim();
        if (!value) return;

        try {
            const url = normalizeBotUrl(value);
            if (!url || seenUrls.has(url)) return;

            seenUrls.add(url);

            result.push({
                label: String(rawLabel || '').trim() || `Bot ${result.length + 1}`,
                url,
                source: 'env',
                sourceUrl: url,
                legacyNumber: Number.isSafeInteger(meta.legacyNumber)
                    ? meta.legacyNumber
                    : null
            });
        } catch (err) {
            console.error(`[CONFIG] URL bot không hợp lệ: ${value} | ${err.message}`);
        }
    }

    const newUrls = String(process.env.BOT_URLS || MANAGER_CONFIG.BOT_URLS || '')
        .split(/[,\n]+/)
        .map(value => value.trim())
        .filter(Boolean);

    if (newUrls.length) {
        newUrls.forEach((url, index) => addEntry(
            url,
            labels[index] || '',
            {}
        ));
        return result;
    }

    // Legacy compatibility: BOT1_URL/BOT2_URL/... only used when BOT_URLS is empty.
    const legacy = Object.keys(process.env)
        .map(key => {
            const match = key.match(/^BOT(\d+)_URL$/i);
            if (!match) return null;

            return {
                number: Number(match[1]),
                url: process.env[key],
                label: process.env[`BOT${match[1]}_LABEL`] || ''
            };
        })
        .filter(Boolean)
        .sort((a, b) => a.number - b.number);

    for (const item of legacy) {
        addEntry(
            item.url,
            item.label,
            { legacyNumber: item.number }
        );
    }

    return result;
}

function normalizeRegistryUrl(value) {
    try {
        return normalizeBotUrl(value);
    } catch (_) {
        return '';
    }
}

function normalizeBotRentalDisabled(value) {
    let candidates = [];
    if (Array.isArray(value)) {
        candidates = value.flatMap(item => {
            if (item && typeof item === 'object') return [item.id ?? item.botId ?? item.bot_id];
            return [item];
        });
    } else if (value && typeof value === 'object') {
        for (const field of ['ids', 'botIds', 'disabledIds', 'botRentalDisabled']) {
            if (Array.isArray(value[field])) candidates.push(...value[field]);
        }
        for (const [key, state] of Object.entries(value)) {
            if (['ids', 'botIds', 'disabledIds', 'botRentalDisabled'].includes(key)) continue;
            if (state === true || state === 1 || state === 'true' || state === 'disabled' || state?.disabled === true || state?.rentable === false) {
                candidates.push(key);
            }
        }
    }
    return [...new Set(candidates.map(Number).filter(id => Number.isSafeInteger(id) && id > 0))];
}

