// ============================================================================
// CÁC ENDPOINT XÁC THỰC (AUTH) & QUẢN LÝ NGƯỜI DÙNG (USER MANAGEMENT)
// ============================================================================

let registerLock = Promise.resolve();
function withRegisterLock(fn) {
    const run = () => supabaseAdapter?.isEnabled?.()
        ? supabaseAdapter.withManagerLock('customer-registration', fn, 900)
        : fn();
    const next = registerLock.then(run, run);
    registerLock = next.catch(() => {});
    return next;
}

async function resetBotsForAssignmentUnlocked(botIds, reason = 'reassignment') {
    if (!Array.isArray(botIds) || botIds.length === 0) return { ok: true };
    // BUG-06 (Wave B0 — recheck §7-4): PREFLIGHT toàn bộ danh sách TRƯỚC khi có side effect
    // (thu hồi quyền/reset worker). Chặn sớm nếu danh sách không thể thành công, tránh
    // trạng thái dở dang "bot 1 đã reset, bot 2 chết rồi dừng".
    // Lưu ý: reset mang tính phá hủy (không thể un-reset credential) nên "compensation"
    // ở đây là (1) chặn sớm danh sách hỏng, (2) khi fail giữa chừng — báo đúng bot nào
    // đã reset qua trạng thái bền vững pendingResets (resume được) và KHÔNG cấp bot fail.
    const preflightFailures = [];
    for (const rawId of botIds) {
        const bId = Number(rawId);
        const botConfig = BOT_CONFIG.find(c => Number(c.id) === bId);
        if (!botConfig) {
            preflightFailures.push({ botId: bId, error: 'BOT_NOT_FOUND' });
            continue;
        }
        const pending = getPendingResets()[String(bId)];
        if (pending && pending.status !== 'completed') {
            preflightFailures.push({ botId: bId, error: 'RESET_PENDING_IN_PROGRESS', resetStatus: String(pending.status || '') });
        }
    }
    if (preflightFailures.length > 0) {
        console.error(`[RESET_ASSIGN] Preflight thất bại (${reason}): ` + preflightFailures.map(p => `#${p.botId}=${p.error}`).join('; '));
        return { ok: false, error: 'RESET_PREFLIGHT_FAILED', partial: false, preflight: preflightFailures };
    }
    const sagaTransactionId = 'saga_assign_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
    let partial = false;
    const succeededBots = [];
    const pending = getPendingResets();

    for (const rawId of botIds) {
        const bId = Number(rawId);
        const botConfig = BOT_CONFIG.find(c => Number(c.id) === bId);
        if (!botConfig) continue;
        try {
            // Use the same durable state machine as the dedicated reset route so a
            // Manager restart can resume an interrupted handover instead of leaving
            // the bot half-reset. The old owner's Cloud access is revoked first.
            const begin = await beginCustomerReset(bId, `resetBotsForAssignment: ${reason}`, {
                ownerAfter: { reason, sagaTransactionId }
            });
            if (!begin.ok) {
                console.error(`[RESET_ASSIGN] Không bắt đầu được reset bot #${bId} (${reason}):`, begin.error);
                const failedError = begin.error || 'RESET_START_FAILED';
                if (succeededBots.length > 0) {
                    // §3.7 Multi-bot assignment: nếu bot 1 thành công nhưng bot 2 thất bại,
                    // lưu checkpoint transaction, giữ conflict state, không để bot mất trạng thái và ghi audit log.
                    for (const s of succeededBots) {
                        const sContext = pending[String(s.botId)] || s.context || { botId: s.botId };
                        sContext.status = 'conflict';
                        sContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                        sContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga thất bại: Bot #${s.botId} đã reset nhưng Bot #${bId} thất bại (${failedError}). Giữ conflict để tránh mất trạng thái bot.`);
                        sContext.sagaTransactionId = sagaTransactionId;
                        sContext.batchBotIds = [...botIds];
                        sContext.succeededBots = succeededBots.map(x => x.botId);
                        sContext.failedBots = [bId];
                        sContext.updatedAt = new Date().toISOString();
                        await persistPendingReset(s.botId, sContext);
                    }
                    const fContext = pending[String(bId)] || begin.existing || {
                        botId: bId,
                        resetTransactionId: 'conflict_' + bId + '_' + Date.now().toString(36),
                        resetId: 'conflict_' + bId + '_' + Date.now().toString(36),
                        createdAt: new Date().toISOString()
                    };
                    fContext.status = 'conflict';
                    fContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                    fContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga thất bại tại bot này (${failedError}) trong khi các bot khác trong cùng batch đã reset (${succeededBots.map(x => x.botId).join(', ')}). Giữ conflict để admin xử lý.`);
                    fContext.sagaTransactionId = sagaTransactionId;
                    fContext.batchBotIds = [...botIds];
                    fContext.succeededBots = succeededBots.map(x => x.botId);
                    fContext.failedBots = [bId];
                    fContext.updatedAt = new Date().toISOString();
                    await persistPendingReset(bId, fContext);

                    logAuditEvent({
                        action: 'SAGA_MULTI_BOT_ASSIGNMENT_CONFLICT',
                        target: { botIds, succeededBots: succeededBots.map(x => x.botId), failedBotId: bId },
                        details: `Multi-bot assignment saga [${sagaTransactionId}] thất bại giữa chừng: bot(s) [${succeededBots.map(x => x.botId).join(', ')}] đã reset nhưng bot #${bId} thất bại (${failedError}). Tất cả bot liên quan đã được lưu checkpoint CONFLICT để bảo toàn trạng thái; cần Admin xử lý qua /api/manager/pending-resets.`,
                        status: 'CONFLICT'
                    });
                    return {
                        ok: false,
                        conflict: true,
                        botId: bId,
                        botReset: false,
                        error: 'MULTI_BOT_ASSIGNMENT_PARTIAL_FAILURE',
                        partial: true,
                        succeededBots: succeededBots.map(x => x.botId),
                        failedBots: [bId],
                        sagaTransactionId,
                        reset: fContext
                    };
                }
                return {
                    ok: false,
                    botId: bId,
                    botReset: false,
                    error: begin.error || 'RESET_START_FAILED',
                    partial: true,
                    reset: begin.existing || null
                };
            }

            begin.context.sagaTransactionId = sagaTransactionId;
            begin.context.batchBotIds = [...botIds];
            const resetResult = await executeCustomerReset(bId, { context: begin.context });
            if (!resetResult.ok) {
                console.error(`[RESET_ASSIGN] Bot #${bId} reset thất bại khi ${reason}:`, resetResult.error || resetResult.warning);
                const failedError = resetResult.error || resetResult.warning || 'RESET_FAILED';
                if (succeededBots.length > 0) {
                    // §3.7 Multi-bot assignment: nếu bot 1 thành công nhưng bot 2 thất bại
                    for (const s of succeededBots) {
                        const sContext = pending[String(s.botId)] || s.context || { botId: s.botId };
                        sContext.status = 'conflict';
                        sContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                        sContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga thất bại: Bot #${s.botId} đã reset nhưng Bot #${bId} thất bại (${failedError}). Giữ conflict để tránh mất trạng thái bot.`);
                        sContext.sagaTransactionId = sagaTransactionId;
                        sContext.batchBotIds = [...botIds];
                        sContext.succeededBots = succeededBots.map(x => x.botId);
                        sContext.failedBots = [bId];
                        sContext.updatedAt = new Date().toISOString();
                        await persistPendingReset(s.botId, sContext);
                    }
                    const fContext = pending[String(bId)] || begin.context;
                    fContext.status = 'conflict';
                    fContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                    fContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga thất bại tại bot này (${failedError}) trong khi các bot khác trong cùng batch đã reset (${succeededBots.map(x => x.botId).join(', ')}). Giữ conflict để admin xử lý.`);
                    fContext.sagaTransactionId = sagaTransactionId;
                    fContext.batchBotIds = [...botIds];
                    fContext.succeededBots = succeededBots.map(x => x.botId);
                    fContext.failedBots = [bId];
                    fContext.updatedAt = new Date().toISOString();
                    await persistPendingReset(bId, fContext);

                    logAuditEvent({
                        action: 'SAGA_MULTI_BOT_ASSIGNMENT_CONFLICT',
                        target: { botIds, succeededBots: succeededBots.map(x => x.botId), failedBotId: bId },
                        details: `Multi-bot assignment saga [${sagaTransactionId}] thất bại giữa chừng: bot(s) [${succeededBots.map(x => x.botId).join(', ')}] đã reset nhưng bot #${bId} thất bại (${failedError}). Tất cả bot liên quan đã được lưu checkpoint CONFLICT để bảo toàn trạng thái; cần Admin xử lý qua /api/manager/pending-resets.`,
                        status: 'CONFLICT'
                    });
                    return {
                        ok: false,
                        conflict: true,
                        botId: bId,
                        botReset: false,
                        ownershipRevoked: resetResult.ownershipRevoked === true,
                        error: 'MULTI_BOT_ASSIGNMENT_PARTIAL_FAILURE',
                        partial: true,
                        succeededBots: succeededBots.map(x => x.botId),
                        failedBots: [bId],
                        sagaTransactionId,
                        resetId: resetResult.resetId
                    };
                }
                return {
                    ok: false,
                    botId: bId,
                    botReset: false,
                    ownershipRevoked: resetResult.ownershipRevoked === true,
                    error: resetResult.error || 'RESET_FAILED',
                    partial: true,
                    resetId: resetResult.resetId
                };
            }
            succeededBots.push({ botId: bId, resetId: resetResult.resetId, context: begin.context });
            if (resetResult.partial === true) partial = true;
            summaryCache.delete(bId);
            try { await refreshSummary(botConfig, true); } catch (_) {}
        } catch (e) {
            console.error(`[RESET_ASSIGN] Không thể kết nối để reset bot #${bId} khi ${reason}:`, e.message);
            if (succeededBots.length > 0) {
                for (const s of succeededBots) {
                    const sContext = pending[String(s.botId)] || s.context || { botId: s.botId };
                    sContext.status = 'conflict';
                    sContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                    sContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga thất bại: Bot #${s.botId} đã reset nhưng Bot #${bId} gặp ngoại lệ (${e.message}). Giữ conflict để tránh mất trạng thái bot.`);
                    sContext.sagaTransactionId = sagaTransactionId;
                    sContext.batchBotIds = [...botIds];
                    sContext.succeededBots = succeededBots.map(x => x.botId);
                    sContext.failedBots = [bId];
                    sContext.updatedAt = new Date().toISOString();
                    await persistPendingReset(s.botId, sContext);
                }
                const fContext = pending[String(bId)] || {
                    botId: bId,
                    resetTransactionId: 'conflict_' + bId + '_' + Date.now().toString(36),
                    resetId: 'conflict_' + bId + '_' + Date.now().toString(36),
                    createdAt: new Date().toISOString()
                };
                fContext.status = 'conflict';
                fContext.errorCode = 'MULTI_BOT_PARTIAL_FAILURE';
                fContext.lastError = sanitizeErrorMessage(`Multi-bot assignment saga gặp ngoại lệ tại bot này (${e.message}) trong khi các bot khác đã reset. Giữ conflict để admin xử lý.`);
                fContext.sagaTransactionId = sagaTransactionId;
                fContext.batchBotIds = [...botIds];
                fContext.succeededBots = succeededBots.map(x => x.botId);
                fContext.failedBots = [bId];
                fContext.updatedAt = new Date().toISOString();
                await persistPendingReset(bId, fContext);

                logAuditEvent({
                    action: 'SAGA_MULTI_BOT_ASSIGNMENT_CONFLICT',
                    target: { botIds, succeededBots: succeededBots.map(x => x.botId), failedBotId: bId },
                    details: `Multi-bot assignment saga [${sagaTransactionId}] gặp ngoại lệ khi kết nối Bot #${bId} (${e.message}) sau khi đã reset Bot(s) [${succeededBots.map(x => x.botId).join(', ')}]. Lưu checkpoint CONFLICT; cần Admin xử lý.`,
                    status: 'CONFLICT'
                });
                return {
                    ok: false,
                    conflict: true,
                    botId: bId,
                    ownershipRevoked: true,
                    error: 'MULTI_BOT_ASSIGNMENT_PARTIAL_FAILURE',
                    partial: true,
                    succeededBots: succeededBots.map(x => x.botId),
                    failedBots: [bId],
                    sagaTransactionId
                };
            }
            return { ok: false, botId: bId, ownershipRevoked: true, error: e.message, partial: true };
        }
    }
    return { ok: true, partial, succeededBots: succeededBots.map(x => x.botId) };
}

async function resetBotsForAssignment(botIds, reason = 'reassignment') {
    if (!Array.isArray(botIds) || botIds.length === 0) return { ok: true };
    if (!supabaseAdapter?.isEnabled?.()) {
        // NEW-04 (Wave B0 — recheck §5): KHÔNG nuốt lỗi. Reset local phải được worker
        // xác nhận (HTTP ok + data.ok !== false) trước khi bot được tính là đã dọn sạch.
        // Worker offline / sai secret / {ok:false} → bot KHÔNG được cấp, báo partial.
        let anyFailure = false;
        for (const rawId of botIds) {
            const bId = Number(rawId);
            const botConfig = BOT_CONFIG.find(c => Number(c.id) === bId);
            if (!botConfig) continue;
            let resetOk = false;
            try {
                const expectedTxId = crypto.randomUUID();
                const localReset = await fetchChild(botConfig, '/api/bot/reset-customer', {
                    method: 'POST',
                    body: { resetTransactionId: expectedTxId },
                    timeoutMs: 4000
                });
                resetOk = isWorkerResetPayloadConfirmed(localReset, expectedTxId);
                if (resetOk && /^[a-f0-9]{32}$/i.test(String(localReset?.data?.resetMarker || ''))) {
                    localBotResetMarkers.set(bId, String(localReset.data.resetMarker));
                }
            } catch (_) { resetOk = false; }
            if (!resetOk) {
                console.error(`[RESET_ASSIGN] Reset local Bot #${bId} không được worker xác nhận (offline/sai secret/{ok:false}) — báo thất bại, không giả thành công.`);
                anyFailure = true;
            }
        }
        // NEW-04: trả kết quả trung thực để caller chặn việc bàn giao bot chưa được dọn.
        return anyFailure
            ? { ok: false, partial: true, error: 'LOCAL_RESET_NOT_CONFIRMED' }
            : { ok: true, partial: false };
    }
    if (!supabaseStorageReady) return { ok: false, error: 'Supabase chưa sẵn sàng để khóa reset trên Cloud.', partial: true };
    try { return await supabaseAdapter.withManagerLock('bot-ownership-mutation', () => resetBotsForAssignmentUnlocked(botIds, reason), 900); }
    catch (err) { return { ok: false, error: err.message || 'Không lấy được khóa Cloud cho reset bot.', partial: true }; }
}

function resetSettingsFingerprint(row, forceCleared = false) {
    const settings = row?.settings && typeof row.settings === 'object' ? { ...row.settings } : {};
    if (settings.proxy && typeof settings.proxy === 'object') {
        settings.proxy = { ...settings.proxy, password: '' };
    }
    const proxy = row?.proxy && typeof row.proxy === 'object' ? { ...row.proxy, password: '' } : {};
    return stableJson({
        username: forceCleared ? '' : String(row?.username || ''),
        password: forceCleared ? '' : String(row?.password || ''),
        proxy,
        settings,
        schedules: row?.schedules || [],
        auto_chat: row?.auto_chat || []
    });
}

function resetContextConflict(context, existingSettings) {
    if (!context) return null;
    const syncedAuth = existingSettings?.synced_auth || {};
    if (context.resetId && String(syncedAuth.lastCustomerResetId || '') === String(context.resetId)) return null;
    const expectedFingerprint = String(context.settingsFingerprint || '');
    const beforeFingerprint = String(context.settingsFingerprintBefore || '');
    const currentFingerprint = resetSettingsFingerprint(existingSettings);
    if (expectedFingerprint && currentFingerprint === expectedFingerprint) return null;
    // An unchanged pre-clear row is still the old customer even if updated_at
    // moved because the worker saved a non-destructive setting.
    if (beforeFingerprint && currentFingerprint === beforeFingerprint) return null;
    const expectedExisted = context.settingsExisted === true;
    const expectedUpdatedAt = String(context.settingsUpdatedAt || '');
    const expectedUsername = String(context.settingsUsername || '');
    const currentUsername = String(existingSettings?.username || '');
    const currentPassword = String(existingSettings?.password || '');
    const currentProxyHost = String(existingSettings?.proxy?.host || '');
    const currentHasCustomerData = !!existingSettings && !!(currentUsername || currentPassword || currentProxyHost);
    const ownerChanged = !!expectedUsername && !!currentUsername && currentUsername !== expectedUsername;
    const appearedAfterBegin = !expectedExisted && !!existingSettings && currentHasCustomerData;
    const updatedChanged = !!expectedUpdatedAt && !!existingSettings?.updated_at && String(existingSettings.updated_at) !== expectedUpdatedAt;
    if (ownerChanged || appearedAfterBegin || updatedChanged) {
        return 'CONFLICT_NEW_OWNER: bot_settings đã thay đổi hoặc thuộc khách mới; không xóa dữ liệu mới.';
    }
    return null;
}

async function assertCustomerResetTargetSafe(botId, context) {
    if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) {
        return { ok: false, error: 'Supabase chưa sẵn sàng; không thể xác minh chủ sở hữu bot.' };
    }
    let settings = null;
    try {
        settings = await supabaseAdapter.fetchBotSettingsStrict(String(botId));
    } catch (err) {
        return { ok: false, error: 'Không đọc được bot_settings để xác minh chủ sở hữu: ' + err.message };
    }
    const syncedAuth = settings?.synced_auth || {};
    if (context?.resetId && String(syncedAuth.lastCustomerResetId || '') === String(context.resetId)) {
        context.authResetMarker = String(syncedAuth.resetMarker || context.authResetMarker || '');
        return { ok: true, resetCompleted: true, resetMarker: context.authResetMarker };
    }
    if (/^user-lifecycle:/.test(String(context?.requestedBy || ''))) {
        let users;
        try { users = await loadUsersFreshOrThrow(); }
        catch (err) { return { ok: false, error: 'Không xác minh được chủ sở hữu bot trước reset: ' + err.message }; }
        const activeOwner = users.find(user => user.role !== 'admin' && isActiveUserEntitlement(user) &&
            Array.isArray(user.assignedBotIds) && user.assignedBotIds.some(id => Number(id) === Number(botId)));
        if (activeOwner) return { ok: false, conflict: true, error: 'BOT_LEASE_ACTIVE: bot đã có lease hiệu lực của ' + activeOwner.username + '; reset bị dừng.' };
    }
    const conflict = resetContextConflict(context, settings);
    if (conflict) return { ok: false, conflict: true, error: conflict };
    return { ok: true };
}

// Thu hồi một bot khỏi tất cả người dùng (assignedBotIds), bot_aliases, session và auth cache Cloud.
// Đọc lại users/sessions/settings từ Cloud trước khi ghi để không dựa vào cache RAM đã cũ.
async function revokeBotOwnership(botId, options = {}) {
    const context = options && typeof options.context === 'object' ? options.context : null;
    const bId = Number(botId);
    let usersModified = false;
    let usersSaved = false;
    let sessionsModified = false;
    let sessionsSaved = false;
    let settingsSaved = false;
    const fail = (error, extra = {}) => ({
        ok: false,
        error,
        usersModified,
        usersSaved,
        sessionsModified,
        sessionsSaved,
        settingsSaved,
        partial: true,
        ...extra
    });
    if (!Number.isSafeInteger(bId) || bId <= 0) return fail('BOT_ID không hợp lệ');
    if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) {
        return fail('Supabase chưa sẵn sàng; không thể thu hồi quyền trên Cloud.');
    }
    try {
        const [cloudUsers, cloudSessions] = await Promise.all([
            loadUsersFreshOrThrow(),
            supabaseAdapter.fetchSessions()
        ]);
        if (!Array.isArray(cloudUsers) || !Array.isArray(cloudSessions)) {
            return fail('Không đọc được đầy đủ users/sessions từ Cloud; chưa thu hồi quyền.');
        }
        const assignmentFlow = /^(?:allocateBotsForUser|resetBotsForAssignment):/.test(String(context?.requestedBy || ''));
        if (assignmentFlow) {
            const activeOwner = cloudUsers.find(user => {
                if (!user || user.role === 'admin' || user.status !== 'active' || !Array.isArray(user.assignedBotIds) || !user.assignedBotIds.some(id => Number(id) === bId)) return false;
                const expiry = user.expiresAt ? Date.parse(user.expiresAt) : Infinity;
                return !Number.isFinite(expiry) || expiry > Date.now();
            });
            if (activeOwner) return fail('BOT_LEASE_ACTIVE: bot còn lease hiệu lực của ' + activeOwner.username + '; không reset hoặc thu hồi.', { activeOwner: activeOwner.username });
        }
        let existingSettings = null;
        try {
            existingSettings = await supabaseAdapter.fetchBotSettingsStrict(String(bId));
        } catch (err) {
            return fail('Không đọc được bot_settings từ Cloud; chưa thu hồi quyền: ' + err.message);
        }

        // A retry must never wipe data that belongs to a newly assigned customer.
        const contextConflict = resetContextConflict(context, existingSettings);
        if (contextConflict) {
            return fail(contextConflict, { conflict: true });
        }

        const allowedUserIds = new Set((context?.ownerUserIds || []).map(id => String(id)));
        const allowedUsernames = new Set((context?.ownerUsernames || []).map(name => String(name || '').toLowerCase()));
        const isCapturedOwner = (user) => {
            if (!context) return true;
            if (user.id !== undefined && user.id !== null && String(user.id) !== '') {
                return allowedUserIds.has(String(user.id));
            }
            // Only fall back to username for legacy rows without a stable id.
            return allowedUsernames.has(String(user.username || '').toLowerCase());
        };

        for (const user of cloudUsers) {
            if (!user) continue;
            // Admin giữ quyền quản trị toàn bộ bot; chỉ khách thuê bị gỡ assignedBotIds.
            if (user.role === 'admin' || !isCapturedOwner(user)) continue;
            let changed = false;
            if (Array.isArray(user.assignedBotIds)) {
                const original = user.assignedBotIds.length;
                if (original > 0) {
                    user.botCount = Math.max(parseInt(user.botCount, 10) || 1, original);
                }
                user.assignedBotIds = user.assignedBotIds.filter(id => Number(id) !== bId);
                if (user.assignedBotIds.length !== original) changed = true;
            }
            if (user.botAliases && typeof user.botAliases === 'object' && String(bId) in user.botAliases) {
                delete user.botAliases[String(bId)];
                changed = true;
            }
            if (changed) {
                usersModified = true;
                user.updatedAt = new Date().toISOString();
            }
        }
        usersSaved = true;
        if (usersModified) {
            usersSaved = await saveUsers(cloudUsers);
            if (!usersSaved) {
                return fail('Không lưu được users đã thu hồi lên Cloud; chưa reset bot.');
            }
        } else {
            setUsersCache(cloudUsers);
        }

        if (context) {
            context.steps = context.steps || {};
            context.steps.users = true;
            if (!(await persistPendingReset(bId, context))) return fail('Users đã thu hồi nhưng không lưu được checkpoint Cloud; reset đã dừng để phục hồi an toàn.', { checkpointFailed: 'users' });
        }
        const now = Date.now();
        const cloudSessionsByHash = new Map();
        for (const sessionItem of cloudSessions) {
            const tokenHash = String(sessionItem?.tokenHash || '').trim();
            if (!tokenHash || Number(sessionItem.expiresAt) <= now) continue;
            cloudSessionsByHash.set(tokenHash, { ...sessionItem, tokenHash });
        }
        const allowedSessionHashes = new Set((context?.sessionTokenHashes || []).map(token => String(token)));
        const sessionBelongsToCapturedOwner = (sessionItem) => {
            if (!context) return true;
            const tokenHash = String(sessionItem?.tokenHash || '').trim();
            if (tokenHash && allowedSessionHashes.has(tokenHash)) return true;
            const userId = String(sessionItem?.userId || '');
            const username = String(sessionItem?.username || '').toLowerCase();
            return allowedUserIds.has(userId) || allowedUsernames.has(username);
        };
        const revokedSessionHashes = new Set();
        for (const [tokenHash, sessionItem] of cloudSessionsByHash.entries()) {
            if (!sessionBelongsToCapturedOwner(sessionItem)) continue;
            if (Array.isArray(sessionItem.assignedBotIds) && sessionItem.assignedBotIds.some(id => Number(id) === bId)) {
                revokedSessionHashes.add(tokenHash);
            }
        }
        for (const [tokenHash, sessionItem] of activeSessions.entries()) {
            if (!sessionItem || Number(sessionItem.expiresAt) <= now) continue;
            if (!sessionBelongsToCapturedOwner({ ...sessionItem, tokenHash })) continue;
            if (Array.isArray(sessionItem.assignedBotIds) && sessionItem.assignedBotIds.some(id => Number(id) === bId)) {
                revokedSessionHashes.add(tokenHash);
            }
        }
        const sessionsToSave = new Map();
        for (const tokenHash of revokedSessionHashes) {
            // Cloud session là nguồn chuẩn; chỉ dùng session RAM khi Cloud chưa có token đó.
            const baseSession = cloudSessionsByHash.get(tokenHash) || activeSessions.get(tokenHash);
            if (!baseSession) continue;
            const currentIds = Array.isArray(baseSession.assignedBotIds) ? baseSession.assignedBotIds : [];
            const updated = { ...baseSession, tokenHash, assignedBotIds: currentIds.filter(id => Number(id) !== bId) };
            sessionsModified = true;
            sessionsToSave.set(tokenHash, updated);
        }
        sessionsSaved = true;
        if (sessionsModified) {
            sessionsSaved = await supabaseAdapter.syncAllSessions(sessionsToSave);
            if (!sessionsSaved) {
                return fail('Không lưu được sessions đã thu hồi lên Cloud; chưa reset bot.');
            }
            for (const [tokenHash, updated] of sessionsToSave.entries()) {
                if (activeSessions.has(tokenHash)) activeSessions.set(tokenHash, { ...updated });
                persistedSessionHashes.add(tokenHash);
            }
        }

        if (context) {
            context.steps = context.steps || {};
            context.steps.sessions = true;
            if (!(await persistPendingReset(bId, context))) return fail('Sessions đã thu hồi nhưng không lưu được checkpoint Cloud; reset đã dừng để phục hồi an toàn.', { checkpointFailed: 'sessions' });
        }

        try {
            const cleared = {
                bot_id: String(bId),
                username: '',
                password: '',
                clearCredentials: true,
                clearProxyPassword: true,
                settings: existingSettings?.settings || {},
                proxy: existingSettings?.proxy || {},
                schedules: existingSettings?.schedules || [],
                auto_chat: existingSettings?.auto_chat || [],
                syncedAuth: {
                    ...(existingSettings?.synced_auth || {}),
                    managerBotId: null,
                    adminPasswordHash: null,
                    users: [],
                    pendingCustomerResetId: context?.resetId || existingSettings?.synced_auth?.pendingCustomerResetId || null,
                    updatedAt: new Date().toISOString()
                },
                manuallyStopped: true,
                manually_stopped: true
            };
            settingsSaved = await supabaseAdapter.saveBotSettings(String(bId), cleared);
            if (!settingsSaved) console.error('[RESET_ASSIGN] Không thể ghi bot_settings đã thu hồi lên Supabase.');
        } catch (e) {
            settingsSaved = false;
            console.error('[RESET_ASSIGN] Lỗi thu hồi bot_settings trên Supabase:', e.message);
        }

        if (context && settingsSaved) {
            context.steps = context.steps || {};
            context.steps.settings = true;
            if (!(await persistPendingReset(bId, context))) return fail('bot_settings đã ghi ý định reset nhưng không lưu được checkpoint Cloud; reset đã dừng để phục hồi an toàn.', { checkpointFailed: 'settings' });
        }
        const ok = usersSaved && sessionsSaved && settingsSaved;
        return { ok, usersModified, sessionsModified, usersSaved, sessionsSaved, settingsSaved, partial: !ok };
    } catch (err) {
        console.error('[RESET_ASSIGN] Lỗi thu hồi ownership bot #' + bId + ':', err.message);
        return fail(err.message);
    }
}

// ---------------------------------------------------------------------------
// Persistent customer-reset state machine.
// pendingResets lives inside the existing registry JSON blob, so no DB schema
// change is required. Each step is idempotent and retried after a Manager
// restart or transient Cloud/worker failure.
// ---------------------------------------------------------------------------
const customerResetLocks = new Set();

function getPendingResets() {
    if (!registry.pendingResets || typeof registry.pendingResets !== 'object' || Array.isArray(registry.pendingResets)) {
        registry.pendingResets = {};
    }
    return registry.pendingResets;
}

async function persistPendingReset(botId, context) {
    if (!context) return false;
    const pending = getPendingResets();
    pending[String(Number(botId))] = context;
    return await saveRegistry();
}

async function persistPendingResetOrThrow(botId, context) {
    let saved = false;
    try { saved = await persistPendingReset(botId, context); } catch (_) {}
    if (!saved) throw new Error('RESET_CHECKPOINT_SAVE_FAILED: không xác nhận được checkpoint reset trên Supabase.');
    return true;
}

const SAGA_RESET_STATES = Object.freeze({
    PENDING: 'pending',
    RUNNING: 'running',
    WAITING_WORKER: 'waiting_worker',
    CONFLICT: 'conflict',
    COMPLETED: 'completed',
    FAILED_RETRIABLE: 'failed_retriable',
    NEEDS_ADMIN: 'needs_admin'
});

async function beginCustomerReset(botId, requestedBy = 'admin', options = {}) {
    const bId = Number(botId);
    const key = String(bId);
    if (!Number.isSafeInteger(bId) || bId <= 0) return { ok: false, error: 'BOT_ID không hợp lệ' };
    if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) {
        return { ok: false, error: 'Supabase chưa sẵn sàng; không thể bắt đầu reset an toàn.' };
    }
    const pending = getPendingResets();
    const existing = pending[key];
    const previousPending = existing ? JSON.parse(JSON.stringify(existing)) : null;
    const isRunning = customerResetLocks.has(key) ||
        (existing && (existing.status === 'running' || existing.status === 'in_progress' || existing.status === 'waiting_worker') && Number(existing.leaseUntil || 0) > Date.now());
    if (isRunning) {
        return { ok: false, conflict: true, error: 'Đang có một tiến trình reset khác chạy trên bot này.', existing };
    }
    if (existing && existing.status === 'conflict') return { ok: false, conflict: true, error: 'Reset đang ở trạng thái conflict và cần quản trị viên xử lý.', existing };
    if (existing && existing.status === 'needs_admin') return { ok: false, conflict: true, error: 'Reset đang ở trạng thái needs_admin và cần quản trị viên xử lý.', existing };
    if (existing && existing.status !== 'completed') {
        customerResetLocks.add(key);
        existing.status = 'running';
        existing.leaseUntil = Date.now() + 10 * 60 * 1000;
        existing.attempts = Number(existing.attempts || 0) + 1;
        existing.updatedAt = new Date().toISOString();
        if (!(await persistPendingReset(bId, existing))) {
            customerResetLocks.delete(key);
            return { ok: false, error: 'Không lưu được checkpoint để tiếp tục giao dịch reset đang chờ.', existing };
        }
        return { ok: true, context: existing, resumed: true };
    }
    if (existing && existing.status === 'completed') {
        delete pending[key];
        if (!(await saveRegistry())) { pending[key] = previousPending; return { ok: false, error: 'Không dọn được checkpoint reset đã hoàn tất.' }; }
    }
    customerResetLocks.add(key);
    try {
        const [cloudUsers, cloudSessions] = await Promise.all([
            supabaseAdapter.fetchUsers(),
            supabaseAdapter.fetchSessions()
        ]);
        if (!Array.isArray(cloudUsers) || !Array.isArray(cloudSessions)) {
            throw new Error('Không đọc được đầy đủ users/sessions từ Cloud; chưa bắt đầu reset.');
        }
        let settings = null;
        try {
            settings = await supabaseAdapter.fetchBotSettingsStrict(String(bId));
        } catch (err) {
            throw new Error('Không đọc được bot_settings từ Cloud; chưa bắt đầu reset: ' + err.message);
        }
        const cloudPendingId = String(settings?.synced_auth?.pendingCustomerResetId || '');
        if (cloudPendingId && cloudPendingId !== String(existing?.resetTransactionId || existing?.resetId || '')) {
            throw new Error('Cloud vẫn có giao dịch reset đang chờ xử lý: ' + cloudPendingId);
        }
        const assignmentFlow = /^(?:allocateBotsForUser|resetBotsForAssignment):/.test(String(requestedBy || ''));
        if (assignmentFlow) {
            const activeOwner = cloudUsers.find(user => {
                if (!user || user.role === 'admin' || user.status !== 'active' || !Array.isArray(user.assignedBotIds) || !user.assignedBotIds.some(id => Number(id) === bId)) return false;
                const expiry = user.expiresAt ? Date.parse(user.expiresAt) : Infinity;
                return !Number.isFinite(expiry) || expiry > Date.now();
            });
            if (activeOwner) throw new Error('BOT_LEASE_ACTIVE: bot còn lease hiệu lực của ' + activeOwner.username + '; không reset hoặc thu hồi.');
        }
        const lifecycleFlow = /^user-lifecycle:/.test(String(requestedBy || ''));
        if (lifecycleFlow) {
            const activeOwner = cloudUsers.find(user => user.role !== 'admin' && isActiveUserEntitlement(user) &&
                Array.isArray(user.assignedBotIds) && user.assignedBotIds.some(id => Number(id) === bId));
            if (activeOwner) {
                customerResetLocks.delete(key);
                return { ok: true, skipReset: true, activeOwner: activeOwner.username };
            }
        }
        const ownerUserIds = [];
        const ownerUsernames = [];
        for (const user of cloudUsers) {
            if (!user || user.role === 'admin') continue;
            if (Array.isArray(user.assignedBotIds) && user.assignedBotIds.some(id => Number(id) === bId)) {
                if (user.id !== undefined && user.id !== null && String(user.id) !== '') ownerUserIds.push(String(user.id));
                if (String(user.username || '').trim()) ownerUsernames.push(String(user.username).trim());
            }
        }
        const now = Date.now();
        const sessionTokenHashes = new Set();
        for (const sessionItem of cloudSessions) {
            if (!sessionItem || Number(sessionItem.expiresAt) <= now) continue;
            if (Array.isArray(sessionItem.assignedBotIds) && sessionItem.assignedBotIds.some(id => Number(id) === bId)) {
                sessionTokenHashes.add(String(sessionItem.tokenHash || ''));
            }
        }
        for (const sessionItem of activeSessions.values()) {
            if (!sessionItem || Number(sessionItem.expiresAt) <= now) continue;
            if (Array.isArray(sessionItem.assignedBotIds) && sessionItem.assignedBotIds.some(id => Number(id) === bId)) {
                sessionTokenHashes.add(String(sessionItem.tokenHash || ''));
            }
        }
        const resetTransactionId = 'reset_' + bId + '_' + now.toString(36) + '_' + Math.random().toString(36).slice(2, 6);
        const context = {
            resetId: resetTransactionId,
            resetTransactionId,
            botId: bId,
            requestedBy: String(requestedBy || 'admin'),
            requestedAt: new Date(now).toISOString(),
            createdAt: new Date(now).toISOString(),
            updatedAt: new Date(now).toISOString(),
            completedAt: null,
            ownerBefore: {
                userIds: ownerUserIds,
                usernames: ownerUsernames,
                username: ownerUsernames[0] || null
            },
            ownerAfter: options.ownerAfter || null,
            ownerUserIds,
            ownerUsernames,
            sessionTokenHashes: [...sessionTokenHashes],
            settingsExisted: !!settings,
            settingsUpdatedAt: String(settings?.updated_at || ''),
            settingsUsername: String(settings?.username || ''),
            fingerprint: resetSettingsFingerprint(settings, true),
            settingsFingerprint: resetSettingsFingerprint(settings, true),
            settingsFingerprintBefore: resetSettingsFingerprint(settings, false),
            revision: Number(settings?.synced_auth?.authRevision || 0),
            steps: { users: false, settings: false, sessions: false, botReset: false, authSync: false },
            currentStep: 'pending',
            status: 'pending',
            attempts: 0,
            maxAttempts: 5,
            leaseUntil: now + 10 * 60 * 1000,
            errorCode: null,
            lastError: ''
        };
        pending[key] = context;
        const saved = await saveRegistry();
        if (!saved) {
            delete pending[key];
            throw new Error('Không lưu được trạng thái reset lên Cloud; chưa thay đổi dữ liệu.');
        }
        return { ok: true, context };
    } catch (err) {
        customerResetLocks.delete(key);
        if (previousPending) pending[key] = previousPending;
        else delete pending[key];
        return { ok: false, error: err.message };
    }
}

async function executeCustomerReset(botId, options = {}) {
    const bId = Number(botId);
    const key = String(bId);
    if (!options?.context) return { ok: false, status: 500, error: 'Thiếu reset context.' };
    try {
        if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) throw new Error('Supabase chưa sẵn sàng để khóa reset trên Cloud.');
        return await supabaseAdapter.withManagerLock('customer-reset-' + bId, () =>
            supabaseAdapter.withManagerLock('bot-auth-sync-' + bId, () => executeCustomerResetCore(bId, { ...options, distributedAuthLockHeld: true }), 900), 900);
    } catch (err) {
        customerResetLocks.delete(key);
        const context = options.context;
        context.status = 'failed_retriable';
        context.errorCode = 'LOCK_OR_EXECUTION_FAILED';
        context.lastError = sanitizeErrorMessage(err.message);
        context.leaseUntil = 0;
        context.updatedAt = new Date().toISOString();
        try { await persistPendingReset(bId, context); } catch (_) {}
        return { ok: false, status: 503, partial: true, resetId: context.resetId, resetTransactionId: context.resetTransactionId, errorCode: context.errorCode, error: err.message };
    }
}

async function executeCustomerResetCore(botId, options = {}) {
    const bId = Number(botId);
    const key = String(bId);
    const context = options.context;
    const botConfig = (typeof BOT_CONFIG !== 'undefined' ? BOT_CONFIG : []).find(bot => Number(bot.id) === bId) || null;
    if (!context) return { ok: false, status: 500, error: 'Thiếu reset context.' };
    try {
        context.status = 'running';
        context.currentStep = 'revoke_ownership';
        context.updatedAt = new Date().toISOString();
        if (!(context.steps.users && context.steps.settings && context.steps.sessions)) {
            const revoke = await revokeBotOwnership(bId, { context });
            if (revoke.usersSaved) context.steps.users = true;
            if (revoke.settingsSaved) context.steps.settings = true;
            if (revoke.sessionsSaved) context.steps.sessions = true;
            if (revoke.conflict) {
                context.status = 'conflict';
                context.errorCode = 'REVOKE_CONFLICT';
                context.lastError = sanitizeErrorMessage(revoke.error);
                context.leaseUntil = 0;
                context.updatedAt = new Date().toISOString();
                await persistPendingResetOrThrow(bId, context);
                return {
                    ok: false,
                    status: 409,
                    partial: true,
                    conflict: true,
                    resetId: context.resetId,
                    resetTransactionId: context.resetTransactionId,
                    errorCode: context.errorCode,
                    error: revoke.error,
                    revoke
                };
            }
            if (!revoke.ok) {
                context.attempts = Number(context.attempts || 0) + 1;
                context.status = context.attempts >= (context.maxAttempts || 5) ? 'needs_admin' : 'failed_retriable';
                context.errorCode = 'REVOKE_FAILED';
                context.lastError = sanitizeErrorMessage(revoke.error || 'REVOKE_FAILED');
                context.leaseUntil = 0;
                context.updatedAt = new Date().toISOString();
                await persistPendingResetOrThrow(bId, context);
                return {
                    ok: false,
                    status: 502,
                    partial: true,
                    step: 'revoke-before-reset',
                    resetId: context.resetId,
                    resetTransactionId: context.resetTransactionId,
                    errorCode: context.errorCode,
                    error: revoke.error || 'REVOKE_FAILED',
                    revoke
                };
            }
            await persistPendingResetOrThrow(bId, context);
        }

        if (!context.steps.botReset) {
            if (!botConfig) {
                context.steps.botReset = true;
                context.steps.authSync = true;
            } else {
                // Re-check immediately before the destructive worker reset. A new
                // customer may have been configured while an earlier step failed.
                const safety = await assertCustomerResetTargetSafe(bId, context);
                if (!safety.ok) {
                    context.attempts = Number(context.attempts || 0) + 1;
                    context.status = safety.conflict ? 'conflict' : (context.attempts >= (context.maxAttempts || 5) ? 'needs_admin' : 'failed_retriable');
                    context.errorCode = safety.conflict ? 'SAFETY_CONFLICT' : 'SAFETY_CHECK_FAILED';
                    context.lastError = sanitizeErrorMessage(safety.error);
                    context.leaseUntil = 0;
                    context.updatedAt = new Date().toISOString();
                    await persistPendingResetOrThrow(bId, context);
                    return {
                        ok: false,
                        status: safety.conflict ? 409 : 502,
                        partial: true,
                        conflict: !!safety.conflict,
                        resetId: context.resetId,
                        resetTransactionId: context.resetTransactionId,
                        errorCode: context.errorCode,
                        error: safety.error,
                        warning: 'Đã dừng trước bước reset bot vì không xác minh được bot vẫn thuộc khách cũ.'
                    };
                }
                context.status = 'waiting_worker';
                context.currentStep = 'bot_reset';
                context.updatedAt = new Date().toISOString();
                await persistPendingReset(bId, context).catch(() => {});

                let botResult = await runChildAction(bId, '/api/bot/reset-customer', { resetTransactionId: context.resetTransactionId || context.resetId }, {}, 'POST', { timeoutMs: 45000 });
                if (safety.resetCompleted === true && (!botResult.ok || botResult.data?.ok !== true)) {
                    // Cloud proves the reset committed; retrying the same transaction on Worker only refreshes cleanup status.
                    botResult = { ok: true, status: 200, data: { ok: true, alreadyReset: true, partial: true, resetMarker: safety.resetMarker } };
                } else if (!botResult.ok || botResult.data?.ok !== true) {
                    // The Worker may have committed Cloud state before the response was lost.
                    try {
                        const committed = await supabaseAdapter.fetchBotSettingsStrict(String(bId));
                        if (String(committed?.synced_auth?.lastCustomerResetId || '') === String(context.resetTransactionId || context.resetId)) {
                            botResult = { ok: true, status: 200, data: { ok: true, alreadyReset: true, partial: true, resetMarker: committed?.synced_auth?.resetMarker || '' } };
                        }
                    } catch (_) {}
                }
                const botResetOk = !!(botResult.ok && botResult.data?.ok === true);
                if (!botResetOk) {
                    context.attempts = Number(context.attempts || 0) + 1;
                    const isPermanent = botResult.status === 401 || botResult.status === 403;
                    context.status = isPermanent ? 'needs_admin' : (context.attempts >= (context.maxAttempts || 5) ? 'needs_admin' : 'failed_retriable');
                    context.errorCode = isPermanent ? 'WORKER_AUTH_FORBIDDEN' : 'WORKER_RESET_FAILED';
                    context.lastError = sanitizeErrorMessage(botResult.data?.error || 'WORKER_RESET_FAILED');
                    context.leaseUntil = 0;
                    context.updatedAt = new Date().toISOString();
                    await persistPendingResetOrThrow(bId, context);
                    return {
                        ok: false,
                        status: botResult.status || 502,
                        partial: true,
                        ownershipRevoked: true,
                        authSynced: false,
                        resetId: context.resetId,
                        resetTransactionId: context.resetTransactionId,
                        errorCode: context.errorCode,
                        error: context.lastError,
                        warning: 'Quyền Cloud của khách cũ đã được thu hồi, nhưng bot chưa reset thành công.',
                        data: botResult.data
                    };
                }
                context.steps.botReset = true;
                if (/^[a-f0-9]{32}$/i.test(String(botResult.data?.resetMarker || ''))) {
                    context.authResetMarker = String(botResult.data.resetMarker);
                }
                if (botResult.data?.partial === true) context.partialLogs = true;
                await persistPendingResetOrThrow(bId, context);
            }
        }

        if (!context.steps.authSync) {
            if (!botConfig) {
                context.steps.authSync = true;
            } else {
                context.status = 'waiting_worker';
                context.currentStep = 'auth_sync';
                context.updatedAt = new Date().toISOString();
                const authSync = await syncAuthToBotAfterOwnershipChange(botConfig, { resetMarker: context.authResetMarker, pendingCustomerResetId: null, distributedAuthLockHeld: true });
                if (authSync?.ok === true) {
                    context.steps.authSync = true;
                } else {
                    context.attempts = Number(context.attempts || 0) + 1;
                    const syncCode = lastAuthSyncStatusCodes.get(bId);
                    const isPermanent = syncCode === 401 || syncCode === 403;
                    context.status = isPermanent ? 'needs_admin' : (context.attempts >= (context.maxAttempts || 5) ? 'needs_admin' : 'failed_retriable');
                    context.errorCode = isPermanent ? 'AUTH_SYNC_FORBIDDEN' : 'AUTH_SYNC_FAILED';
                    context.lastError = sanitizeErrorMessage(authSync?.error || 'AUTH_SYNC_FAILED');
                    context.leaseUntil = 0;
                    context.updatedAt = new Date().toISOString();
                    await enqueueOutboxSync(bId, { type: 'auth_sync', committedTransaction: { type: 'CUSTOMER_RESET', target: bId } });
                    await persistPendingResetOrThrow(bId, context);
                    return {
                        ok: true,
                        status: 200,
                        partial: true,
                        coreCommitted: true,
                        syncStatus: 'pending_retry',
                        ownershipRevoked: true,
                        authSynced: false,
                        resetId: context.resetId,
                        resetTransactionId: context.resetTransactionId,
                        errorCode: context.errorCode,
                        authSyncError: context.lastError,
                        warning: 'Bot đã reset và quyền Cloud đã thu hồi, nhưng worker chưa xác nhận auth-sync. Hệ thống sẽ thử lại định kỳ.'
                    };
                }
                await persistPendingResetOrThrow(bId, context);
            }
        }

        const cloudSettings = await supabaseAdapter.fetchBotSettingsStrict(String(bId));
        if (!cloudSettings) throw new Error('Không đọc được bot_settings để hoàn tất checkpoint reset.');
        const cloudAuth = { ...(cloudSettings.synced_auth || {}) };
        const pendingResetId = String(cloudAuth.pendingCustomerResetId || '');
        if (pendingResetId && pendingResetId !== String(context.resetTransactionId || context.resetId)) throw new Error('Cloud có pending reset ID khác; giữ nguyên checkpoint để tránh ghi đè.');
        if (pendingResetId) {
            delete cloudAuth.pendingCustomerResetId;
            if (!(await supabaseAdapter.saveBotSettings(String(bId), { ...cloudSettings, syncedAuth: cloudAuth }))) throw new Error('Không xóa được pending reset marker trên Cloud.');
        }
        context.status = 'completed';
        context.currentStep = 'done';
        context.completedAt = new Date().toISOString();
        context.updatedAt = new Date().toISOString();
        context.leaseUntil = 0;
        context.errorCode = null;
        context.lastError = '';
        const pending = getPendingResets();
        pending[key] = context;
        // Mark completion durably before deleting the record. If the process
        // dies here, resume sees status=completed and will not reset the bot a
        // second time; it only removes the stale completed marker.
        const marked = await persistPendingResetOrThrow(bId, context);
        let removed = false;
        if (marked) {
            delete pending[key];
            removed = await saveRegistry().catch(() => false);
            if (!removed) pending[key] = context;
        }
        const statePersisted = marked && removed;
        return {
            ok: true,
            status: 200,
            partial: !!context.partialLogs || !statePersisted,
            coreCommitted: true,
            syncStatus: 'synced',
            ownershipRevoked: true,
            authSynced: true,
            resetId: context.resetId,
            resetTransactionId: context.resetTransactionId,
            statePersisted,
            warning: statePersisted ? undefined : 'Reset đã xong nhưng chưa xác nhận xóa xong trạng thái tạm trên Cloud; sẽ dọn lại khi Manager khởi động.',
            message: 'Đã reset bàn giao bot và thu hồi quyền khách cũ thành công.'
        };
    } catch (err) {
        context.attempts = Number(context.attempts || 0) + 1;
        context.status = context.attempts >= (context.maxAttempts || 5) ? 'needs_admin' : 'failed_retriable';
        context.errorCode = 'CORE_RESET_EXCEPTION';
        context.lastError = sanitizeErrorMessage(err.message);
        context.leaseUntil = 0;
        context.updatedAt = new Date().toISOString();
        await persistPendingReset(bId, context).catch(() => false);
        return { ok: false, status: 502, partial: true, resetId: context.resetId, resetTransactionId: context.resetTransactionId, errorCode: context.errorCode, error: err.message };
    } finally {
        customerResetLocks.delete(key);
    }
}

async function runCustomerResetTransaction(botId, requestedBy = 'admin') {
    if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) {
        const targetBot = getBotConfig(botId);
        if (!targetBot) {
            return { begin: { ok: false, error: `Bot #${botId} không tồn tại trong cấu hình.` }, resetResult: { ok: false, error: 'BOT_NOT_FOUND' } };
        }
        try {
            // Audit v2 §3.5 & NEW-04: Bắt buộc AWAIT worker xác nhận reset thành công.
            // Tuyệt đối không fire-and-forget hoặc trả giả thành công khi chưa xóa được credential.
            const res = await fetchChild(targetBot, '/api/bot/reset-customer', {
                method: 'POST',
                body: { offlineLocalReset: true, requestedBy, resetId: `local_${Date.now()}_${Math.random().toString(36).slice(2, 8)}` },
                timeoutMs: 4000
            });
            if (res && res.ok && res.data && res.data.ok === true) {
                return { begin: { ok: true, context: { botId, localConfirmed: true, resetId: res.data.resetId }, skipped: false }, resetResult: { ok: true, confirmed: true, data: res.data } };
            }
            const errMsg = res?.data?.error || res?.statusText || (res ? `HTTP ${res.status}` : 'Không nhận được phản hồi từ Worker');
            console.error(`[RESET_LOCAL] Worker Bot #${botId} từ chối reset: ${errMsg}`);
            return { begin: { ok: false, error: `Worker bot #${botId} từ chối reset: ${errMsg}` }, resetResult: { ok: false, offline: true, error: errMsg } };
        } catch (err) {
            console.error(`[RESET_LOCAL] Lỗi kết nối tới Worker Bot #${botId}: ${err.message}`);
            return { begin: { ok: false, error: `Lỗi kết nối tới Worker bot #${botId}: ${err.message}` }, resetResult: { ok: false, offline: true, error: err.message } };
        }
    }
    try {
        return await supabaseAdapter.withManagerLock('bot-ownership-mutation', async () => {
            const begin = await beginCustomerReset(botId, requestedBy);
            if (!begin.ok) return { begin, resetResult: null };
            if (begin.skipReset === true) return { begin, resetResult: { ok: true, skipped: true } };
            const resetResult = await executeCustomerReset(botId, { context: begin.context });
            return { begin, resetResult };
        }, 900);
    } catch (err) {
        return { begin: { ok: false, error: err.message || 'Không lấy được khóa reset Cloud.' }, resetResult: null };
    }
}

// V3-07: Canonical Entitlement Normalizer
function normalizeEntitlement(user) {
    if (!user || typeof user !== 'object') {
        return { isPermanent: false, expiresAt: null, isActive: false, status: 'disabled' };
    }
    const status = String(user.status || 'active').trim().toLowerCase();
    const isPermanent = Boolean(user.isPermanent === true || user.is_permanent === true || (!user.expiresAt && String(user.status || 'active').toLowerCase() === 'active' && (user.role === 'admin' || /vĩnh viễn|permanent|lifetime|vip/i.test(String(user.planName || '')) || user.expiresAt === null)));
    let expiresAt = null;
    if (!isPermanent && user.expiresAt) {
        const parsed = Date.parse(user.expiresAt);
        if (Number.isFinite(parsed)) {
            expiresAt = new Date(parsed).toISOString();
        }
    }
    const now = Date.now();
    let isActive = false;
    if (status === 'active') {
        if (user.role === 'admin' || isPermanent) {
            isActive = true;
        } else if (expiresAt) {
            isActive = Date.parse(expiresAt) > now;
        } else {
            // Không permanent mà thiếu expiresAt -> KHÔNG active (V3-07)
            isActive = false;
        }
    }
    return { isPermanent, expiresAt, isActive, status };
}

function isActiveUserEntitlement(user, now = Date.now()) {
    if (!user) return false;
    const status = String(user.status || 'active').trim().toLowerCase();
    if (status !== 'active') return false;
    if (user.role === 'admin') return true;
    const isPermanent = Boolean(user.isPermanent === true || user.is_permanent === true || (!user.expiresAt && (user.role === 'admin' || /vĩnh viễn|permanent|lifetime|vip/i.test(String(user.planName || '')) || user.expiresAt === null)));
    if (isPermanent) return true;
    if (!user.expiresAt) return false;
    const expiry = Date.parse(user.expiresAt);
    return Number.isFinite(expiry) && expiry > now;
}

async function reconcileUserBotLifecycle(previousUser, nextUser, reason = 'user lifecycle change') {
    const previousBots = Array.isArray(previousUser?.assignedBotIds) ? [...new Set(previousUser.assignedBotIds.map(Number).filter(Number.isSafeInteger))] : [];
    const nextBots = Array.isArray(nextUser?.assignedBotIds) ? new Set(nextUser.assignedBotIds.map(Number)) : new Set();
    const nextIsActive = isActiveUserEntitlement(nextUser);
    const retire = nextIsActive ? previousBots.filter(botId => !nextBots.has(botId)) : previousBots;
    let partial = false;
    const failedBots = [];
    for (const botId of retire) {
        const latestUsers = await loadUsersFreshOrThrow();
        const targetId = String(previousUser?.id || '');
        const targetName = String(previousUser?.username || '').toLowerCase();
        const otherOwner = latestUsers.find(user => {
            const sameUser = (targetId && String(user.id || '') === targetId) ||
                (targetName && String(user.username || '').toLowerCase() === targetName);
            return !sameUser && isActiveUserEntitlement(user) &&
                Array.isArray(user.assignedBotIds) && user.assignedBotIds.some(id => Number(id) === botId);
        });
        if (otherOwner) continue;

        const reset = await runCustomerResetTransaction(botId, 'user-lifecycle: ' + reason);
        if (reset.begin?.skipReset === true) continue;
        if (!reset.begin?.ok || !reset.resetResult?.ok) {
            partial = true;
            failedBots.push({
                botId,
                resetId: reset.resetResult?.resetId || reset.begin?.context?.resetId || '',
                error: reset.resetResult?.error || reset.begin?.error || 'Không hoàn tất được reset bot sau thay đổi quyền user.'
            });
            continue;
        }
        if (reset.resetResult.partial === true || reset.resetResult?.authSyncError) partial = true;
    }
    if (failedBots.length > 0) {
        return {
            ok: false,
            partial: true,
            failedBots,
            error: `Không hoàn tất được reset cho ${failedBots.length} bot (${failedBots.map(f => f.botId).join(', ')}) sau khi thay đổi quyền.`
        };
    }
    return { ok: true, partial };
}

async function resumePendingCustomerResets() {
    if (!supabaseAdapter?.isEnabled?.() || !supabaseStorageReady) return { resumed: 0 };
    const pending = getPendingResets();
    let resumed = 0;
    let conflictCount = 0;
    for (const [key, context] of Object.entries(pending)) {
        if (!context || typeof context !== 'object') continue;
        if (context.status === 'completed') {
            delete pending[key];
            const cleaned = await saveRegistry().catch(() => false);
            if (!cleaned) pending[key] = context;
            continue;
        }
        if (context.status === 'conflict' || context.status === 'needs_admin') {
            // BUG-05 (Wave B0 — recheck §7-3): KHÔNG bỏ qua im lặng. Conflict phải được
            // admin nhìn thấy và xử lý có kiểm soát (route /api/manager/pending-resets).
            // KHÔNG tự xóa checkpoint. Log rút gọn 10 phút/lần chống spam.
            const conflictWarnKey = 'reset_conflict_' + key;
            const nowMs = Date.now();
            if (!lastPositionWarnLog || nowMs - (lastPositionWarnLog.get(conflictWarnKey) || 0) > 600000) {
                console.error(`[RESET_CUSTOMER] ⚠ Checkpoint reset bot #${context.botId || key} đang ${String(context.status).toUpperCase()} — cần admin xử lý qua /api/manager/pending-resets (owner: ${context.username || context.ownerBefore?.username || 'N/A'}). Không resume tự động.`);
                if (lastPositionWarnLog) lastPositionWarnLog.set(conflictWarnKey, nowMs);
            }
            conflictCount++;
            continue;
        }
        if (customerResetLocks.has(String(key))) continue;
        const bId = Number(context.botId || key);
        if (!Number.isSafeInteger(bId) || bId <= 0) continue;
        customerResetLocks.add(String(key));
        context.status = 'running';
        context.leaseUntil = Date.now() + 10 * 60 * 1000;
        context.updatedAt = new Date().toISOString();
        try {
            const result = await supabaseAdapter.withManagerLock('bot-ownership-mutation', async () => {
                if (!(await persistPendingReset(bId, context))) throw new Error('Không lưu được lease/checkpoint resume reset lên Cloud.');
                return await executeCustomerReset(bId, { context, resume: true });
            }, 900);
            resumed++;
            if (result.ok && result.partial !== true) {
                console.log('[RESET_CUSTOMER] Đã hoàn tất reset còn dang dở cho bot #' + bId + '.');
            } else {
                console.warn('[RESET_CUSTOMER] Reset bot #' + bId + ' vẫn chưa hoàn tất: ' + (result.error || result.warning || 'PARTIAL'));
            }
        } catch (err) {
            customerResetLocks.delete(String(key));
            console.error('[RESET_CUSTOMER] Lỗi resume reset bot #' + bId + ':', err.message);
        }
    }
    // BUG-05 (Wave B0): trả về cả số conflict đang treo để giám sát/UI admin polling.
    return { resumed, conflicts: conflictCount };
}

// V3-03 & V4-08: Helper xác nhận payload reset worker chặt chẽ cho cả local và cloud
function isWorkerResetPayloadConfirmed(res, expectedTxId = null) {
    if (!res || !res.ok) return false;
    const data = res.data;
    if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
    if (data.ok !== true) return false;
    // V4-08: Nếu có expectedTxId, BẮT BUỘC payload phải có resetTransactionId và phải khớp
    if (expectedTxId) {
        if (!data.resetTransactionId || String(data.resetTransactionId) !== String(expectedTxId)) {
            return false;
        }
    }
    return true;
}

async function allocateBotsForUserUnlocked(username, count = 1, preferredBotIds = []) {
    let partial = false;
    const users = await loadUsersFreshOrThrow();
    const now = Date.now();
    registry.botRentalDisabled = normalizeBotRentalDisabled(registry.botRentalDisabled);
    const rentalDisabledSet = new Set(registry.botRentalDisabled);
    const pendingResetBotIds = new Set(Object.entries(getPendingResets())
        .filter(([, context]) => context && context.status !== 'completed')
        .map(([id]) => Number(id)).filter(Number.isSafeInteger));

    // 1. V4-07 & V4-15: Tập hợp các bot đang có khách hàng active thuê theo normalizeEntitlement canonical
    const activeOccupiedBotMap = new Map();
    for (const u of users) {
        if (u.role !== 'admin' && u.username.toLowerCase() !== username.toLowerCase()) {
            const ent = normalizeEntitlement(u);
            if (ent.isActive && Array.isArray(u.assignedBotIds)) {
                for (const bId of u.assignedBotIds) {
                    activeOccupiedBotMap.set(Number(bId), u.username);
                }
            }
        }
    }

    // 2. Lấy danh sách toàn bộ bot cho thuê hợp lệ (rentable !== false và không nằm trong botRentalDisabled)
    const rentableConfigs = BOT_CONFIG.filter(b => {
        const bId = Number(b.id);
        return !rentalDisabledSet.has(bId) && !pendingResetBotIds.has(bId) && b.rentable !== false;
    });

    if (rentableConfigs.length === 0) {
        return { ok: false, error: 'NO_RENTABLE_BOTS', botIds: [] };
    }

    // 3. Tập hợp các bot đã từng gán cho user
    const allAssignedBotIds = new Set();
    for (const u of users) {
        if (Array.isArray(u.assignedBotIds)) {
            for (const bId of u.assignedBotIds) {
                allAssignedBotIds.add(Number(bId));
            }
        }
    }

    const targetUser = users.find(u => u.username.toLowerCase() === username.toLowerCase());
    const existingBots = new Set(Array.isArray(targetUser?.assignedBotIds) ? targetUser.assignedBotIds.map(Number) : []);

    const allocatedIds = [];
    const candidates = [];

    // Ưu tiên 0: preferredBotIds nếu được truyền vào
    if (Array.isArray(preferredBotIds) && preferredBotIds.length > 0) {
        for (const pId of preferredBotIds.map(Number)) {
            const found = rentableConfigs.find(b => Number(b.id) === pId);
            if (found && !activeOccupiedBotMap.has(pId) && !existingBots.has(pId)) {
                const prevOwner = users.find(u => u.username.toLowerCase() !== username.toLowerCase() && Array.isArray(u.assignedBotIds) && u.assignedBotIds.includes(pId));
                candidates.push({ botConfig: found, reclaimedFrom: prevOwner || null });
            }
        }
    }

    // Ưu tiên 1: Bot hoàn toàn trống (chưa từng gán hoặc không ai giữ)
    for (const b of rentableConfigs) {
        const bId = Number(b.id);
        if (!activeOccupiedBotMap.has(bId) && !existingBots.has(bId) && !allAssignedBotIds.has(bId)) {
            if (!candidates.some(c => Number(c.botConfig.id) === bId)) {
                candidates.push({ botConfig: b, reclaimedFrom: null });
            }
        }
    }

    // Ưu tiên 2: V4-07 & V4-15: Bot của người dùng KHÔNG active (hết hạn/disabled theo canonical entitlement)
    for (const u of users) {
        if (u.username.toLowerCase() === username.toLowerCase()) continue;
        const ent = normalizeEntitlement(u);
        if (!ent.isActive && Array.isArray(u.assignedBotIds)) {
            for (const bId of u.assignedBotIds) {
                const numId = Number(bId);
                const found = rentableConfigs.find(c => Number(c.id) === numId);
                if (found && !activeOccupiedBotMap.has(numId) && !existingBots.has(numId)) {
                    if (!candidates.some(c => Number(c.botConfig.id) === numId)) {
                        candidates.push({ botConfig: found, reclaimedFrom: u });
                    }
                }
            }
        }
    }

    // Tiến hành reset và bàn giao bot theo số lượng yêu cầu.
    // QUAN TRỌNG: bắt buộc đi qua beginCustomerReset/executeCustomerReset —
    // đường gọi worker thẳng đã từng bỏ sót: (1) thu hồi quyền Cloud khách cũ
    // TRƯỚC khi reset worker, (2) resetMarker cần thiết cho auth-sync đầu tiên
    // sau reset, (3) tái lập (resume) khi Manager chết giữa chừng.
    for (const { botConfig, reclaimedFrom } of candidates) {
        if (allocatedIds.length >= count) break;
        const chosenBotId = Number(botConfig.id);
        if (!supabaseAdapter?.isEnabled?.()) {
            // NEW-04 (Wave B0 — recheck §5): local/no-Supabase không được coi reset thất bại
            // là thành công. Chỉ khi worker XÁC NHẬN (HTTP ok + data.ok !== false) bot mới
            // được đưa vào allocatedIds. Thất bại → partial + bỏ qua bot này.
            let localResetOk = false;
            const resetTxId = crypto.randomUUID ? crypto.randomUUID() : `reset-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
            try {
                const localReset = await fetchChild(botConfig, '/api/bot/reset-customer', {
                    method: 'POST',
                    body: {
                        botSecretKey: botConfig.secretKey || getRegistryBotSecret(chosenBotId) || BOT_SECRET_KEY,
                        resetTransactionId: resetTxId
                    }
                });
                localResetOk = isWorkerResetPayloadConfirmed(localReset, resetTxId);
            } catch (_) { localResetOk = false; }
            if (!localResetOk) {
                console.warn(`[ALLOCATE] Reset local Bot #${chosenBotId} không được worker xác nhận — KHÔNG cấp bot này cho user (NEW-04 / V3-03).`);
                partial = true;
                continue;
            }
            allocatedIds.push(chosenBotId);
            continue;
        }
        try {
            const begin = await beginCustomerReset(chosenBotId, `allocateBotsForUser: ${username}`);
            if (!begin.ok) {
                console.warn(`[ALLOCATE] Không bắt đầu được reset bền vững cho Bot #${chosenBotId}: ${begin.error || 'RESET_START_FAILED'}. Thử bot tiếp theo...`);
                continue;
            }
            const resetResult = await executeCustomerReset(chosenBotId, { context: begin.context });
            if (!resetResult.ok) {
                console.warn(`[ALLOCATE] Reset Bot #${chosenBotId} chưa hoàn tất (đã ghi pendingResets để resume): ${resetResult.error || resetResult.warning}. Thử bot tiếp theo...`);
                // Trạng thái còn dang dở nằm trong registry.pendingResets; resume định kỳ sẽ tiếp tục.
                continue;
            }
            if (resetResult.ownershipRevoked !== true) {
                console.error(`[ALLOCATE] Bot #${chosenBotId} đã reset worker nhưng chưa xác nhận thu hồi quyền Cloud khách cũ; không cấp bot này.`);
                continue;
            }
            if (resetResult.partial === true) partial = true;
            if (reclaimedFrom) {
                logAuditEvent({
                    action: 'BOT_RECLAIM_EXPIRED',
                    target: { botId: chosenBotId, label: botConfig.label },
                    details: `Thu hồi Bot #${chosenBotId} (${botConfig.label || ''}) từ tài khoản hết hạn "${reclaimedFrom.username}" để cấp cho "${username}" (thu hồi quyền Cloud do state machine reset thực hiện).`,
                    status: 'SUCCESS'
                });
            }
            summaryCache.delete(chosenBotId);
            try { await refreshSummary(botConfig, true); } catch (_) {}
            allocatedIds.push(chosenBotId);
        } catch (e) {
            console.warn(`[ALLOCATE] Không thể kết nối tới Bot #${chosenBotId} (${e.message}), thử bot tiếp theo...`);
        }
    }

    if (allocatedIds.length === 0) {
        return { ok: false, error: 'FULL_BOTS', botIds: [] };
    }

    return {
        ok: true,
        botIds: allocatedIds,
        botId: allocatedIds[0],
        botLabel: (BOT_CONFIG.find(b => Number(b.id) === allocatedIds[0])?.label) || ('Bot ' + allocatedIds[0]),
        partial: allocatedIds.length < count || partial
    };
}

async function allocateBotForNewUser(newUsername) {
    return allocateBotsForUser(newUsername, 1);
}

async function withUniversalManagerLock(lockKey, fn, leaseSeconds = 900) {
    return await withLocalProcessLock(lockKey, async (localCtx) => {
        if (supabaseAdapter && supabaseAdapter.isEnabled()) {
            return await supabaseAdapter.withManagerLock(lockKey, fn, leaseSeconds, { _localLockHeld: true });
        }
        return await fn(localCtx);
    });
}

// V4-14: Local / no-Supabase mode serializes bot allocations via universal queue lock
async function allocateBotsForUser(username, count = 1, preferredBotIds = []) {
    return await withUniversalManagerLock('bot-ownership-mutation', () => allocateBotsForUserUnlocked(username, count, preferredBotIds), 900);
}

// §3.3 / V3-01 & V3-02: Reconcile entitlement & bot allocation on user reactivation
async function reconcileUserReactivationAndBotAllocation(username, options = {}) {
    if (!username) return { ok: false, coreCommitted: true, allocationStatus: 'failed', error: 'MISSING_USERNAME' };
    const normUser = String(username).trim().toLowerCase();

    const runReconciliation = async (lockContext) => {
        let users;
        try { users = await loadUsersFreshOrThrow(); }
        catch (err) { return { ok: false, coreCommitted: true, allocationStatus: 'failed', error: err.message || 'CANNOT_LOAD_USERS' }; }
        const user = users.find(u => u.username.toLowerCase() === normUser);
        if (!user) return { ok: false, coreCommitted: true, allocationStatus: 'failed', error: 'USER_NOT_FOUND' };

        if (!isActiveUserEntitlement(user)) {
            return { ok: false, coreCommitted: true, allocationStatus: 'not_active', error: 'USER_NOT_ACTIVE', status: user.status };
        }
        if (user.role === 'admin') {
            return { ok: true, coreCommitted: true, allocationStatus: 'allocated', allocated: [], assignedBotIds: user.assignedBotIds || [], missingBotCount: 0, role: 'admin' };
        }

        const currentBots = Array.isArray(user.assignedBotIds) ? user.assignedBotIds.map(Number).filter(Number.isSafeInteger) : [];
        const targetBotCount = Math.max(
            1,
            parseInt(options.targetBotCount, 10) || 0,
            parseInt(user.botCount, 10) || 0,
            (Array.isArray(options.targetBotIds) && options.targetBotIds.length ? options.targetBotIds.length : 1)
        );

        if (currentBots.length >= targetBotCount) {
            return { ok: true, coreCommitted: true, allocationStatus: 'allocated', allocated: [], assignedBotIds: currentBots, missingBotCount: 0, message: 'USER_ALREADY_HAS_SUFFICIENT_BOTS' };
        }

        const needed = targetBotCount - currentBots.length;
        const preferredBotIds = Array.isArray(options.preferredBotIds) ? options.preferredBotIds : (Array.isArray(options.targetBotIds) ? options.targetBotIds : []);

        // §3.3: allocateBotsForUser(user.username, needed, preferredBotIds)
        const alloc = await allocateBotsForUserUnlocked(user.username, needed, preferredBotIds);
        if (!alloc.ok || !Array.isArray(alloc.botIds) || alloc.botIds.length === 0) {
            logAuditEvent({
                req: options.req || null,
                action: 'USER_REACTIVATION_BOT_ALLOCATION_PENDING',
                target: { username: user.username },
                details: 'Thiếu bot cho ' + user.username + ': ' + (alloc.error || 'NO_AVAILABLE_BOTS'),
                status: 'WARNING'
            });
            // P1-02: Nếu đang chạy trong background retry, KHÔNG tạo job mới (ngăn nhân bản vô hạn)
            if (options.context === 'background_pending_retry' || options.existingJobId) {
                return {
                    ok: false,
                    coreCommitted: true,
                    allocationStatus: 'pending_retry',
                    error: alloc.error || 'NO_AVAILABLE_BOTS',
                    allocated: [],
                    assignedBotIds: currentBots,
                    missingBotCount: needed,
                    warnings: ['Chưa có bot trống sẵn sàng để cấp lại. Giữ nguyên pending job hiện tại.']
                };
            }
            // V4-09: Lưu durable allocation job vào registry và Supabase SQL (Initial allocation)
            if (!Array.isArray(registry.pendingAllocations)) registry.pendingAllocations = [];
            const existingJob = registry.pendingAllocations.find(j => j.username?.toLowerCase() === normUser && j.status === 'pending_retry');
            const jobId = existingJob ? existingJob.id : ('alloc_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8));
            registry.pendingAllocations = registry.pendingAllocations.filter(j => j.id !== jobId);
            const zeroJob = {
                id: jobId,
                username: user.username,
                targetBotCount,
                currentAssigned: currentBots.length,
                missingBotCount: needed,
                preferredBotIds,
                status: 'pending_retry',
                attempts: existingJob ? existingJob.attempts : 0,
                createdAt: existingJob ? existingJob.createdAt : new Date().toISOString(),
                updatedAt: new Date().toISOString(),
                context: options.context || 'reactivation'
            };
            registry.pendingAllocations.push(zeroJob);
            if (supabaseAdapter && supabaseAdapter.isEnabled()) {
                const saveOk = await supabaseAdapter.savePendingAllocation(zeroJob);
                if (!saveOk) {
                    console.warn('[ALLOCATION] Cảnh báo: Không thể lưu zero-bot pending allocation vào Supabase SQL.');
                }
            }
            await saveRegistry();
            return {
                ok: false,
                coreCommitted: true,
                allocationStatus: 'pending_retry',
                error: alloc.error || 'NO_AVAILABLE_BOTS',
                allocated: [],
                assignedBotIds: currentBots,
                missingBotCount: needed,
                warnings: ['Chưa có bot trống sẵn sàng để cấp lại. Hệ thống đã lưu trạng thái pending_retry.']
            };
        }

        // Fencing check trước khi commit thay đổi phân bổ
        if (lockContext && typeof lockContext.assertLockValid === 'function') {
            lockContext.assertLockValid();
        }
        if (supabaseAdapter && supabaseAdapter.isEnabled() && lockContext && lockContext.fencingToken) {
            const fencingValid = await supabaseAdapter.verifyLockFencing('bot-ownership-mutation', lockContext.owner, lockContext.fencingToken);
            if (!fencingValid) {
                throw new Error(`STALE_FENCING_TOKEN: Fencing token T${lockContext.fencingToken} không còn hợp lệ trên PostgreSQL.`);
            }
        }

        const newAssigned = [...new Set([...currentBots, ...alloc.botIds])];
        user.assignedBotIds = newAssigned;
        user.botCount = Math.max(parseInt(user.botCount, 10) || 1, targetBotCount, newAssigned.length);
        assignBotsExclusively(users, user.id || user.username, newAssigned);

        const saved = await saveUsers(users);
        if (!saved) {
            return {
                ok: false,
                coreCommitted: true,
                allocationStatus: 'failed_persist',
                error: 'FAILED_TO_PERSIST_ALLOCATION',
                allocated: [],
                assignedBotIds: currentBots,
                missingBotCount: needed,
                warnings: ['Không thể lưu phân bổ bot vào cơ sở dữ liệu.']
            };
        }

        if (Array.isArray(cachedUsers)) {
            const cu = cachedUsers.find(x => x.username.toLowerCase() === normUser);
            if (cu) cu.assignedBotIds = newAssigned;
        }

        for (const [hash, sess] of activeSessions.entries()) {
            if (sess.username?.toLowerCase() === normUser) {
                sess.assignedBotIds = newAssigned;
                activeSessions.set(hash, sess);
            }
        }

        const isPartial = alloc.botIds.length < needed;
        const missingCount = Math.max(0, needed - alloc.botIds.length);
        const allocationStatus = isPartial ? 'partial' : 'allocated';

        // P1-01 / V4-09: Nếu cấp một phần nhưng vẫn thiếu bot -> Lưu/cập nhật pending job để background retry tự động
        if (isPartial && missingCount > 0) {
            if (!Array.isArray(registry.pendingAllocations)) registry.pendingAllocations = [];
            // P1-02: Tái sử dụng job ID hiện có (từ options.existingJobId hoặc registry cũ), không tạo mới
            const existingJob = (options.existingJobId && registry.pendingAllocations.find(j => j.id === options.existingJobId))
                || registry.pendingAllocations.find(j => j.username?.toLowerCase() === normUser && j.status === 'pending_retry');
            const jobId = existingJob ? existingJob.id : (options.existingJobId || ('alloc_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8)));
            registry.pendingAllocations = registry.pendingAllocations.filter(j => j.id !== jobId);
            const partialJob = {
                id: jobId,
                username: user.username,
                targetBotCount,
                currentAssigned: newAssigned.length,
                missingBotCount: missingCount,
                preferredBotIds,
                status: 'pending_retry',
                attempts: existingJob ? existingJob.attempts : (options.attempts || 0),
                createdAt: existingJob ? existingJob.createdAt : new Date().toISOString(),
                updatedAt: new Date().toISOString(),
                context: options.context || 'partial_reactivation'
            };
            registry.pendingAllocations.push(partialJob);
            if (supabaseAdapter && supabaseAdapter.isEnabled()) {
                const saveOk = await supabaseAdapter.savePendingAllocation(partialJob);
                if (!saveOk) {
                    console.warn('[ALLOCATION] Cảnh báo: Không thể lưu partial pending allocation vào Supabase SQL.');
                }
            }
            await saveRegistry();
        } else if (!isPartial) {
            // Đã cấp đủ toàn bộ: hoàn thành mọi pending job cũ của user nếu có
            if (Array.isArray(registry.pendingAllocations)) {
                let changed = false;
                for (const j of registry.pendingAllocations) {
                    if (j.username?.toLowerCase() === normUser && j.status === 'pending_retry') {
                        j.status = 'completed';
                        j.completedAt = new Date().toISOString();
                        changed = true;
                        if (supabaseAdapter && supabaseAdapter.isEnabled()) {
                            await supabaseAdapter.completePendingAllocation(j.id, 'completed', MANAGER_WORKER_ID).catch(() => {});
                        }
                    }
                }
                if (changed) await saveRegistry();
            }
        }

        logAuditEvent({
            req: options.req || null,
            action: 'USER_REACTIVATION_BOT_REALLOCATED',
            target: { username: user.username },
            details: 'Tái cấp ' + alloc.botIds.length + ' bot (#' + alloc.botIds.join(', #') + ') sau kích hoạt lại',
            status: isPartial ? 'PARTIAL' : 'SUCCESS'
        });

        return {
            ok: !isPartial,
            coreCommitted: true,
            allocationStatus,
            allocated: alloc.botIds,
            assignedBotIds: newAssigned,
            missingBotCount: missingCount,
            partial: isPartial,
            warnings: isPartial ? ['Chỉ cấp được ' + alloc.botIds.length + '/' + targetBotCount + ' bot.'] : []
        };
    };

    try {
        return await withUniversalManagerLock('bot-ownership-mutation', runReconciliation, 900);
    } catch (err) {
        return {
            ok: false,
            coreCommitted: true,
            allocationStatus: 'pending_retry',
            error: err.message || 'ALLOCATION_LOCK_FAILED',
            allocated: [],
            assignedBotIds: [],
            missingBotCount: 1,
            warnings: ['Không lấy được khóa phân bổ bot phân tán.']
        };
    }
}

// Khách tự đăng ký tài khoản mới (Tự động cấp bot trống hoặc tái sử dụng bot của tài khoản hết hạn)
app.post('/api/auth/register', (req, res) => {
    return withRegisterLock(async () => {
        try {
            if (supabaseAdapter.isEnabled() && !supabaseStorageReady) {
                return res.status(503).json({ ok: false, error: 'Supabase chưa sẵn sàng; không thể tạo tài khoản bền vững lúc này.' });
            }
            const clientIp = getClientIp(req);
            const username = String(req.body?.username || '').trim();
            const password = String(req.body?.password ?? '');
            const providedKey = String(req.body?.licenseKey || req.body?.key || '').trim().toUpperCase();

            const rateLimit = checkRegisterRateLimit(clientIp, username || 'register_user');
            if (!rateLimit.allowed) {
                return res.status(429).json({ ok: false, error: rateLimit.error });
            }

            if (!username) {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(400).json({ ok: false, error: 'Vui lòng nhập tên đăng nhập.' });
            }
            if (!/^[a-zA-Z0-9_.-]{3,32}$/.test(username)) {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(400).json({ ok: false, error: 'Tên người dùng chỉ được chứa chữ cái, số, gạch dưới, gạch ngang và chấm (3-32 ký tự).' });
            }
            if (username.toLowerCase() === 'admin') {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(400).json({ ok: false, error: 'Tên "admin" được bảo lưu cho Quản trị viên chính.' });
            }

            const passPolicy = validatePasswordPolicy(password);
            if (!passPolicy.valid) {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(400).json({ ok: false, error: passPolicy.error });
            }

            let users = await loadUsersFreshOrThrow();
            if (users.some(u => u.username.toLowerCase() === username.toLowerCase())) {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(400).json({ ok: false, error: `Tên người dùng "${username}" đã tồn tại. Vui lòng chọn tên khác!` });
            }

            const trialGiftEnabled = registry.systemSettings?.trialGiftEnabled !== false;
            const trialDays = Math.max(1, Math.min(365, parseInt(registry.systemSettings?.trialDays, 10) || 1));
            let planName = trialDays === 1 ? 'Dùng thử 1 ngày' : `Dùng thử ${trialDays} ngày`;
            let expiresAt = new Date(Date.now() + trialDays * 86400000).toISOString();
            let isPermanentKey = false;
            let assignedBotIds = [];
            let keyObj = null;
            let registerMessage = `Đăng ký thành công! Chào mừng ${username} đến với KBOT.`;

            if (providedKey !== '') {
                const keysList = await loadKeysFresh();
                if (!Array.isArray(keysList)) {
                    recordRegisterAttempt(clientIp, username, false);
                    return res.status(503).json({ ok: false, error: 'Không đọc được danh sách Key mới nhất từ Supabase.' });
                }
                const keyIndex = keysList.findIndex(k => normalizeKeyCode(k) === providedKey);
                if (keyIndex === -1) {
                    recordRegisterAttempt(clientIp, username, false);
                    return res.status(400).json({ ok: false, error: 'Mã Key / Giftcode gia hạn không tồn tại!' });
                }
                keyObj = keysList[keyIndex];
                const keyCheck = checkKeyValidity(keyObj, username);
                if (!keyCheck.ok) {
                    recordRegisterAttempt(clientIp, username, false);
                    return res.status(400).json({ ok: false, error: keyCheck.error });
                }
                isPermanentKey = keyObj.isPermanent === true || keyObj.days === -1;
                const days = isPermanentKey ? -1 : Number(keyObj.days || 30);
                expiresAt = isPermanentKey ? null : new Date(Date.now() + days * 86400000).toISOString();
                planName = keyObj.planName || (isPermanentKey ? 'VIP Vĩnh Viễn' : `Gói ${days} ngày`);

                const requestedBotCount = Number(keyObj.botCount) || (Array.isArray(keyObj.botIds) && keyObj.botIds.length > 0 ? keyObj.botIds.length : 1);
                const preferredBotIds = Array.isArray(keyObj.botIds) ? keyObj.botIds.map(Number) : [];

                const alloc = await allocateBotsForUser(username, requestedBotCount, preferredBotIds);
                if (alloc.ok && alloc.botIds.length > 0) {
                    assignedBotIds = alloc.botIds;
                    registerMessage = `Đăng ký thành công với Mã Key! Gói: ${planName}, Cấp ${assignedBotIds.length} bot (#${assignedBotIds.join(', ')}), Hạn: ${isPermanentKey ? 'Vĩnh viễn' : days + ' ngày'}.`;
                } else {
                    assignedBotIds = [];
                    registerMessage = `Đăng ký thành công với Mã Key! Gói: ${planName}, Hạn: ${isPermanentKey ? 'Vĩnh viễn' : days + ' ngày'} (Hiện chưa có bot trống trong danh sách cho thuê, vui lòng liên hệ Admin để gán bot).`;
                }
            } else {
                // Đăng ký không có Key -> kiểm tra cài đặt tặng ngày dùng thử của Admin
                if (trialGiftEnabled) {
                    const alloc = await allocateBotsForUser(username, 1);
                    if (alloc.ok && alloc.botIds.length > 0) {
                        assignedBotIds = alloc.botIds;
                        registerMessage = `Đăng ký thành công! Bạn đã được cấp Bot #${assignedBotIds.join(', ')} dùng thử ${trialDays} ngày miễn phí.`;
                    } else if (alloc.error === 'NO_RENTABLE_BOTS') {
                        assignedBotIds = [];
                        planName = `Chờ cấp bot (${planName})`;
                        registerMessage = `Đăng ký thành công! Hiện chưa có bot nào được mở cho thuê. Tài khoản của bạn đã được tạo kèm ${trialDays} ngày dùng thử, vui lòng liên hệ Admin để được cấp bot.`;
                    } else {
                        assignedBotIds = [];
                        planName = `Chờ cấp bot (${planName})`;
                        registerMessage = `Đăng ký thành công! Hiện tại toàn bộ bot cho thuê đều đang có người sử dụng. Tài khoản của bạn đã được tạo kèm ${trialDays} ngày dùng thử, vui lòng liên hệ Admin để được cấp bot.`;
                    }
                } else {
                    // Admin đã TẮT chế độ tặng dùng thử -> Chặn đăng ký không có Key
                    recordRegisterAttempt(clientIp, username, false);
                    return res.status(400).json({
                        ok: false,
                        error: 'Chế độ tặng ngày dùng thử hiện đang tạm dừng. Vui lòng nhập Mã Key kích hoạt gói thuê để đăng ký tài khoản!'
                    });
                }
            }

            const newUser = {
                id: 'u_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
                username,
                password,
                role: 'user',
                status: 'active',
                planName,
                expiresAt,
                isPermanent: isPermanentKey ? true : false,
                note: providedKey ? `Tự đăng ký với mã Key ${maskLicenseKey(providedKey)}` : (assignedBotIds.length ? `Tự đăng ký (Được cấp Bot #${assignedBotIds.join(', ')})` : 'Tự đăng ký (Chưa có bot)'),
                allowAccountChange: true,
                assignedBotIds,
                botCount: Math.max(1, keyObj ? (Number(keyObj.botCount) || (Array.isArray(keyObj.botIds) && keyObj.botIds.length ? keyObj.botIds.length : 1)) : 1, assignedBotIds.length),
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString()
            };

            // Tải lại snapshot users mới nhất vì allocateBotsForUser có thể đã chạy revokeBotOwnership làm tăng revision trên Cloud
            users = await loadUsersFreshOrThrow();
            if (users.some(u => u.username.toLowerCase() === username.toLowerCase())) {
                recordRegisterAttempt(clientIp, username, false);
                return res.status(409).json({ ok: false, error: `Tên người dùng "${username}" vừa được đăng ký bởi phiên khác.` });
            }
            assignBotsExclusively(users, '', assignedBotIds);
            users.push(newUser);
            if (keyObj) {
                // Key usage and new account ownership commit together. No active
                // entitlement is visible until Supabase confirms both writes.
                const keyCommit = await commitKeyConsumptionAtomic(keyObj, username, users);
                if (!keyCommit.ok) {
                    users.pop();
                    recordRegisterAttempt(clientIp, username, false);
                    return res.status(keyCommit.status || 409).json({ ok: false, error: keyCommit.error || 'Không thể cập nhật trạng thái Key. Vui lòng thử lại!' });
                }
            } else {
                const saved = await saveUsers(users);
                if (!saved) {
                    users.pop();
                    recordRegisterAttempt(clientIp, username, false);
                    const status = lastUserSaveError.startsWith('REVISION_CONFLICT') ? 409 : 503;
                    return res.status(status).json({ ok: false, error: lastUserSaveError || 'Không thể lưu tài khoản mới vào hệ thống. Vui lòng thử lại!' });
                }
            }

            // Ghi nhận đăng ký thành công cho rate limiter
            recordRegisterAttempt(clientIp, username, true);

            // BUG-29: mảng cảnh báo auth-sync sau commit (được gắn vào response cuối).
            const registerAuthSyncWarnings = [];

            {
                // BUG-29: tài khoản ĐÃ commit; auth-sync có retry 60s → không trả 502
                // che mất việc tạo tài khoản + phiên đăng nhập.
                const authSyncDetailed = await syncAuthToAllBotsDetailed(true);
                if (!authSyncDetailed?.ok) {
                    const failedBots = (authSyncDetailed?.results || []).filter(r => !r.ok);
                    for (const f of failedBots) {
                        await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_REGISTER', target: username } });
                    }
                    registerAuthSyncWarnings.push('Tài khoản đã được tạo nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (authSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây; có thể đăng nhập lại sau khi đồng bộ.');
                }
            }

            logAuditEvent({
                req,
                action: 'USER_REGISTER',
                target: { userId: newUser.id, username },
                details: `Người dùng tự đăng ký tài khoản "${username}" thành công (Gói: ${planName}, Cấp bot: ${assignedBotIds.length ? assignedBotIds.join(', ') : 'Chưa có'}). Mật khẩu tạo: "********"`,
                status: 'SUCCESS'
            });

            // Tự động cấp phiên đăng nhập ngay sau khi đăng ký
            const sessionDurationMs = 30 * 86400000;
            const cookieMaxAge = 2592000;
            const token = crypto.randomBytes(32).toString('hex');
            const tokenHash = hashSessionToken(token);
            const session = {
                tokenHash,
                userId: newUser.id,
                username: newUser.username,
                role: 'user',
                assignedBotIds,
                createdAt: Date.now(),
                expiresAt: Date.now() + sessionDurationMs,
                expiresAtRental: newUser.expiresAt,
                planName: newUser.planName,
                allowAccountChange: true,
                status: 'active'
            };
            const sessionCommit = await supabaseAdapter.createManagerUserSession(session, userSnapshotRevisions.get(users));
            if (!sessionCommit.ok) {
                const status = sessionCommit.error === 'REVISION_CONFLICT' ? 409 : 502;
                return res.status(status).json({ ok: false, error: 'Tài khoản đã lưu nhưng phiên chưa được tạo an toàn: ' + (sessionCommit.error || 'Supabase chưa xác nhận.') });
            }
            activeSessions.set(tokenHash, session);
            persistedSessionHashes.add(tokenHash);

            res.setHeader('Set-Cookie', serializeCookie('kingmc_mgr_session', token, { maxAge: cookieMaxAge, secure: isHttps(req) }));
            return res.json({
                ok: true,
                coreCommitted: true,
                syncStatus: registerAuthSyncWarnings.length > 0 ? 'pending_retry' : 'synced',
                partial: registerAuthSyncWarnings.length > 0,
                warnings: registerAuthSyncWarnings.length ? registerAuthSyncWarnings : undefined,
                user: {
                    username: newUser.username,
                    role: 'user',
                    assignedBotIds,
                    planName: newUser.planName,
                    expiresAt: newUser.expiresAt,
                    allowAccountChange: true,
                    status: 'active'
                },
                message: registerMessage
            });
        } catch (err) {
            console.error('[AUTH] Lỗi đăng ký tài khoản:', err.message);
            return res.status(500).json({ ok: false, error: 'Đã xảy ra lỗi máy chủ trong quá trình đăng ký.' });
        }
    });
});

app.post('/api/auth/login', async (req, res) => {
    if (supabaseAdapter.isEnabled() && !supabaseStorageReady) {
        return res.status(503).json({ ok: false, error: 'Đang tải dữ liệu Supabase hoặc Cloud chưa sẵn sàng. Vui lòng thử lại.' });
    }
    const clientIp = getClientIp(req);
    const username = String(req.body?.username || '').trim();
    const password = String(req.body?.password ?? '');
    const providedKey = String(req.body?.licenseKey || req.body?.key || '').trim().toUpperCase();
    const rememberMe = req.body?.rememberMe === true;
    const sessionDurationMs = rememberMe ? (30 * 86400000) : (24 * 3600000);
    const cookieMaxAge = rememberMe ? 2592000 : 86400;

    const rateLimit = checkLoginRateLimit(clientIp, username);
    if (!rateLimit.allowed) {
        logAuditEvent({
            req,
            action: 'AUTH_LOGIN_BLOCKED',
            target: { username },
            details: 'Bị chặn do thử đăng nhập sai quá nhiều lần từ IP ' + clientIp,
            status: 'BLOCKED'
        });
        return res.status(429).json({ ok: false, error: rateLimit.error });
    }

    if (!username || !password) {
        return res.status(400).json({ ok: false, error: 'Vui lòng nhập đầy đủ tên đăng nhập và mật khẩu.' });
    }

    // 1. Quản trị viên ADMIN
    if (username.toLowerCase() === 'admin') {
        const adminPass = getAdminPassword();
        if (!verifyAdminPassword(password, adminPass)) {
            recordLoginAttempt(clientIp, username, false);
            logAuditEvent({
                req,
                action: 'AUTH_ADMIN_LOGIN_FAILED',
                target: { username: 'admin' },
                details: 'Đăng nhập Quản trị viên thất bại: Sai mật khẩu.',
                status: 'FAILED'
            });
            return res.status(401).json({ ok: false, error: 'Mật khẩu Quản trị viên (Admin) không chính xác.' });
        }

        if (providedKey !== '') {
            return res.status(400).json({
                ok: false,
                error: 'Tài khoản Quản trị viên (Admin) không dùng Mã Key gia hạn. Vui lòng để trống ô Mã Key!'
            });
        }

        recordLoginAttempt(clientIp, username, true);

        // Tự động di trú mật khẩu Admin sang scrypt nếu đang là plaintext
        if (!String(registry.adminPassword || '').startsWith('scrypt$')) {
            registry.adminPassword = hashAdminPassword(password);
            const regSaved = await saveRegistry();
            if (regSaved) {
                console.log('[SECURITY] 🔐 Đã tự động nâng cấp mật khẩu Admin sang scrypt hash an toàn!');
            } else {
                console.error('[SECURITY] ❌ Không thể lưu registry khi nâng cấp mật khẩu Admin');
            }
        }

        const token = crypto.randomBytes(32).toString('hex');
        const tokenHash = hashSessionToken(token);
        const expiresAt = Date.now() + sessionDurationMs;
        const session = {
            tokenHash,
            userId: 'admin',
            username: 'admin',
            role: 'admin',
            assignedBotIds: null,
            createdAt: Date.now(),
            expiresAt
        };
        activeSessions.set(tokenHash, session);
        if (supabaseAdapter.isEnabled() && !(await saveSessions())) {
            activeSessions.delete(tokenHash);
            return res.status(502).json({ ok: false, error: 'Không thể lưu phiên đăng nhập Admin lên Supabase.' });
        }
        logAuditEvent({
            req,
            action: 'AUTH_ADMIN_LOGIN_SUCCESS',
            target: { username: 'admin' },
            details: 'Quản trị viên đăng nhập thành công vào hệ thống.',
            status: 'SUCCESS'
        });
        res.setHeader('Set-Cookie', serializeCookie('kingmc_mgr_session', token, { maxAge: cookieMaxAge, secure: isHttps(req) }));
        return res.json({
            ok: true,
            token,
            user: {
                username: 'admin',
                role: 'admin',
                assignedBotIds: null,
                mustChangePassword: registry.mustChangePassword === true
            },
            message: 'Đăng nhập thành công với quyền Quản trị viên (ADMIN)!'
        });
    }

    // 2. Tài khoản người dùng USER
    let users;
    try {
        users = await loadUsersFreshOrThrow();
    } catch (err) {
        return res.status(503).json({ ok: false, error: 'Không thể xác minh tài khoản trên Supabase. Vui lòng thử lại sau.' });
    }
    let user = users.find(u => u.username.toLowerCase() === username.toLowerCase());
    if (!user) {
        recordLoginAttempt(clientIp, username, false);
        logAuditEvent({
            req,
            action: 'AUTH_LOGIN_FAILED',
            target: { username },
            details: 'Đăng nhập thất bại: Tài khoản "' + username + '" không tồn tại.',
            status: 'FAILED'
        });
        return res.status(401).json({ ok: false, error: 'Tên đăng nhập hoặc mật khẩu không chính xác.' });
    }

    // BẮT BUỘC kiểm tra mật khẩu TRƯỚC KHI kiểm tra hay gạch Key
    if (!verifyUserPassword(password, user.password)) {
        recordLoginAttempt(clientIp, username, false);
        logAuditEvent({
            req,
            action: 'AUTH_LOGIN_FAILED',
            target: { username },
            details: 'Đăng nhập thất bại: Sai mật khẩu cho tài khoản "' + username + '".',
            status: 'FAILED'
        });
        return res.status(401).json({ ok: false, error: 'Tên đăng nhập hoặc mật khẩu không chính xác.' });
    }

    recordLoginAttempt(clientIp, username, true);

    if (user.status === 'disabled') {
        logAuditEvent({
            req,
            action: 'AUTH_LOGIN_BLOCKED',
            target: { username },
            details: 'Đăng nhập bị từ chối: Tài khoản "' + username + '" đã bị vô hiệu hóa bởi Quản trị viên.',
            status: 'BLOCKED'
        });
        return res.status(403).json({ ok: false, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
    }

    // Xử lý nạp Key gia hạn (nếu có nhập)
    // Giao dịch chiếm khóa chung với đăng ký (withRegisterLock) để hai luồng
    // tiêu thụ Key không chạy song song trên cùng một process.
    let renewalResetPartial = false;
    let renewalResetPerformed = false;
    // BUG-29: auth-sync chưa hội tụ sau khi commit Key KHÔNG được làm hỏng đăng nhập
    // (operation đã commit); gom cảnh báo và trả trong response login.
    const authSyncPartialWarnings = [];
    if (providedKey !== '') {
        let renewOutcome;
        try {
            renewOutcome = await withRegisterLock(async () => {
        const renewRate = checkRenewRateLimit(req, user.username);
        if (!renewRate.allowed) {
            return res.status(429).json({ ok: false, error: renewRate.error });
        }

        const keysList = await loadKeysFresh();
        if (!Array.isArray(keysList)) {
            recordRenewAttempt(req, user.username, false);
            return res.status(503).json({ ok: false, error: 'Không đọc được danh sách Key mới nhất từ Supabase.' });
        }
        const keyIndex = keysList.findIndex(k => normalizeKeyCode(k) === providedKey);
        if (keyIndex === -1) {
            recordRenewAttempt(req, user.username, false);
            return res.status(400).json({ ok: false, error: 'Mã Key / Giftcode gia hạn không tồn tại!' });
        }
        const keyObj = keysList[keyIndex];
        const keyCheck = checkKeyValidity(keyObj, user.username);
        if (!keyCheck.ok) {
            recordRenewAttempt(req, user.username, false);
            return res.status(400).json({ ok: false, error: keyCheck.error });
        }

        recordRenewAttempt(req, user.username, true);

        if (user.status === 'disabled') {
            recordRenewAttempt(req, user.username, false);
            return res.status(403).json({ ok: false, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
        }

        const ent = normalizeEntitlement(user);
        if (ent.isPermanent) {
            recordRenewAttempt(req, user.username, false);
            return res.status(400).json({ ok: false, error: 'Tài khoản của bạn đã là VIP Vĩnh Viễn, không cần nạp thêm Key!' });
        }

        const isPermanentKey = keyObj.isPermanent === true || keyObj.days === -1;
        if (isPermanentKey) {
            user.expiresAt = null;
            user.isPermanent = true;
        } else {
            const baseTime = (user.expiresAt && Date.parse(user.expiresAt) > Date.now())
                ? Date.parse(user.expiresAt)
                : Date.now();
            user.expiresAt = new Date(baseTime + Number(keyObj.days || 30) * 86400000).toISOString();
        }
        user.status = 'active';
        if (keyObj.planName) user.planName = keyObj.planName;
        else if (isPermanentKey) user.planName = 'VIP Vĩnh Viễn';
        const keyBotCount = Number(keyObj.botCount) || (Array.isArray(keyObj.botIds) && keyObj.botIds.length > 0 ? keyObj.botIds.length : 1);
        user.botCount = Math.max(parseInt(user.botCount, 10) || 1, keyBotCount);
        const currentBots = Array.isArray(user.assignedBotIds) ? user.assignedBotIds.map(Number) : [];
        if (Array.isArray(keyObj.botIds) && keyObj.botIds.length > 0) {
            const newlyAssigned = keyObj.botIds.map(Number).filter(id => !currentBots.includes(id));
            if (newlyAssigned.length > 0) {
                const resetRes = await resetBotsForAssignment(newlyAssigned, `nạp Key gia hạn cho "${user.username}"`);
                if (!resetRes.ok) {
                    recordRenewAttempt(req, user.username, false);
                    return res.status(500).json({ ok: false, partial: resetRes.partial === true, error: `Không thể dọn dẹp reset Bot #${resetRes.botId} để bàn giao (${resetRes.error}). Vui lòng liên hệ Admin!` });
                }
                renewalResetPerformed = true;
                renewalResetPartial = resetRes.partial === true;
                const preserved = { expiresAt: user.expiresAt, status: user.status, planName: user.planName, isPermanent: user.isPermanent, botCount: user.botCount };
                users = await loadUsersFreshOrThrow();
                const freshUser = users.find(u => String(u.id) === String(user.id) || u.username.toLowerCase() === user.username.toLowerCase());
                if (!freshUser) return res.status(409).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản đã thay đổi trong lúc reset bot; vui lòng đăng nhập lại.' });
                if (freshUser.status === 'disabled') {
                    return res.status(403).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
                }
                user = freshUser;
                user.expiresAt = preserved.expiresAt;
                user.status = preserved.status;
                user.planName = preserved.planName;
                user.isPermanent = preserved.isPermanent;
                user.botCount = preserved.botCount;
            }
            const freshCurrentBots = Array.isArray(user.assignedBotIds) ? user.assignedBotIds.map(Number) : [];
            const merged = [...new Set([...freshCurrentBots, ...keyObj.botIds.map(Number)])];
            user.assignedBotIds = merged;
            user.botCount = Math.max(parseInt(user.botCount, 10) || 1, user.assignedBotIds.length);
            assignBotsExclusively(users, user.id || user.username, keyObj.botIds);
        } else if (keyBotCount > 0 && currentBots.length < keyBotCount) {
            const needed = keyBotCount - currentBots.length;
            const alloc = await allocateBotsForUser(user.username, needed);
            if (alloc.ok && alloc.botIds.length > 0) {
                const preserved = { expiresAt: user.expiresAt, status: user.status, planName: user.planName, isPermanent: user.isPermanent, botCount: user.botCount };
                users = await loadUsersFreshOrThrow();
                const freshUser = users.find(u => String(u.id) === String(user.id) || u.username.toLowerCase() === user.username.toLowerCase());
                if (!freshUser) return res.status(409).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản đã thay đổi trong lúc cấp bot; vui lòng đăng nhập lại.' });
                if (freshUser.status === 'disabled') {
                    return res.status(403).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
                }
                user = freshUser;
                user.expiresAt = preserved.expiresAt;
                user.status = preserved.status;
                user.planName = preserved.planName;
                user.isPermanent = preserved.isPermanent;
                user.botCount = preserved.botCount;
                const freshUserBots = Array.isArray(user.assignedBotIds) ? user.assignedBotIds.map(Number) : [];
                user.assignedBotIds = [...new Set([...freshUserBots, ...alloc.botIds])];
                user.botCount = Math.max(parseInt(user.botCount, 10) || 1, user.assignedBotIds.length);
                assignBotsExclusively(users, user.id || user.username, user.assignedBotIds);
            }
        }

        // Key consumption and entitlement mutation are one Cloud transaction.
        const keyCommit = await commitKeyConsumptionAtomic(keyObj, user.username, users);
        if (!keyCommit.ok) {
            return res.status(keyCommit.status || 409).json({
                ok: false,
                partial: renewalResetPerformed,
                error: (renewalResetPerformed ? 'Bot đã được reset và quyền cũ đã thu hồi, nhưng ' : '') +
                    (keyCommit.conflict ? 'mã Key vừa được sử dụng bởi giao dịch khác. ' : 'lỗi ghi lượt dùng Key. ') +
                    'Vui lòng thử lại!'
            });
        }

        logAuditEvent({
            req,
            action: 'RENTAL_RENEW_KEY',
            target: { username: user.username, key: maskLicenseKey(keyObj.key) },
            details: 'Gia hạn thành công khi đăng nhập bằng Key (' + maskLicenseKey(keyObj.key) + ', +' + keyObj.days + ' ngày). Hạn mới: ' + user.expiresAt + (renewalResetPartial ? ' | Bot bàn giao reset chưa xóa hết log Cloud.' : ''),
            status: renewalResetPartial ? 'PARTIAL' : 'SUCCESS'
        });

        {
            // BUG-29: Key + hạn thuê ĐÃ commit trước đó; auth-sync có retry 60s tự hội tụ.
            // Trả tiếp luồng đăng nhập thay vì 502 che mất kết quả thành công.
            const authSyncDetailed = await syncAuthToAllBotsDetailed(true);
            if (!authSyncDetailed?.ok) {
                const failedBots = (authSyncDetailed?.results || []).filter(r => !r.ok);
                for (const f of failedBots) {
                    await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'LOGIN_KEY_RENEW', target: user.username } });
                }
                authSyncPartialWarnings.push('Key và hạn thuê đã lưu thành công nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (authSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
            }
        }
        return 'RENEW_CONTINUE_LOGIN';
        });
        if (renewOutcome !== 'RENEW_CONTINUE_LOGIN') return renewOutcome; // chết đường nào thì response đã gửi ở đó
        } catch (renewErr) {
            console.error('[AUTH] Lỗi giao dịch nạp Key khi đăng nhập:', renewErr.message);
            return res.status(500).json({ ok: false, partial: renewalResetPerformed, error: 'Lỗi máy chủ khi xử lý nạp Key gia hạn. Vui lòng thử lại.' });
        }
    }

    // Xác định trạng thái tài khoản: disabled, expired hoặc active
    const isTemporarilyDisabled = user.status === 'disabled';
    const isExpired = !isTemporarilyDisabled && (user.status === 'expired' || (user.expiresAt && Date.now() > Date.parse(user.expiresAt)));
    const finalStatus = isTemporarilyDisabled ? 'disabled' : (isExpired ? 'expired' : 'active');

    const token = crypto.randomBytes(32).toString('hex');
    const tokenHash = hashSessionToken(token);
    const expiresAt = Date.now() + sessionDurationMs;
    const assignedBotIds = Array.isArray(user.assignedBotIds) ? user.assignedBotIds.map(Number) : [];
    const session = {
        tokenHash,
        userId: user.id,
        username: user.username,
        role: 'user',
        assignedBotIds,
        createdAt: Date.now(),
        expiresAt,
        expiresAtRental: user.expiresAt || null,
        planName: user.planName || 'Gói thường',
        allowAccountChange: user.allowAccountChange !== false,
        status: finalStatus,
        lockReason: user.lockReason || ''
    };
    const expectedUserRevision = userSnapshotRevisions.get(users);
    const sessionCommit = await supabaseAdapter.createManagerUserSession(session, expectedUserRevision);
    if (!sessionCommit.ok) {
        if (sessionCommit.error === 'USER_CHANGED') {
            return res.status(403).json({ ok: false, error: 'Tài khoản đã bị khóa hoặc thay đổi trong lúc đăng nhập. Vui lòng tải lại và thử lại.' });
        }
        const status = sessionCommit.error === 'REVISION_CONFLICT' ? 409 : 502;
        return res.status(status).json({ ok: false, error: sessionCommit.error === 'REVISION_CONFLICT'
            ? 'Tài khoản vừa được thay đổi; vui lòng đăng nhập lại.'
            : 'Không thể tạo phiên đăng nhập an toàn trên Supabase.' });
    }
    activeSessions.set(tokenHash, session);
    persistedSessionHashes.add(tokenHash);

    logAuditEvent({
        req,
        action: isTemporarilyDisabled ? 'AUTH_USER_LOGIN_DISABLED' : (isExpired ? 'AUTH_USER_LOGIN_EXPIRED' : 'AUTH_USER_LOGIN_SUCCESS'),
        target: { userId: user.id, username: user.username },
        details: isTemporarilyDisabled
            ? `Khách thuê "${user.username}" đăng nhập (Tài khoản đang bị tạm khóa: ${user.lockReason || 'Không có lý do'}).`
            : (isExpired
                ? `Khách thuê "${user.username}" đăng nhập (Gói thuê đã hết hạn).`
                : `Khách thuê "${user.username}" đăng nhập thành công (Gói: ${user.planName || 'Chuẩn'}, Hạn: ${user.expiresAt || 'Vĩnh viễn'}, Quản lý: ${assignedBotIds.length} bot).`),
        status: 'SUCCESS'
    });

    res.setHeader('Set-Cookie', serializeCookie('kingmc_mgr_session', token, { maxAge: cookieMaxAge, secure: isHttps(req) }));
    return res.json({
        ok: true,
        coreCommitted: true,
        syncStatus: (renewalResetPartial || authSyncPartialWarnings.length > 0) ? 'pending_retry' : 'synced',
        partial: renewalResetPartial || authSyncPartialWarnings.length > 0,
        warning: renewalResetPartial ? 'Gia hạn thành công nhưng bot bàn giao chưa xóa hết log Cloud; kiểm tra log worker.' : undefined,
        warnings: authSyncPartialWarnings.length ? authSyncPartialWarnings : undefined,
        token,
        user: {
            username: user.username,
            role: 'user',
            assignedBotIds,
            planName: user.planName || 'Gói thường',
            expiresAt: user.expiresAt || null,
            allowAccountChange: user.allowAccountChange !== false,
            status: finalStatus,
            lockReason: user.lockReason || ''
        },
        message: isTemporarilyDisabled
            ? 'Tài khoản của bạn đang bị tạm khóa. Vui lòng xem thông báo của Quản trị viên.'
            : (isExpired
                ? 'Tài khoản của bạn đã hết hạn thuê. Vui lòng nạp Mã Key để tiếp tục sử dụng!'
                : 'Đăng nhập thành công! Chào mừng ' + user.username + '.')
    });
});

app.post('/api/auth/logout', async (req, res) => {
    const session = getSessionUser(req);
    const headerToken = getAuthToken(req);
    const cookies = parseCookies(req);
    const cookieToken = cookies.kingmc_mgr_session;

    let modified = false;
    if (headerToken) {
        const h = hashSessionToken(headerToken);
        if (activeSessions.has(h)) {
            activeSessions.delete(h);
            invalidateAuthCache(h);
            modified = true;
            if (supabaseAdapter && supabaseAdapter.isEnabled()) {
                await supabaseAdapter.deleteSession(h);
            }
        }
    }
    if (cookieToken) {
        const h = hashSessionToken(cookieToken);
        if (activeSessions.has(h)) {
            activeSessions.delete(h);
            invalidateAuthCache(h);
            modified = true;
            if (supabaseAdapter && supabaseAdapter.isEnabled()) {
                await supabaseAdapter.deleteSession(h);
            }
        }
    }
    if (modified) {
        if (supabaseAdapter.isEnabled() && !(await saveSessions())) {
            return res.status(502).json({ ok: false, error: 'Không thể xác nhận phiên đăng xuất trên Supabase.' });
        }
    }

    if (session) {
        logAuditEvent({ req, action: 'AUTH_LOGOUT', details: 'Đăng xuất tài khoản "' + session.username + '" (IP: ' + getClientIp(req) + ')', status: 'SUCCESS' });
    }
    res.setHeader('Set-Cookie', clearCookieHeader('kingmc_mgr_session', isHttps(req)));
    res.json({ ok: true, message: 'Đã đăng xuất.' });
});

app.get('/api/auth/me', (req, res) => {
    const session = getSessionUser(req);
    if (!session) {
        return res.status(401).json({ ok: false, user: null, error: 'Chưa đăng nhập.' });
    }
    const users = loadUsers();
    const u = users.find(x => x.username.toLowerCase() === session.username.toLowerCase());
    const isRentalExpired = session.role === 'user' && (session.status === 'expired' || u?.status === 'expired' || (u?.expiresAt && Date.now() > Date.parse(u.expiresAt)) || (session?.expiresAtRental && Date.now() > Date.parse(session.expiresAtRental)));
    const finalStatus = (session.role === 'user' && (session.status === 'disabled' || u?.status === 'disabled'))
        ? 'disabled'
        : (isRentalExpired ? 'expired' : (u?.status || session.status || 'active'));
    res.json({
        ok: true,
        user: {
            username: session.username,
            role: session.role,
            assignedBotIds: session.assignedBotIds,
            planName: u?.planName || (session.role === 'admin' ? 'Admin VIP' : 'Gói thường'),
            expiresAt: u?.expiresAt || session.expiresAtRental || null,
            isPermanent: Boolean(u?.isPermanent === true || u?.is_permanent === true || session?.isPermanent === true || (session.role === 'user' && !u?.expiresAt && !session.expiresAtRental)),
            // BUG-18: ghi chú nội bộ (note) chỉ trả về cho Admin, không lộ cho khách thuê.
            note: session.role === 'admin' ? (u?.note || '') : '',
            allowAccountChange: u ? u.allowAccountChange !== false : true,
            status: finalStatus,
            lockReason: u?.lockReason || session.lockReason || '',
            mustChangePassword: session.role === 'admin' ? (registry.mustChangePassword === true) : false
        }
    });
});

function validatePasswordPolicy(password) {
    if (!password || typeof password !== 'string') {
        return { valid: false, error: 'Mật khẩu không được để trống.' };
    }
    if (password.length < 5) {
        return { valid: false, error: 'Mật khẩu phải có tối thiểu 5 ký tự.' };
    }
    return { valid: true };
}

app.post('/api/auth/change-password', async (req, res) => {
    const session = getSessionUser(req);
    if (!session) {
        return res.status(401).json({ ok: false, error: 'Chưa đăng nhập hệ thống.' });
    }

    const clientIp = getClientIp(req);
    const rateCheck = changePassLimiter.check(clientIp, session.username);
    if (!rateCheck.allowed) {
        return res.status(429).json({ ok: false, error: rateCheck.error });
    }

    const oldPassword = String(req.body?.oldPassword ?? '');
    const newPassword = String(req.body?.newPassword ?? '');

    if (!oldPassword) {
        return res.status(400).json({ ok: false, error: 'Vui lòng nhập mật khẩu hiện tại.' });
    }
    const passPolicy = validatePasswordPolicy(newPassword);
    if (!passPolicy.valid) {
        return res.status(400).json({ ok: false, error: passPolicy.error });
    }
    if (oldPassword === newPassword) {
        return res.status(400).json({ ok: false, error: 'Mật khẩu mới không được trùng với mật khẩu hiện tại.' });
    }

    if (session.role === 'admin') {
        if (!verifyAdminPassword(oldPassword, getAdminPassword())) {
            changePassLimiter.record(clientIp, session.username, false);
            logAuditEvent({ req, action: 'AUTH_ADMIN_CHANGE_PASS_FAILED', status: 'FAILED' });
            return res.status(400).json({ ok: false, error: 'Mật khẩu hiện tại của Quản trị viên không chính xác.' });
        }
        changePassLimiter.record(clientIp, session.username, true);
        await createSystemBackup('pre-admin-pass-change');
        if (supabaseAdapter?.isEnabled?.()) {
            const previousAdminPassword = registry.adminPassword;
            const previousMustChangePassword = registry.mustChangePassword;
            registry.adminPassword = hashAdminPassword(newPassword);
            registry.mustChangePassword = false;
            const saved = await saveRegistry();
            if (!saved) {
                registry.adminPassword = previousAdminPassword;
                registry.mustChangePassword = previousMustChangePassword;
                return res.status(502).json({ ok: false, error: 'Supabase chưa xác nhận lưu mật khẩu mới. Vui lòng kiểm tra kết nối rồi thử lại.' });
            }
        } else {
            registry.adminPassword = hashAdminPassword(newPassword);
            registry.mustChangePassword = false;
        }
        const sessionResult = await revokeUserSessions(session, { excludeTokenHash: session.tokenHash || '' });
        if (!sessionResult.ok) return res.status(502).json({ ok: false, partial: true, error: 'Mật khẩu đã lưu nhưng chưa xác nhận thu hồi các phiên Admin khác: ' + sessionResult.error });
        // BUG-29: mật khẩu đã commit; auth-sync có retry 60s → trả ok:true + warnings.
        const adminPassSync = await syncAuthToAllBotsDetailed(true);
        const adminPassWarnings = [];
        if (!adminPassSync?.ok) {
            const failedBots = (adminPassSync?.results || []).filter(r => !r.ok);
            for (const f of failedBots) {
                await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'ADMIN_CHANGE_PASSWORD', target: 'admin' } });
            }
            adminPassWarnings.push('Mật khẩu đã lưu thành công nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (adminPassSync?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
        }
        logAuditEvent({ req, action: 'AUTH_ADMIN_CHANGE_PASS_SUCCESS', status: 'SUCCESS' });
        return res.json({ ok: true, coreCommitted: true, syncStatus: adminPassWarnings.length > 0 ? 'pending_retry' : 'synced', partial: adminPassWarnings.length > 0, warnings: adminPassWarnings.length ? adminPassWarnings : undefined, message: 'Đổi mật khẩu Quản trị viên (ADMIN) thành công!' });
    } else {
        const users = await loadUsersFreshOrThrow();
        const userIndex = users.findIndex(u => u.id === session.userId || u.username.toLowerCase() === session.username.toLowerCase());
        if (userIndex === -1) {
            return res.status(404).json({ ok: false, error: 'Không tìm thấy thông tin tài khoản người dùng.' });
        }
        if (!verifyUserPassword(oldPassword, users[userIndex].password)) {
            changePassLimiter.record(clientIp, session.username, false);
            logAuditEvent({ req, action: 'AUTH_USER_CHANGE_PASS_FAILED', details: { username: session.username }, status: 'FAILED' });
            return res.status(400).json({ ok: false, error: 'Mật khẩu hiện tại không chính xác.' });
        }
        changePassLimiter.record(clientIp, session.username, true);
        await createSystemBackup('pre-user-pass-change');
        users[userIndex].password = newPassword;
        users[userIndex].updatedAt = new Date().toISOString();
        const saved = await saveUsers(users);
        if (!saved) {
            return res.status(500).json({ ok: false, error: 'Không thể lưu mật khẩu người dùng vào hệ thống.' });
        }
        const sessionResult = await revokeUserSessions(users[userIndex], { excludeTokenHash: session.tokenHash || '' });
        if (!sessionResult.ok) return res.status(502).json({ ok: false, partial: true, error: 'Mật khẩu đã lưu nhưng chưa xác nhận thu hồi các phiên khác: ' + sessionResult.error });
        // BUG-29: mật khẩu đã commit; auth-sync có retry 60s → trả ok:true + warnings.
        const userPassSync = await syncAuthToAllBotsDetailed(true);
        const userPassWarnings = [];
        if (!userPassSync?.ok) {
            const failedBots = (userPassSync?.results || []).filter(r => !r.ok);
            for (const f of failedBots) {
                await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_CHANGE_PASSWORD', target: session.username } });
            }
            userPassWarnings.push('Mật khẩu đã lưu thành công nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (userPassSync?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
        }
        logAuditEvent({ req, action: 'AUTH_USER_CHANGE_PASS_SUCCESS', details: `Đổi mật khẩu tài khoản "${session.username}" thành công`, status: 'SUCCESS' });
        return res.json({ ok: true, coreCommitted: true, syncStatus: userPassWarnings.length > 0 ? 'pending_retry' : 'synced', partial: userPassWarnings.length > 0, warnings: userPassWarnings.length ? userPassWarnings : undefined, message: 'Đổi mật khẩu thành công!' });
    }
});

// Admin: Lấy danh sách users (Không trả mật khẩu plaintext hàng loạt)
app.get('/api/manager/users', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên (Admin) mới có quyền truy cập danh sách người dùng.' });
    }
    const allUsers = await loadUsersFreshOrThrow();
    const customerUsers = allUsers.filter(u => u.role !== 'admin' && String(u.username || '').toLowerCase() !== 'admin');
    let users = customerUsers.map(u => ({
        id: u.id,
        username: u.username,
        password: '',
        hasPassword: !!u.password,
        status: u.status || 'active',
        lockReason: u.lockReason || '',
        assignedBotIds: Array.isArray(u.assignedBotIds) ? u.assignedBotIds.map(Number) : [],
        planName: u.planName || 'Gói thường',
        expiresAt: u.expiresAt || null,
        note: u.note || '',
        allowAccountChange: u.allowAccountChange !== false,
        role: u.role || 'user',
        createdAt: u.createdAt || new Date().toISOString()
    }));

    const page = parseInt(req.query.page, 10) || 1;
    const limit = Math.min(200, Math.max(1, parseInt(req.query.limit, 10) || 50));
    const search = String(req.query.search || '').trim().toLowerCase();
    const status = req.query.status ? String(req.query.status).trim().toLowerCase() : null;

    if (search) {
        users = users.filter(u =>
            (u.username && u.username.toLowerCase().includes(search)) ||
            (u.planName && u.planName.toLowerCase().includes(search)) ||
            (u.note && u.note.toLowerCase().includes(search))
        );
    }
    if (status && status !== 'all') {
        users = users.filter(u => String(u.status || 'active').toLowerCase() === status);
    }

    const paginatedUsers = (req.query.page || req.query.limit || req.query.search || req.query.status)
        ? users.slice((page - 1) * limit, page * limit)
        : users;

    // Xây dựng bản đồ quyền sở hữu bot độc quyền (1 bot -> tối đa 1 user)
    const botOwnership = {};
    for (const u of allUsers) {
        if (Array.isArray(u.assignedBotIds)) {
            for (const bId of u.assignedBotIds) {
                botOwnership[Number(bId)] = { userId: u.id, username: u.username };
            }
        }
    }

    const availableBots = BOT_CONFIG.map(b => {
        const bId = Number(b.id);
        const rawLabel = String(b.label || '').trim();
        const hasCustomAlias = rawLabel && rawLabel !== `Bot ${bId}` && rawLabel !== `bot${bId}` && rawLabel !== `Bot #${bId}`;
        const displayLabel = hasCustomAlias ? `Bot #${bId} (${rawLabel})` : `Bot #${bId}`;
        return {
            id: bId,
            label: displayLabel,
            rawLabel: rawLabel || `Bot #${bId}`,
            url: b.url || '',
            rentable: b.rentable !== false,
            currentOwner: botOwnership[bId] || null
        };
    });
    res.json({ ok: true, page, limit, total: users.length, totalPages: Math.ceil(users.length / limit), users: paginatedUsers, availableBots, botOwnership });
});

// Admin: Xem mật khẩu người dùng theo yêu cầu (On-Demand Reveal)
app.post('/api/manager/users/:id/reveal-password', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên (Admin) mới có quyền xem mật khẩu người dùng.' });
    }
    const allUsers = await loadUsersFreshOrThrow();
    const target = allUsers.find(u => u.id === req.params.id || (u.username && u.username.toLowerCase() === String(req.params.id).toLowerCase()));
    if (!target) {
        return res.status(404).json({ ok: false, error: 'Không tìm thấy người dùng.' });
    }
    const plain = decryptUserPassword(target.password);
    if (plain === null) {
        return res.status(500).json({ ok: false, error: 'Không thể giải mã mật khẩu người dùng bằng MANAGER_MASTER_KEY hiện tại.' });
    }
    logAuditEvent({
        req,
        action: 'USER_PASSWORD_REVEAL',
        target: { userId: target.id, username: target.username },
        details: `Admin xem mật khẩu của người dùng "${target.username}".`,
        status: 'SUCCESS'
    });
    return res.json({ ok: true, password: plain });
});

// Admin: Tạo user mới
app.post('/api/manager/users', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên (Admin) mới có quyền tạo người dùng.' });
    }
    const username = String(req.body?.username || '').trim();
    const password = String(req.body?.password || '').trim();
    const assignedBotIds = Array.isArray(req.body?.assignedBotIds) ? req.body.assignedBotIds.map(Number) : [];
    const status = req.body?.status === 'disabled' ? 'disabled' : (req.body?.status === 'expired' ? 'expired' : 'active');
    const lockReason = req.body?.lockReason ? String(req.body.lockReason).trim() : '';

    if (!username) return res.status(400).json({ ok: false, error: 'Tên đăng nhập không được để trống.' });
    if (!/^[a-zA-Z0-9_.-]{3,32}$/.test(username)) {
        return res.status(400).json({ ok: false, error: 'Tên người dùng chỉ được chứa chữ cái, số, gạch dưới, gạch ngang và chấm (3-32 ký tự).' });
    }
    if (username.toLowerCase() === 'admin') return res.status(400).json({ ok: false, error: 'Tên "admin" được bảo lưu cho Quản trị viên chính.' });
    const passPolicy = validatePasswordPolicy(password);
    if (!passPolicy.valid) {
        return res.status(400).json({ ok: false, error: passPolicy.error });
    }

    const parsedExp = parseSafeIsoDate(req.body?.expiresAt);
    if (!parsedExp.valid) {
        return res.status(400).json({ ok: false, error: parsedExp.error });
    }

    let users = await loadUsersFreshOrThrow();
    if (users.some(u => u.username.toLowerCase() === username.toLowerCase())) {
        return res.status(400).json({ ok: false, error: `Người dùng "${username}" đã tồn tại.` });
    }

    // Reset bot được cấp cho user mới để bàn giao sạch sẽ
    let resetPartial = false;
    let resetPerformed = false;
    if (assignedBotIds.length > 0) {
        const resetRes = await resetBotsForAssignment(assignedBotIds, `Admin tạo người dùng "${username}"`);
        if (!resetRes.ok) {
            return res.status(500).json({ ok: false, partial: resetRes.partial === true, error: `Không thể dọn dẹp reset Bot #${resetRes.botId} để bàn giao (${resetRes.error}).` });
        }
        resetPerformed = true;
        resetPartial = resetRes.partial === true;
        // revokeBotOwnership đã ghi Cloud; nạp lại để không ghi đè aliases/quyền cũ bằng snapshot trước reset.
        users = await loadUsersFreshOrThrow();
    }

    // Đảm bảo nguyên tắc 1 bot chỉ cấp cho tối đa 1 user
    assignBotsExclusively(users, '', assignedBotIds);

    const newUser = {
        id: 'usr_' + crypto.randomUUID(),
        username,
        password,
        role: 'user',
        status,
        lockReason,
        planName: String(req.body?.planName || 'Gói thường').trim(),
        expiresAt: parsedExp.value,
        isPermanent: req.body?.isPermanent === true || parsedExp.value === null,
        note: String(req.body?.note || '').trim(),
        allowAccountChange: req.body?.allowAccountChange !== false,
        assignedBotIds,
        botCount: Math.max(1, parseInt(req.body?.botCount, 10) || assignedBotIds.length || 1),
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };
    users.push(newUser);
    const saved = await saveUsers(users);
    if (!saved) {
        users.pop();
        return res.status(500).json({
            ok: false,
            partial: resetPerformed,
            error: (resetPerformed ? 'Bot đã được reset và quyền cũ đã thu hồi, nhưng chưa lưu được người dùng mới. ' : '') +
                'Không thể lưu dữ liệu người dùng mới vào hệ thống.'
        });
    }
    await createSystemBackup('post-user-create');
    const authSyncDetailed = await syncAuthToAllBotsDetailed(true);
    const authSyncOk = authSyncDetailed?.ok === true;
    if (!authSyncOk) {
        const failedBots = (authSyncDetailed?.results || []).filter(r => !r.ok);
        for (const f of failedBots) {
            await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_CREATE', target: username } });
        }
    }

    logAuditEvent({ req, action: 'USER_CREATE', target: { userId: newUser.id, username }, status: resetPartial || !authSyncOk ? 'PARTIAL' : 'SUCCESS' });
    const safeNewUser = { ...newUser, password: '' };
    res.json({
        ok: true,
        coreCommitted: true,
        syncStatus: (resetPartial || !authSyncOk) ? 'pending_retry' : 'synced',
        partial: resetPartial || !authSyncOk,
        warning: [resetPartial ? 'Bot bàn giao chưa xóa hết log Cloud; kiểm tra log worker.' : '', !authSyncOk ? 'Auth chưa được đồng bộ tới toàn bộ bot.' : ''].filter(Boolean).join(' ') || undefined,
        user: safeNewUser,
        message: `Đã tạo người dùng "${username}" thành công!`
    });
});

// Admin: Cập nhật user
const handleUpdateUser = async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên (Admin) mới có quyền cập nhật người dùng.' });
    }
    const userId = String(req.params.id);
    let users = await loadUsersFreshOrThrow();
    let userIndex = users.findIndex(u => u.id === userId || u.username.toLowerCase() === userId.toLowerCase());
    if (userIndex === -1) return res.status(404).json({ ok: false, error: 'Không tìm thấy người dùng.' });

    const userBackup = JSON.parse(JSON.stringify(users[userIndex]));
    let rollbackUser = userBackup;
    let user = { ...userBackup };
    let passwordChanged = false;
    let resetPartial = false;
    let resetPerformed = false;
    let hasExpiresAtUpdate = false;
    let parsedExpiresAt = null;
    if (req.body?.expiresAt !== undefined) {
        const parsedExp = parseSafeIsoDate(req.body.expiresAt);
        if (!parsedExp.valid) {
            return res.status(400).json({ ok: false, error: parsedExp.error });
        }
        hasExpiresAtUpdate = true;
        parsedExpiresAt = parsedExp.value;
    }

    if (typeof req.body?.username === 'string') {
        const newUsername = req.body.username.trim();
        if (newUsername && newUsername.toLowerCase() !== user.username.toLowerCase()) {
            if (!/^[a-zA-Z0-9_.-]{3,32}$/.test(newUsername)) {
                return res.status(400).json({ ok: false, error: 'Tên người dùng chỉ được chứa chữ cái, số, gạch dưới, gạch ngang và chấm (3-32 ký tự).' });
            }
            if (newUsername.toLowerCase() === 'admin') return res.status(400).json({ ok: false, error: 'Tên "admin" được bảo lưu.' });
            if (users.some((u, i) => i !== userIndex && u.username.toLowerCase() === newUsername.toLowerCase())) {
                return res.status(400).json({ ok: false, error: `Tên người dùng "${newUsername}" đã được sử dụng.` });
            }
            user.username = newUsername;
        }
    }
    if (typeof req.body?.password === 'string' && req.body.password.trim().length > 0) {
        const newPassword = req.body.password.trim();
        if (newPassword !== userBackup.password) {
            const passPolicy = validatePasswordPolicy(newPassword);
            if (!passPolicy.valid) {
                return res.status(400).json({ ok: false, error: passPolicy.error });
            }
            user.password = newPassword;
            passwordChanged = true;
        }
    }
    if (Array.isArray(req.body?.assignedBotIds)) {
        const nextBotIds = req.body.assignedBotIds.map(Number);
        const prevBotIds = Array.isArray(userBackup.assignedBotIds) ? userBackup.assignedBotIds.map(Number) : [];
        const newlyAssigned = nextBotIds.filter(id => !prevBotIds.includes(id));
        if (newlyAssigned.length > 0) {
            const resetRes = await resetBotsForAssignment(newlyAssigned, `Admin gán Bot cho "${user.username}"`);
            if (!resetRes.ok) {
                return res.status(500).json({ ok: false, partial: resetRes.partial === true, error: `Không thể dọn dẹp reset Bot #${resetRes.botId} để bàn giao (${resetRes.error}).` });
            }
            resetPerformed = true;
            resetPartial = resetRes.partial === true;
            users = await loadUsersFreshOrThrow();
            const matchedUserId = String(user.id || '');
            const originalUsername = String(userBackup.username || '').toLowerCase();
            userIndex = users.findIndex(u => (matchedUserId && String(u.id) === matchedUserId) ||
                (originalUsername && String(u.username || '').toLowerCase() === originalUsername));
            if (userIndex === -1) {
                return res.status(409).json({ ok: false, error: 'Người dùng đã thay đổi trong lúc reset bot; vui lòng tải lại trang và thử lại.' });
            }
            // revokeBotOwnership đã xóa alias/quyền của bot khỏi Cloud và cache. Không được
            // ghi đè user bằng snapshot trước reset, nếu không alias cũ sẽ sống lại.
            const freshUser = users[userIndex];
            rollbackUser = JSON.parse(JSON.stringify(freshUser));
            user = {
                ...freshUser,
                ...(user.username !== userBackup.username ? { username: user.username } : {}),
                ...(passwordChanged ? { password: user.password } : {})
            };
        }
        user.assignedBotIds = nextBotIds;
        const retainedBotIds = new Set(nextBotIds.map(Number));
        if (user.botAliases && typeof user.botAliases === 'object') {
            for (const aliasBotId of Object.keys(user.botAliases)) {
                if (!retainedBotIds.has(Number(aliasBotId))) delete user.botAliases[aliasBotId];
            }
        }
        assignBotsExclusively(users, user.id, user.assignedBotIds);
    }
    if (typeof req.body?.status === 'string') {
        user.status = req.body.status === 'disabled' ? 'disabled' : (req.body.status === 'expired' ? 'expired' : 'active');
    }
    if (req.body?.lockReason !== undefined) {
        user.lockReason = String(req.body.lockReason || '').trim();
    }
    if (req.body?.planName !== undefined) {
        user.planName = String(req.body.planName || '').trim();
    }
    if (hasExpiresAtUpdate) {
        user.expiresAt = parsedExpiresAt;
        user.isPermanent = parsedExpiresAt === null ? true : (req.body?.isPermanent === true ? true : false);
    }
    if (req.body?.note !== undefined) {
        user.note = String(req.body.note || '').trim();
    }
    if (req.body?.allowAccountChange !== undefined) {
        user.allowAccountChange = !!req.body.allowAccountChange;
    }
    if (req.body?.botCount !== undefined) {
        user.botCount = Math.max(1, parseInt(req.body.botCount, 10) || 1);
    }
    if (Array.isArray(req.body?.assignedBotIds) && req.body.assignedBotIds.length > (user.botCount || 1)) {
        user.botCount = req.body.assignedBotIds.length;
    }
    user.updatedAt = new Date().toISOString();
    users[userIndex] = user;

    const saved = await saveUsers(users);
    if (!saved) {
        users[userIndex] = rollbackUser;
        return res.status(500).json({
            ok: false,
            partial: resetPerformed,
            error: (resetPerformed ? 'Bot đã được reset và quyền cũ đã thu hồi, nhưng chưa lưu được cập nhật người dùng. ' : '') +
                'Không thể lưu dữ liệu cập nhật người dùng.'
        });
    }
    user = users[userIndex];
    await createSystemBackup('post-user-update');
    let sessionRevokeError = null;
    if (user.status !== 'active' || (user.expiresAt && Date.parse(user.expiresAt) <= Date.now()) || passwordChanged ||
        user.username.toLowerCase() !== userBackup.username.toLowerCase()) {
        const sessionResult = await revokeUserSessions(user);
        if (!sessionResult.ok) {
            sessionRevokeError = sessionResult.error || 'Chưa xác nhận thu hồi mọi session.';
        }
    }
    const lifecycle = await reconcileUserBotLifecycle(userBackup, user, 'admin user update');
    let autoAllocationResult = null;
    if (!isActiveUserEntitlement(userBackup) && isActiveUserEntitlement(user) && (!Array.isArray(user.assignedBotIds) || user.assignedBotIds.length === 0)) {
        autoAllocationResult = await reconcileUserReactivationAndBotAllocation(user.username, { req, context: 'admin_user_update' });
        if (autoAllocationResult?.assignedBotIds?.length) {
            user.assignedBotIds = autoAllocationResult.assignedBotIds;
        }
    }
    // BUG-29: thay đổi user ĐÃ commit; auth-sync có retry 60s → trả ok:true + warnings thay vì 502.
    const authSyncDetailed = await syncAuthToAllBotsDetailed(true);
    const authSyncOk = authSyncDetailed?.ok === true;

    const partialWarnings = [];
    if (sessionRevokeError) partialWarnings.push(sessionRevokeError);
    if (!lifecycle.ok) partialWarnings.push('Chưa hoàn tất reset bot: ' + lifecycle.error);
    if (autoAllocationResult?.warnings?.length) partialWarnings.push(...autoAllocationResult.warnings);
    if (!authSyncOk) {
        const failedBots = (authSyncDetailed?.results || []).filter(r => !r.ok);
        for (const f of failedBots) {
            await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_UPDATE', target: user.username } });
        }
        partialWarnings.push('Chưa đồng bộ auth tới ' + failedBots.length + '/' + (authSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
    }

    logAuditEvent({
        req,
        action: 'USER_UPDATE',
        target: { userId: user.id, username: user.username },
        details: partialWarnings.join('; ') || undefined,
        status: partialWarnings.length ? 'PARTIAL' : (resetPartial ? 'PARTIAL' : 'SUCCESS')
    });
    const safeUser = { ...user, password: '' };
    res.json({
        ok: true,
        coreCommitted: true,
        syncStatus: (resetPartial || partialWarnings.length > 0) ? 'pending_retry' : 'synced',
        partial: resetPartial || partialWarnings.length > 0,
        warning: resetPartial ? 'Người dùng đã được cập nhật nhưng bot bàn giao chưa xóa hết log Cloud; kiểm tra log worker.' : undefined,
        warnings: partialWarnings.length ? partialWarnings : undefined,
        user: safeUser,
        message: `Đã cập nhật người dùng "${user.username}" thành công!`
    });
};
app.put('/api/manager/users/:id', handleUpdateUser);
app.patch('/api/manager/users/:id', handleUpdateUser);

// Admin: Xóa user
app.delete('/api/manager/users/:id', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên (Admin) mới có quyền xóa người dùng.' });
    }
    const userId = String(req.params.id);
    let users = await loadUsersFreshOrThrow();
    const targetIndex = users.findIndex(u => u.id === userId || u.username.toLowerCase() === userId.toLowerCase());
    const target = targetIndex >= 0 ? users[targetIndex] : null;
    if (!target) return res.status(404).json({ ok: false, error: 'Không tìm thấy người dùng.' });
    if (target.role === 'admin') return res.status(400).json({ ok: false, error: 'Không thể xóa tài khoản Quản trị viên bằng chức năng xóa user.' });

    await createSystemBackup('pre-user-delete');
    const previousUser = { ...target, assignedBotIds: Array.isArray(target.assignedBotIds) ? [...target.assignedBotIds] : [] };
    const disabledUser = { ...target, status: 'disabled', updatedAt: new Date().toISOString() };
    users[targetIndex] = disabledUser;
    if (!(await saveUsers(users))) {
        const status = lastUserSaveError.startsWith('REVISION_CONFLICT') ? 409 : 503;
        return res.status(status).json({ ok: false, error: 'Không thể vô hiệu hóa user trước khi xóa: ' + (lastUserSaveError || 'Supabase write failed.') });
    }

    let deleteRevokeError = null;
    const revoked = await revokeUserSessions(disabledUser);
    if (!revoked.ok) {
        deleteRevokeError = revoked.error || 'Thu hồi session thất bại.';
    }
    const lifecycle = await reconcileUserBotLifecycle(previousUser, disabledUser, 'admin user delete');
    let lifecycleError = !lifecycle.ok ? (lifecycle.error || 'Reset bot thất bại.') : null;

    users = await loadUsersFreshOrThrow();
    const currentIndex = users.findIndex(u => String(u.id) === String(target.id) || u.username.toLowerCase() === target.username.toLowerCase());
    if (currentIndex < 0) {
        // BUG-29: user ĐÃ bị vô hiệu hóa trên Cloud; lỗi hoàn tất trả dạng partial warnings.
        const authSyncDetailedEarly = await syncAuthToAllBotsDetailed(true);
        const authSyncFailedEarly = !authSyncDetailedEarly?.ok;
        if (authSyncFailedEarly) {
            const failedBotsEarly = (authSyncDetailedEarly?.results || []).filter(r => !r.ok);
            for (const f of failedBotsEarly) {
                await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_DELETE', target: target.username } }).catch(() => {});
            }
        }
        const hasErr = deleteRevokeError || lifecycleError || authSyncFailedEarly;
        if (hasErr) {
            logAuditEvent({ req, action: 'USER_DELETE', target: { userId: target.id, username: target.username }, details: [deleteRevokeError, lifecycleError, authSyncFailedEarly ? 'Chưa đồng bộ auth tới toàn bộ bot' : null].filter(Boolean).join('; '), status: 'PARTIAL' });
        }
        return res.json({ ok: true, partial: hasErr, warnings: hasErr ? [deleteRevokeError, lifecycleError, authSyncFailedEarly ? 'Chưa đồng bộ auth tới toàn bộ bot; hệ thống sẽ tự thử lại trong khoảng 60 giây.' : null].filter(Boolean) : undefined, message: `Đã xóa người dùng "${target.username}".` });
    }
    const updatedUsers = deriveUsersSnapshot(users, users.filter((_, index) => index !== currentIndex));
    if (!(await saveUsers(updatedUsers))) {
        return res.status(502).json({ ok: false, partial: true, error: 'User đã bị vô hiệu hóa và bot/session đã xử lý, nhưng không thể xóa hàng user trên Cloud: ' + (lastUserSaveError || 'Supabase write failed.') });
    }
    // BUG-29: user ĐÃ xóa trên Cloud; auth-sync có retry 60s → trả ok:true + warnings.
    const authSyncDetailed = await syncAuthToAllBotsDetailed(true);
    const authSyncOk = authSyncDetailed?.ok === true;
    const deleteWarnings = [];
    if (deleteRevokeError) deleteWarnings.push(`Chưa xác nhận thu hồi session: ${deleteRevokeError}`);
    if (lifecycleError) deleteWarnings.push(`Chưa reset sạch bot: ${lifecycleError}`);
    if (!authSyncOk) {
        const failedBots = (authSyncDetailed?.results || []).filter(r => !r.ok);
        for (const f of failedBots) {
            await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'USER_DELETE', target: target.username } }).catch(() => {});
        }
        deleteWarnings.push('Chưa đồng bộ auth tới ' + failedBots.length + '/' + (authSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '; hệ thống sẽ tự thử lại trong khoảng 60 giây.');
    }

    logAuditEvent({ req, action: 'USER_DELETE', target: { userId: target.id, username: target.username }, details: deleteWarnings.join('; ') || undefined, status: deleteWarnings.length ? 'PARTIAL' : 'SUCCESS' });
    res.json({
        ok: true,
        partial: deleteWarnings.length > 0,
        warnings: deleteWarnings.length ? deleteWarnings : undefined,
        message: `Đã xóa người dùng "${target.username}".`
    });
});

// Admin: Gia hạn linh hoạt cho người dùng (thêm/bớt ngày, ngày cố định, vĩnh viễn)
app.post('/api/manager/users/:id/renew-days', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên mới có quyền gia hạn tài khoản.' });
    }
    const userId = String(req.params.id);
    const users = await loadUsersFreshOrThrow();
    const userIndex = users.findIndex(u => u.id === userId || u.username.toLowerCase() === userId.toLowerCase());
    if (userIndex === -1) {
        return res.status(404).json({ ok: false, error: 'Không tìm thấy người dùng.' });
    }
    const targetUser = users[userIndex];
    const userBackup = JSON.parse(JSON.stringify(targetUser));

    const setPermanent = req.body?.setPermanent === true;
    const fixedDate = req.body?.fixedDate ? String(req.body.fixedDate).trim() : null;
    const days = Number(req.body?.days);

    if (setPermanent) {
        targetUser.expiresAt = null;
        targetUser.isPermanent = true;
        targetUser.planName = (typeof req.body?.planName === 'string' && req.body.planName.trim()) ? req.body.planName.trim() : 'VIP Vĩnh Viễn';
        targetUser.status = 'active';
    } else if (fixedDate) {
        const parsed = new Date(fixedDate);
        if (isNaN(parsed.getTime())) {
            return res.status(400).json({ ok: false, error: 'Ngày cố định không hợp lệ.' });
        }
        targetUser.expiresAt = parsed.toISOString();
        targetUser.isPermanent = false;
        if (typeof req.body?.planName === 'string' && req.body.planName.trim()) {
            targetUser.planName = req.body.planName.trim();
        } else if (targetUser.planName === 'VIP Vĩnh Viễn') {
            targetUser.planName = 'Gói tùy chỉnh';
        }
        targetUser.status = (parsed.getTime() > Date.now()) ? 'active' : 'expired';
    } else if (Number.isFinite(days) && days !== 0) {
        // V4-07 & BUG-40a: Dùng canonical normalizeEntitlement để xác định VIP Vĩnh Viễn
        const userEnt = normalizeEntitlement(targetUser);
        if (userEnt.isPermanent) {
            return res.json({
                ok: true,
                changed: false,
                message: `"${targetUser.username}" đang là VIP Vĩnh Viễn (không có hạn ngày) nên hệ thống giữ nguyên quyền lợi. Để chuyển sang hạn ngày, hãy dùng "Ngày cố định" hoặc đặt lại rõ ràng.`
            });
        }
        const now = Date.now();
        // Nếu người dùng đang là VIP Vĩnh Viễn (expiresAt === null) hoặc đã hết hạn:
        // Luôn tính bắt đầu từ thời điểm hiện tại (now)!
        // Nếu đang có hạn dùng cụ thể và chưa hết hạn: Tính tiếp từ mốc hạn đó.
        let baseTime = now;
        if (targetUser.expiresAt) {
            const currentExp = Date.parse(targetUser.expiresAt);
            if (!isNaN(currentExp) && currentExp > now) {
                baseTime = currentExp;
            }
        }
        const newExpMs = baseTime + days * 86400000;
        targetUser.expiresAt = new Date(newExpMs).toISOString();
        if (typeof req.body?.planName === 'string' && req.body.planName.trim()) {
            targetUser.planName = req.body.planName.trim();
        } else if (targetUser.planName === 'VIP Vĩnh Viễn') {
            targetUser.planName = days > 0 ? `Gói ${days} ngày` : 'Gói tùy chỉnh';
        }
        targetUser.status = (newExpMs > now) ? 'active' : 'expired';
    } else {
        return res.status(400).json({ ok: false, error: 'Tham số gia hạn không hợp lệ.' });
    }

    targetUser.updatedAt = new Date().toISOString();
    users[userIndex] = targetUser;
    const saved = await saveUsers(users);
    if (!saved) {
        users[userIndex] = userBackup;
        return res.status(500).json({ ok: false, error: 'Không thể lưu thông tin gia hạn người dùng.' });
    }

    // BUG-30: gia hạn có thể biến user thành 'expired' (trừ ngày / fixedDate trong quá khứ).
    // Phải chạy đúng lifecycle như Watchdog: thu hồi session + reconcile lifecycle bot.
    const renewWarnings = [];
    let renewSessionRevokeError = null;
    if (targetUser.status !== 'active' || (targetUser.expiresAt && Date.parse(targetUser.expiresAt) <= Date.now())) {
        const sessionResult = await revokeUserSessions(targetUser);
        if (!sessionResult.ok) {
            renewSessionRevokeError = sessionResult.error || 'Chưa xác nhận thu hồi mọi session.';
        }
    }
    const renewLifecycle = await reconcileUserBotLifecycle(userBackup, targetUser, 'admin renew-days');

    // §3.3 & V3-01: Tự động tái cấp bot và đẩy warning nếu chưa cấp đủ
    let reallocResult = null;
    if (targetUser.status === 'active' && (!Array.isArray(targetUser.assignedBotIds) || targetUser.assignedBotIds.length === 0)) {
        try {
            reallocResult = await reconcileUserReactivationAndBotAllocation(targetUser.username, { req, context: 'admin_renew_days' });
            if (reallocResult?.ok && Array.isArray(reallocResult.assignedBotIds)) {
                targetUser.assignedBotIds = reallocResult.assignedBotIds;
            } else if (reallocResult && (!reallocResult.ok || reallocResult.partial || reallocResult.allocationStatus === 'pending_retry' || reallocResult.allocationStatus === 'partial')) {
                const allocWarn = (reallocResult.warnings && reallocResult.warnings[0]) || ('Cảnh báo cấp bot: ' + (reallocResult.error || 'Chưa đủ bot trống để cấp lại cho người dùng.'));
                renewWarnings.push(allocWarn);
            }
        } catch (reallocErr) {
            console.warn('[RENEW-DAYS] Lỗi tái cấp bot tự động:', reallocErr.message);
            renewWarnings.push('Lỗi tái cấp bot tự động: ' + reallocErr.message);
        }
    }

    // BUG-29: hạn thuê ĐÃ commit; auth-sync có retry 60s → trả ok:true + warnings thay vì 502.
    const renewAuthSyncDetailed = await syncAuthToAllBotsDetailed(true);
    if (renewSessionRevokeError) renewWarnings.push(renewSessionRevokeError);
    if (!renewLifecycle.ok) renewWarnings.push('Chưa hoàn tất lifecycle bot: ' + (renewLifecycle.error || 'lý do không xác định.'));
    if (!renewAuthSyncDetailed?.ok) {
        const failedBots = (renewAuthSyncDetailed?.results || []).filter(r => !r.ok);
        for (const f of failedBots) {
            await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'ADMIN_RENEW_USER', target: targetUser.username } });
        }
        renewWarnings.push('Chưa đồng bộ auth tới ' + failedBots.length + '/' + (renewAuthSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
    }
    logAuditEvent({
        req,
        action: 'ADMIN_RENEW_USER',
        target: { userId: targetUser.id, username: targetUser.username },
        details: `Quản trị viên gia hạn cho ${targetUser.username}: Hạn mới = ${targetUser.expiresAt || 'Vĩnh viễn'} (Gói: ${targetUser.planName})` + (renewWarnings.length ? ' | ' + renewWarnings.join('; ') : ''),
        status: renewWarnings.length ? 'PARTIAL' : 'SUCCESS'
    });

    const safeTargetUser = { ...targetUser, password: '' };
    return res.json({
        ok: true,
        coreCommitted: true,
        syncStatus: renewWarnings.length > 0 ? 'pending_retry' : 'synced',
        partial: renewWarnings.length > 0,
        allocationStatus: reallocResult?.allocationStatus || (targetUser.assignedBotIds?.length ? 'allocated' : 'none'),
        missingBotCount: reallocResult?.missingBotCount || 0,
        warnings: renewWarnings.length ? renewWarnings : undefined,
        user: safeTargetUser,
        message: `Gia hạn thành công cho "${targetUser.username}"! Hạn mới: ${targetUser.expiresAt ? new Date(targetUser.expiresAt).toLocaleString('vi-VN') : 'Vĩnh viễn'}.`
    });
});

// Admin: Lấy danh sách Audit Logs & Phân trang, Bộ lọc
app.get('/api/manager/audit-logs', async (req, res) => {
    try {
        const session = getSessionUser(req);
        if (!session || session.role !== 'admin') {
            return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên mới có quyền xem Audit Logs.' });
        }
        const limit = Math.max(1, Math.min(200, Number(req.query?.limit || 50)));
        const page = Math.max(1, Number(req.query?.page || 1));
        const q = String(req.query?.q || '').trim();
        const category = String(req.query?.category || '').trim();
        const status = String(req.query?.status || '').trim();
        const actor = String(req.query?.actor || '').trim();
        const botId = String(req.query?.botId || '').trim();
        const logType = String(req.query?.logType || '').trim();

        if (!supabaseAdapter || !supabaseAdapter.isEnabled()) {
            const memoryResult = readAuditLogs({ limit, page, logType, category });
            return res.json({
                ok: true,
                logs: memoryResult.logs,
                total: memoryResult.total,
                page: memoryResult.page,
                limit: memoryResult.limit,
                totalPages: memoryResult.totalPages
            });
        }
        const result = await supabaseAdapter.fetchAuditLogs({ logType, category, status, q, actor, botId, limit, page });
        if (!result) return res.status(502).json({ ok: false, error: 'Không thể tải Audit Log từ Supabase.' });
        res.json({
            ok: true,
            logs: result.logs,
            total: result.total,
            page: result.page,
            limit: result.limit,
            totalPages: result.totalPages
        });
    } catch (err) {
        console.error('[AUDIT] Lỗi đọc audit logs:', err.message);
        res.status(500).json({ ok: false, error: 'Lỗi máy chủ khi đọc danh sách Audit Logs.' });
    }
});

// Admin: Xuất file Audit Logs (CSV / JSONL)
app.get('/api/manager/audit-logs/export', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ ok: false, error: 'Chỉ Quản trị viên mới có quyền xuất Audit Logs.' });
    }
    const format = String(req.query?.format || 'csv').toLowerCase() === 'jsonl' ? 'jsonl' : 'csv';
    const dateStr = new Date().toISOString().slice(0, 10);
    if (!supabaseAdapter?.isEnabled() || !supabaseStorageReady) return res.status(503).json({ ok: false, error: 'Supabase chưa sẵn sàng để xuất Audit Logs.' });
    const firstPage = await supabaseAdapter.fetchAuditLogs({ limit: 1000, page: 1 });
    if (!firstPage) return res.status(502).json({ ok: false, error: 'Không thể tải Audit Logs từ Supabase.' });
    const entries = [...firstPage.logs];
    for (let page = 2; page <= Math.min(firstPage.totalPages, 100); page++) {
        const next = await supabaseAdapter.fetchAuditLogs({ limit: 1000, page });
        if (!next) return res.status(502).json({ ok: false, error: `Không thể tải trang Audit Logs ${page}.` });
        entries.push(...next.logs);
    }
    const content = exportAuditLogsFile(format, entries);

    if (format === 'jsonl') {
        res.setHeader('Content-Type', 'application/x-ndjson; charset=utf-8');
        res.setHeader('Content-Disposition', `attachment; filename="kingmc_audit_logs_${dateStr}.jsonl"`);
    } else {
        res.setHeader('Content-Type', 'text/csv; charset=utf-8');
        res.setHeader('Content-Disposition', `attachment; filename="kingmc_audit_logs_${dateStr}.csv"`);
    }
    res.send(content);
});

