app.post('/api/manager/keys', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ error: 'Chỉ Quản trị viên mới có quyền tạo Key.' });
    }
    const rawDays = Number(req.body?.days);
    const isPermanent = req.body?.isPermanent === true || req.body?.setPermanent === true || rawDays === -1;
    const days = isPermanent ? -1 : (Number.isFinite(rawDays) && rawDays >= 1 ? Math.min(Math.floor(rawDays), 36500) : 7);
    const planName = (req.body?.planName || (isPermanent ? 'VIP Vĩnh Viễn' : `Gói ${days} Ngày`)).trim();
    const botIds = Array.isArray(req.body?.botIds) ? req.body.botIds.map(Number).filter(Number.isFinite) : [];
    const rawBotCount = Number(req.body?.botCount);
    const botCount = Number.isFinite(rawBotCount) && rawBotCount >= 1 ? Math.min(Math.floor(rawBotCount), 50) : (botIds.length || 1);
    const rawCount = Number(req.body?.count);
    const count = Number.isFinite(rawCount) && rawCount >= 1 ? Math.min(Math.floor(rawCount), 50) : 1;

    // Giới hạn số lượt dùng tối đa trên toàn server (1 = key cá nhân, n = giftcode, 0 = không giới hạn)
    const rawMaxUses = req.body?.maxUses === undefined || req.body?.maxUses === '' ? 1 : Number(req.body.maxUses);
    const maxUses = normalizeMaxUses(rawMaxUses);
    if (maxUses === null) return res.status(400).json({ error: 'maxUses phải là số nguyên không âm; 0 là không giới hạn.' });

    // Thời hạn áp dụng của mã Code (ngày hết hạn hoặc số ngày có hiệu lực validDays)
    let expiresAt = null;
    if (req.body?.expiresAt) {
        const expMs = Date.parse(req.body.expiresAt);
        if (!isNaN(expMs)) expiresAt = new Date(expMs).toISOString();
    } else if (req.body?.validDays) {
        const vDays = Number(req.body.validDays);
        if (Number.isFinite(vDays) && vDays > 0) {
            expiresAt = new Date(Date.now() + vDays * 86400000).toISOString();
        }
    }

    const customKey = String(req.body?.customKey || req.body?.customCode || '').trim().toUpperCase();

    const keysList = await loadKeysFresh();
    if (!Array.isArray(keysList)) return res.status(503).json({ ok: false, error: 'Không đọc được danh sách Key mới nhất từ Supabase.' });
    const createdKeys = [];

    for (let i = 0; i < count; i++) {
        let keyStr;
        if (count === 1 && customKey) {
            keyStr = customKey;
            if (keysList.some(k => normalizeKeyCode(k) === keyStr)) {
                return res.status(400).json({ ok: false, error: `Mã Key/Giftcode "${keyStr}" đã tồn tại. Vui lòng chọn mã khác!` });
            }
        } else {
            const rand = crypto.randomBytes(6).toString('hex').toUpperCase();
            keyStr = customKey ? `${customKey}-${rand.slice(0, 4)}` : (isPermanent ? `KINGMC-LIFE-${rand}` : `KINGMC-${days}D-${rand}`);
        }

        const keyItem = {
            key: keyStr,
            days,
            isPermanent: isPermanent ? true : false,
            planName,
            botIds,
            botCount,           // Số lượng bot cấp cho tài khoản khi kích hoạt
            maxUses,            // Giới hạn lượt dùng (1 = private key, n = giftcode, 0 = không giới hạn)
            usedCount: 0,       // Số lượt đã dùng
            usedUsers: [],      // Danh sách username đã nhập mã (mỗi user chỉ dùng được 1 lần)
            expiresAt,          // Hạn áp dụng mã (null = vĩnh viễn)
            createdAt: new Date().toISOString(),
            used: false,
            usedBy: null,
            usedAt: null
        };
        keysList.unshift(keyItem);
        createdKeys.push(keyItem);
    }

    const saved = supabaseAdapter?.isEnabled?.() ? (await supabaseAdapter.insertKeys(createdKeys)) : true;
    if (!saved) {
        const latest = await supabaseAdapter.fetchKeys();
        if (customKey && Array.isArray(latest) && latest.some(key => normalizeKeyCode(key) === customKey)) {
            setKeysCache(latest);
            return res.status(409).json({ ok: false, error: `Mã Key/Giftcode "${customKey}" vừa được tạo ở phiên khác.` });
        }
        return res.status(502).json({ ok: false, error: 'Không thể chèn Key mới lên Supabase; dữ liệu hiện có không bị ghi đè.' });
    }
    const latestKeys = supabaseAdapter?.isEnabled?.() ? (await supabaseAdapter.fetchKeys()) : null;
    setKeysCache(Array.isArray(latestKeys) ? latestKeys : [...createdKeys, ...keysList]);
    logAuditEvent({
        req,
        action: 'LICENSE_KEYS_CREATE',
        details: `Tạo ${count} mã key (${days} ngày, gói ${planName}, maxUses: ${maxUses}, expiresAt: ${expiresAt || 'Vô thời hạn'})`,
        status: 'SUCCESS'
    });

    res.json({ ok: true, message: `Đã tạo ${count} mã Key/Giftcode thành công!`, keys: createdKeys });
});

app.delete('/api/manager/keys/:key', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ error: 'Chỉ Quản trị viên mới có quyền xóa Key.' });
    }
    const targetKey = String(req.params.key || '').trim().toUpperCase();
    let keysList = await loadKeysFresh();
    if (!Array.isArray(keysList)) return res.status(503).json({ ok: false, error: 'Không đọc được danh sách Key mới nhất từ Supabase.' });
    const exists = keysList.some(k => normalizeKeyCode(k) === targetKey);
    if (!exists) return res.status(404).json({ error: 'Key không tồn tại.' });

    if (supabaseAdapter?.isEnabled?.()) {
        if (!(await supabaseAdapter.deleteKey(targetKey))) {
            return res.status(502).json({ ok: false, error: 'Không thể xóa đúng Key trên Supabase.' });
        }
    }
    keysList = keysList.filter(k => normalizeKeyCode(k) !== targetKey);
    setKeysCache(keysList);
    logAuditEvent({
        req,
        action: 'LICENSE_KEY_DELETE',
        target: { key: maskLicenseKey(targetKey) },
        details: `Xóa mã key ${maskLicenseKey(targetKey)}`,
        status: 'SUCCESS'
    });

    res.json({ ok: true, message: `Đã xóa mã Key ${maskLicenseKey(targetKey)}.` });
});

// 2. Gia hạn bằng Key (User hoặc Khách tại Login Gate)
// Toàn bộ giao dịch nạp Key phải nằm trong withRegisterLock (dùng chung khóa
// với /api/auth/register) để hai luồng tiêu thụ Key không chạy song song.
// V4-07: Đồng bộ route /api/manager/renew và /api/manager/rental/redeem-key
app.post('/api/manager/renew', (req, res) => handleManagerRenewExecution(req, res));
app.post('/api/manager/rental/redeem-key', (req, res) => handleManagerRenewExecution(req, res));

function handleManagerRenewExecution(req, res) {
    return withRegisterLock(async () => {
    let renewalResetPartial = false;
    let renewalResetPerformed = false;
    let keyRenewAllocationWarning = '';
    try {
        const rawKey = String(req.body?.key || req.body?.licenseKey || '').trim().toUpperCase();
        const username = String(req.body?.username || '').trim().toLowerCase();
        const password = String(req.body?.password ?? '');

        if (!rawKey) {
            return res.status(400).json({ error: 'Vui lòng nhập mã Key gia hạn.' });
        }

        const session = getSessionUser(req);
        const rateLimitUsername = session?.username || username;
        const rateCheck = checkRenewRateLimit(req, rateLimitUsername);
        if (!rateCheck.allowed) {
            return res.status(429).json({ ok: false, error: rateCheck.error });
        }

        const keysList = await loadKeysFresh();
        if (!Array.isArray(keysList)) {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(503).json({ ok: false, error: 'Không đọc được danh sách Key mới nhất từ Supabase.' });
        }
        const keyItem = keysList.find(k => normalizeKeyCode(k) === rawKey);
        if (!keyItem) {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(404).json({ error: 'Mã Key / Giftcode gia hạn không hợp lệ hoặc không tồn tại.' });
        }

        let users = await loadUsersFreshOrThrow();
        let targetUser = null;
        if (session) {
            targetUser = users.find(u => u.username.toLowerCase() === session.username.toLowerCase());
        } else if (username && password) {
            const u = users.find(x => x.username.toLowerCase() === username.toLowerCase());
            if (u && verifyUserPassword(password, u.password)) {
                targetUser = u;
            } else {
                recordRenewAttempt(req, rateLimitUsername, false);
                return res.status(401).json({ error: 'Tên đăng nhập hoặc mật khẩu không chính xác.' });
            }
        } else {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(400).json({ error: 'Vui lòng cung cấp Username và Mật khẩu tài khoản cần gia hạn.' });
        }

        if (!targetUser) {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(404).json({ error: 'Không tìm thấy tài khoản người dùng.' });
        }

        if (targetUser.status === 'disabled') {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(403).json({ ok: false, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
        }

        // BUG-40a: user VIP Vĩnh Viễn (expiresAt === null) kích hoạt Key KHÔNG bị âm
        // thầm chuyển thành hạn ngày và KHÔNG bị tiêu Key. Admin muốn chuyển plan
        // phải làm rõ ràng qua add-days/renew-days (setPermanent/fixedDate).
        const ent = normalizeEntitlement(targetUser);
        if (ent.isPermanent === true || targetUser.isPermanent === true || targetUser.expiresAt === null) {
            recordRenewAttempt(req, rateLimitUsername, true);
            return res.json({
                ok: true,
                changed: false,
                message: '🎉 Tài khoản của bạn là VIP Vĩnh Viễn — không cần kích hoạt thêm Key. Key chưa được sử dụng, hãy giữ lại hoặc liên hệ Admin nếu muốn chuyển gói.'
            });
        }

        const keyCheck = checkKeyValidity(keyItem, targetUser.username);
        if (!keyCheck.ok) {
            recordRenewAttempt(req, rateLimitUsername, false);
            return res.status(400).json({ error: keyCheck.error });
        }

        // Cộng dồn hạn thuê
        const isPermanentKey = keyItem.isPermanent === true || keyItem.days === -1;
        if (isPermanentKey) {
            targetUser.expiresAt = null;
            targetUser.isPermanent = true;
            targetUser.status = 'active';
            if (keyItem.planName) targetUser.planName = keyItem.planName;
            else targetUser.planName = 'VIP Vĩnh Viễn';
        } else {
            targetUser.isPermanent = false;
            const now = Date.now();
            const baseTime = (targetUser.expiresAt && Date.parse(targetUser.expiresAt) > now)
                ? Date.parse(targetUser.expiresAt)
                : now;

            targetUser.expiresAt = new Date(baseTime + keyItem.days * 86400000).toISOString();
            targetUser.status = 'active';
            if (keyItem.planName) targetUser.planName = keyItem.planName;
        }

        // Gán thêm bot nếu key có chỉ định
        if (Array.isArray(keyItem.botIds) && keyItem.botIds.length > 0) {
            const currentBots = Array.isArray(targetUser.assignedBotIds) ? targetUser.assignedBotIds.map(Number) : [];
            const newlyAssigned = keyItem.botIds.map(Number).filter(id => !currentBots.includes(id));
            if (newlyAssigned.length > 0) {
                const resetRes = await resetBotsForAssignment(newlyAssigned, `gia hạn Key cho "${targetUser.username}"`);
                if (!resetRes.ok) {
                    recordRenewAttempt(req, rateLimitUsername, false);
                    return res.status(500).json({ ok: false, partial: resetRes.partial === true, error: `Không thể dọn dẹp reset Bot #${resetRes.botId} để bàn giao (${resetRes.error}). Vui lòng liên hệ Admin!` });
                }
                renewalResetPerformed = true;
                renewalResetPartial = resetRes.partial === true;
                const preserved = { expiresAt: targetUser.expiresAt, status: targetUser.status, planName: targetUser.planName, isPermanent: targetUser.isPermanent, botCount: Math.max(parseInt(targetUser.botCount, 10) || 1, keyItem.botIds.length) };
                users = await loadUsersFreshOrThrow();
                const freshTarget = users.find(u => String(u.id) === String(targetUser.id) || u.username.toLowerCase() === targetUser.username.toLowerCase());
                if (!freshTarget) return res.status(409).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản đã thay đổi trong lúc reset bot; vui lòng tải lại trang và thử lại.' });
                if (freshTarget.status === 'disabled') {
                    return res.status(403).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
                }
                targetUser = freshTarget;
                targetUser.expiresAt = preserved.expiresAt;
                targetUser.status = preserved.status;
                targetUser.planName = preserved.planName;
                targetUser.isPermanent = preserved.isPermanent;
                targetUser.botCount = preserved.botCount;
            }
            const freshCurrentBots = Array.isArray(targetUser.assignedBotIds) ? targetUser.assignedBotIds.map(Number) : [];
            targetUser.assignedBotIds = [...new Set([...freshCurrentBots, ...keyItem.botIds.map(Number)])];
            targetUser.botCount = Math.max(parseInt(targetUser.botCount, 10) || 1, targetUser.assignedBotIds.length);
            assignBotsExclusively(users, targetUser.id || targetUser.username, keyItem.botIds);
        } else {
            const keyBotCount = Number(keyItem.botCount) || 1;
            targetUser.botCount = Math.max(parseInt(targetUser.botCount, 10) || 1, keyBotCount);
            const currentRenewBots = Array.isArray(targetUser.assignedBotIds) ? targetUser.assignedBotIds.map(Number) : [];
            if (keyBotCount > 0 && currentRenewBots.length < keyBotCount) {
                const needed = keyBotCount - currentRenewBots.length;
                const alloc = await allocateBotsForUser(targetUser.username, needed);
                if (alloc.ok && alloc.botIds.length > 0) {
                    const preserved = { expiresAt: targetUser.expiresAt, status: targetUser.status, planName: targetUser.planName, isPermanent: targetUser.isPermanent, botCount: targetUser.botCount };
                    users = await loadUsersFreshOrThrow();
                    const freshTarget = users.find(u => String(u.id) === String(targetUser.id) || u.username.toLowerCase() === targetUser.username.toLowerCase());
                    if (!freshTarget) return res.status(409).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản đã thay đổi trong lúc cấp bot; vui lòng tải lại trang và thử lại.' });
                    if (freshTarget.status === 'disabled') {
                        return res.status(403).json({ ok: false, partial: renewalResetPerformed, error: 'Tài khoản của bạn đã bị vô hiệu hóa hoặc khóa bởi Quản trị viên.' });
                    }
                    targetUser = freshTarget;
                    targetUser.expiresAt = preserved.expiresAt;
                    targetUser.status = preserved.status;
                    targetUser.planName = preserved.planName;
                    targetUser.isPermanent = preserved.isPermanent;
                    targetUser.botCount = preserved.botCount;
                    const freshUserBots = Array.isArray(targetUser.assignedBotIds) ? targetUser.assignedBotIds.map(Number) : [];
                    targetUser.assignedBotIds = [...new Set([...freshUserBots, ...alloc.botIds])];
                    assignBotsExclusively(users, targetUser.id || targetUser.username, targetUser.assignedBotIds);
                    renewalResetPerformed = true;
                    renewalResetPartial = alloc.partial === true;
                }
                if (!alloc.ok || (alloc.botIds || []).length < needed) {
                    // Hết bot / cấp một phần: Key vẫn cấp ĐÚNG giá trị chính (số ngày) —
                    // không nuốt tình trạng thiếu bot; báo rõ để user/admin biết xử lý.
                    const granted = (alloc.botIds || []).length;
                    keyRenewAllocationWarning = 'Key quy định ' + keyBotCount + ' bot nhưng hệ thống chỉ cấp được ' + granted + '/' + needed + ' bot' + (alloc.error ? ' (' + alloc.error + ')' : '(hệ thống đang hết bot trống)') + '. Vui lòng liên hệ Admin nếu cần bổ sung bot.';
                    console.warn('[RENEW] Cấp bot theo botCount thiếu mục tiêu: ' + keyRenewAllocationWarning);
                }
            }
        }

        const keyCommit = await commitKeyConsumptionAtomic(keyItem, targetUser.username, users);
        if (!keyCommit.ok) {
            return res.status(keyCommit.status || 409).json({
                ok: false,
                partial: renewalResetPerformed,
                error: (renewalResetPerformed ? 'Bot đã được reset và quyền cũ đã thu hồi, nhưng ' : '') +
                    (keyCommit.conflict ? 'mã Key vừa được sử dụng bởi một giao dịch khác. ' : 'không ghi được lượt dùng Key. ') +
                    'Vui lòng thử lại!'
            });
        }
        // BUG-29: Key + hạn thuê ĐÃ commit; auth-sync có retry 60s → trả ok:true + warnings.
        const keyRenewSyncDetailed = await syncAuthToAllBotsDetailed(true);
        const keyRenewWarnings = [];
        if (!keyRenewSyncDetailed?.ok) {
            const failedBots = (keyRenewSyncDetailed?.results || []).filter(r => !r.ok);
            for (const f of failedBots) {
                await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'RENTAL_RENEW_KEY', target: targetUser.username } });
            }
            keyRenewWarnings.push('Key và hạn thuê đã lưu thành công nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (keyRenewSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
        }
        recordRenewAttempt(req, targetUser.username, true);

        const renewMessage = isPermanentKey
            ? '🎉 Kích hoạt Key VIP Vĩnh Viễn thành công! Hạn sử dụng: Vĩnh viễn'
            : `🎉 Gia hạn thành công ${keyItem.days} ngày! Hạn sử dụng mới đến: ${new Date(targetUser.expiresAt).toLocaleString('vi-VN')}`;

        logAuditEvent({
            req,
            action: 'RENTAL_RENEW_KEY',
            target: { username: targetUser.username, key: maskLicenseKey(keyItem.key) },
            details: (isPermanentKey ? `Kích hoạt Key VIP Vĩnh Viễn ${maskLicenseKey(keyItem.key)}` : `Kích hoạt Key ${maskLicenseKey(keyItem.key)} cộng ${keyItem.days} ngày (Hạn mới: ${targetUser.expiresAt})`) + (renewalResetPartial ? ' | Bot bàn giao reset chưa xóa hết log Cloud.' : '') + (keyRenewAllocationWarning ? ' | ' + keyRenewAllocationWarning : '') + (keyRenewWarnings.length ? ' | ' + keyRenewWarnings.join('; ') : ''),
            status: renewalResetPartial || keyRenewWarnings.length || keyRenewAllocationWarning ? 'PARTIAL' : 'SUCCESS'
        });

        res.json({
            ok: true,
            coreCommitted: true,
            syncStatus: (keyRenewWarnings.length > 0 || renewalResetPartial) ? 'pending_retry' : 'synced',
            partial: renewalResetPartial || keyRenewWarnings.length > 0,
            warnings: keyRenewWarnings.length ? keyRenewWarnings : undefined,
            warning: [keyRenewAllocationWarning, renewalResetPartial ? 'Gia hạn thành công nhưng bot bàn giao chưa xóa hết log Cloud; kiểm tra log worker.' : ''].filter(Boolean).join(' ') || undefined,
            message: renewMessage,
            expiresAt: targetUser.expiresAt,
            planName: targetUser.planName,
            assignedBotIds: targetUser.assignedBotIds
        });
    } catch (err) {
        console.error('[RENEW] Lỗi gia hạn tài khoản:', err.message);
        res.status(500).json({ ok: false, error: 'Lỗi máy chủ khi xử lý gia hạn mã Key.' });
    }
    });
}

// 3. Admin Cộng Ngày Thuê Thủ Công (+1, +3, +7, +15, +30, -1 Vĩnh Viễn)
app.post('/api/manager/user/:username/add-days', async (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ error: 'Chỉ Quản trị viên mới có quyền cộng hạn thuê.' });
    }
    const username = String(req.params.username || '').trim().toLowerCase();
    const days = Number(req.body?.days);
    const users = await loadUsersFreshOrThrow();
    const userIndex = users.findIndex(u => u.username?.toLowerCase() === username);
    if (userIndex === -1) return res.status(404).json({ error: 'Không tìm thấy người dùng.' });
    const userBackup = JSON.parse(JSON.stringify(users[userIndex]));
    const targetUser = users[userIndex];

    if (days === -1 && (req.body?.isPermanent === true || req.body?.permanent === true || !req.body?.days || req.body.days === -1)) {
        // Vĩnh viễn
        targetUser.expiresAt = null;
        targetUser.isPermanent = true;
        targetUser.planName = (typeof req.body?.planName === 'string' && req.body.planName.trim()) ? req.body.planName.trim() : 'VIP Vĩnh Viễn';
        targetUser.status = 'active';
    } else if (Number.isFinite(days) && days !== 0) {
        // V4-07 & BUG-40a: Dùng canonical normalizeEntitlement để xác định VIP Vĩnh Viễn
        const userEnt = normalizeEntitlement(targetUser);
        if (userEnt.isPermanent) {
            return res.json({
                ok: true,
                changed: false,
                message: `Khách "${username}" đang là VIP Vĩnh Viễn (không có hạn ngày) nên hệ thống giữ nguyên quyền lợi. Để chuyển sang hạn ngày, hãy dùng "Ngày cố định" hoặc đặt lại rõ ràng.`
            });
        }
        const now = Date.now();
        let baseTime = now;
        if (targetUser.expiresAt) {
            const currentExp = Date.parse(targetUser.expiresAt);
            if (!isNaN(currentExp) && (days < 0 || currentExp > now)) {
                baseTime = currentExp;
            }
        }
        const newExpMs = baseTime + days * 86400000;
        targetUser.expiresAt = new Date(newExpMs).toISOString();
        targetUser.status = (newExpMs > now) ? 'active' : 'expired';
    } else {
        return res.status(400).json({ error: 'Số ngày không hợp lệ.' });
    }

    targetUser.updatedAt = new Date().toISOString();
    users[userIndex] = targetUser;
    const saved = await saveUsers(users);
    if (!saved) {
        users[userIndex] = userBackup;
        return res.status(500).json({ ok: false, error: 'Không thể lưu hạn thuê của người dùng vào hệ thống.' });
    }

    // BUG-30 & NEW-V11.8-05: gia hạn có thể làm hết hạn hoặc kích hoạt lại bot.
    // Phải chạy đúng lifecycle như renew-days: thu hồi session + reconcile lifecycle bot.
    const addDaysSyncWarnings = [];
    let addDaysSessionRevokeError = null;
    if (targetUser.status !== 'active' || (targetUser.expiresAt && Date.parse(targetUser.expiresAt) <= Date.now())) {
        const sessionResult = await revokeUserSessions(targetUser);
        if (!sessionResult.ok) {
            addDaysSessionRevokeError = sessionResult.error || 'Chưa xác nhận thu hồi mọi session.';
        }
    }
    const addDaysLifecycle = await reconcileUserBotLifecycle(userBackup, targetUser, 'admin add-days');

    // §3.3 & V3-01: Tự động tái cấp bot và ghi nhận cảnh báo
    let reallocResult = null;
    if (targetUser.status === 'active' && (!Array.isArray(targetUser.assignedBotIds) || targetUser.assignedBotIds.length === 0)) {
        try {
            reallocResult = await reconcileUserReactivationAndBotAllocation(username, { req, context: 'admin_add_days' });
            if (reallocResult?.ok && Array.isArray(reallocResult.assignedBotIds)) {
                targetUser.assignedBotIds = reallocResult.assignedBotIds;
            } else if (reallocResult && (!reallocResult.ok || reallocResult.partial || reallocResult.allocationStatus === 'pending_retry' || reallocResult.allocationStatus === 'partial')) {
                const allocWarn = (reallocResult.warnings && reallocResult.warnings[0]) || ('Cảnh báo cấp bot: ' + (reallocResult.error || 'Chưa đủ bot trống để cấp lại cho người dùng.'));
                addDaysSyncWarnings.push(allocWarn);
            }
        } catch (reallocErr) {
            console.warn('[ADD-DAYS] Lỗi tái cấp bot tự động:', reallocErr.message);
            addDaysSyncWarnings.push('Lỗi tái cấp bot tự động: ' + reallocErr.message);
        }
    }

    // BUG-29: Hạn thuê ĐÃ commit; auth-sync có retry 60s → trả ok:true + warnings thay vì 502 sau commit.
    const addDaysSyncDetailed = await syncAuthToAllBotsDetailed(true);
    if (!addDaysSyncDetailed?.ok) {
        const failedBots = (addDaysSyncDetailed?.results || []).filter(r => !r.ok);
        for (const f of failedBots) {
            await enqueueOutboxSync(f.botId, { type: 'auth_sync', committedTransaction: { type: 'ADMIN_EXTEND_RENTAL', target: username } });
        }
        addDaysSyncWarnings.push('Hạn thuê đã lưu thành công nhưng chưa đồng bộ được auth tới ' + failedBots.length + '/' + (addDaysSyncDetailed?.results || []).length + ' bot' + (failedBots.length ? ' (' + failedBots.map(f => '#' + f.botId).join(', ') + ')' : '') + '. Hệ thống sẽ tự thử đồng bộ lại trong khoảng 60 giây.');
    }
    logAuditEvent({
        req,
        action: 'ADMIN_EXTEND_RENTAL',
        target: { username },
        details: `Cộng ${days === -1 ? 'Vĩnh viễn' : days + ' ngày'} cho khách ${username} (Hạn mới: ${targetUser.expiresAt || 'Vĩnh viễn'})` + (addDaysSyncWarnings.length ? ' | ' + addDaysSyncWarnings.join('; ') : ''),
        status: addDaysSyncWarnings.length ? 'PARTIAL' : 'SUCCESS'
    });

    res.json({
        ok: true,
        coreCommitted: true,
        syncStatus: addDaysSyncWarnings.length > 0 ? 'pending_retry' : 'synced',
        partial: addDaysSyncWarnings.length > 0,
        allocationStatus: reallocResult?.allocationStatus || (targetUser.assignedBotIds?.length ? 'allocated' : 'none'),
        missingBotCount: reallocResult?.missingBotCount || 0,
        warnings: addDaysSyncWarnings.length ? addDaysSyncWarnings : undefined,
        message: `Đã cập nhật hạn thuê cho ${username} thành công!`,
        expiresAt: targetUser.expiresAt,
        planName: targetUser.planName,
        status: targetUser.status
    });
});

// 7. Đồng Bộ Xác Thực Khách Thuê Cho Bot Con (Login Gate của Bot.js)
app.post('/api/auth/verify-bot-access', (req, res) => {
    // Yêu cầu xác thực service-to-service nội bộ
    if (!isBotSecretRequest(req)) {
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            details: 'Từ chối: X-Bot-Secret không hợp lệ hoặc thiếu.',
            status: 'BLOCKED'
        });
        return res.status(401).json({ ok: false, error: 'Khóa bảo mật nội bộ X-Bot-Secret không hợp lệ.' });
    }

    const clientIp = getClientIp(req);
    const username = String(req.body?.username || '').trim().toLowerCase();
    const password = String(req.body?.password ?? '');
    const botId = Number(req.body?.botId);

    // NEW-03 (Wave B0): per-bot secret phải khớp ĐÚNG bot đang được verify
    // (secret worker A + botId worker B → 401). Global secret của Manager
    // (BOT_SECRET_KEY) vẫn full-trust cho mọi bot — không phá triển khai hiện có.
    if (!isBotSecretRequestForBot(req, botId)) {
        verifyBotLimiter.record(clientIp, username || 'verify-bot', false);
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            target: { botId },
            details: 'Từ chối: X-Bot-Secret không khớp với bot #' + botId + ' (per-bot secret phải bind đúng bot ID).',
            status: 'BLOCKED'
        });
        return res.status(401).json({ ok: false, error: 'Khóa bảo mật nội bộ không khớp với bot được yêu cầu.' });
    }

    const rateLimit = verifyBotLimiter.check(clientIp, username || 'verify-bot');
    if (!rateLimit.allowed) {
        return res.status(429).json({ ok: false, error: rateLimit.error });
    }

    if (!username || !password) {
        verifyBotLimiter.record(clientIp, username || 'verify-bot', false);
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            target: { botId, username },
            details: 'Cổng Bot #' + botId + ': Từ chối do thiếu thông tin đăng nhập.',
            status: 'BLOCKED'
        });
        return res.status(400).json({ ok: false, error: 'Thiếu thông tin đăng nhập.' });
    }

    const users = loadUsers();
    let user = users.find(u => u.username.toLowerCase() === username);
    if (!user && username.toLowerCase() === 'admin') {
        const adminPass = getAdminPassword();
        if (verifyAdminPassword(password, adminPass)) {
            user = {
                id: 'admin',
                username: 'admin',
                password: adminPass,
                role: 'admin',
                status: 'active',
                expiresAt: null,
                allowAccountChange: true
            };
        } else {
            verifyBotLimiter.record(clientIp, username, false);
            logAuditEvent({
                req,
                action: 'AUTH_VERIFY_BOT_ACCESS',
                target: { botId, username },
                details: 'Cổng Bot #' + botId + ': Sai mật khẩu Quản trị viên.',
                status: 'FAILED'
            });
            return res.status(401).json({ ok: false, error: 'Mật khẩu Quản trị viên không chính xác.' });
        }
    }

    if (!user) {
        verifyBotLimiter.record(clientIp, username, false);
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            target: { botId, username },
            details: 'Cổng Bot #' + botId + ': Tài khoản "' + username + '" không tồn tại trên hệ thống.',
            status: 'BLOCKED'
        });
        return res.status(401).json({ ok: false, error: 'Tài khoản không tồn tại trên Manager.' });
    }

    if (user.role !== 'admin' && !verifyUserPassword(password, user.password)) {
        verifyBotLimiter.record(clientIp, username, false);
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            target: { botId, username },
            details: 'Cổng Bot #' + botId + ': Sai mật khẩu cho tài khoản "' + username + '".',
            status: 'FAILED'
        });
        return res.status(401).json({ ok: false, error: 'Mật khẩu không chính xác.' });
    }

    verifyBotLimiter.record(clientIp, username, true);

    if (user.role !== 'admin') {
        const isExpired = user.status === 'expired' || (user.expiresAt && Date.now() > Date.parse(user.expiresAt));
        if (isExpired) {
            logAuditEvent({
                req,
                action: 'AUTH_VERIFY_BOT_ACCESS',
                target: { botId, username },
                details: 'Cổng Bot #' + botId + ': Tài khoản "' + username + '" đã hết hạn thuê vào ngày ' + user.expiresAt + '.',
                status: 'BLOCKED'
            });
            return res.status(403).json({ ok: false, error: 'Tài khoản của bạn đã hết hạn thuê.' });
        }
        if (user.status !== 'active') {
            logAuditEvent({
                req,
                action: 'AUTH_VERIFY_BOT_ACCESS',
                target: { botId, username },
                details: 'Cổng Bot #' + botId + ': Tài khoản "' + username + '" đang bị vô hiệu hóa/khóa.',
                status: 'BLOCKED'
            });
            return res.status(403).json({ ok: false, error: 'Tài khoản đang bị khóa.' });
        }

        const hasBotId = Number.isFinite(botId) && (user.assignedBotIds || []).includes(botId);
        if (!hasBotId) {
            logAuditEvent({
                req,
                action: 'AUTH_VERIFY_BOT_ACCESS',
                target: { botId, username },
                details: 'Cổng Bot #' + botId + ': Khách "' + username + '" không có quyền điều khiển Bot #' + botId + '.',
                status: 'BLOCKED'
            });
            return res.status(403).json({ ok: false, error: 'Bạn không được cấp quyền điều khiển bot này.' });
        }
    }

    const userPlainPass = user.role === 'admin' ? null : decryptUserPassword(user.password);
    if (user.role !== 'admin' && userPlainPass === null) {
        logAuditEvent({
            req,
            action: 'AUTH_VERIFY_BOT_ACCESS',
            target: { botId, username: user.username },
            details: 'Cổng Bot #' + botId + ': Không thể giải mã mật khẩu của "' + user.username + '" bằng MANAGER_MASTER_KEY hiện tại.',
            status: 'FAILED'
        });
        return res.status(500).json({ ok: false, error: 'Không thể giải mã mật khẩu người dùng bằng MANAGER_MASTER_KEY hiện tại.' });
    }

    logAuditEvent({
        req,
        action: 'AUTH_VERIFY_BOT_ACCESS',
        target: { botId, username: user.username },
        details: 'Cổng Bot #' + botId + ': Xác thực thành công quyền truy cập cho "' + user.username + '" (' + (user.role === 'admin' ? 'Quản trị viên' : 'Khách thuê') + ')',
        status: 'SUCCESS'
    });

    const passwordHash = user.role === 'admin'
        ? getSyncAdminPasswordHash()
        : hashSyncUserPassword(user.id || user.username, userPlainPass);

    return res.json({
        ok: true,
        role: user.role,
        username: user.username,
        expiresAt: user.expiresAt,
        allowAccountChange: user.allowAccountChange !== false,
        passwordHash
    });
});

app.get(['/ready', '/api/ready'], (req, res) => {
    const keyReady = Boolean(getManagerCredentialKey() || !isProdRuntime);
    const storageReady = !supabaseAdapter.isEnabled() || supabaseStorageReady;
    const ready = keyReady && storageReady;
    const status = ready ? 200 : 503;
    res.status(status).json({
        ready,
        keyReady,
        storageReady,
        service: 'manager',
        timestamp: new Date().toISOString()
    });
});

app.get(['/healthz', '/api/health'], (req, res) => {
    const mem = process.memoryUsage();
    res.json({
        status: 'ok',
        service: 'manager',
        uptime: Math.round(process.uptime()),
        memory: {
            rssMb: Math.round(mem.rss / (1024 * 1024)),
            heapMb: Math.round(mem.heapUsed / (1024 * 1024))
        },
        fleet: {
            total: Array.isArray(BOT_CONFIG) ? BOT_CONFIG.length : 0
        },
        timestamp: new Date().toISOString()
    });
});

app.get('/api/status', (req, res) => {
    const session = getSessionUser(req);
    if (!session) {
        return res.status(401).json({ error: 'Chưa đăng nhập hệ thống.' });
    }
    let allowedConfigs = BOT_CONFIG;
    if (session.role !== 'admin') {
        const allowedSet = new Set((session.assignedBotIds || []).map(id => Number(id)));
        allowedConfigs = BOT_CONFIG.filter(c => allowedSet.has(Number(c.id)));
    }
    const bots = allowedConfigs.map(config => {
        return summaryCache.get(config.id)?.data ||
            buildUnavailableSummary(config, 'Đang kiểm tra bot...');
    });
    void refreshAllSummaries();
    res.json({
        status: 'ok',
        service: 'kingmc-manager',
        platform: MANAGER_PLATFORM,
        httpPort: HTTP_PORT,
        botCount: allowedConfigs.length,
        bots,
        cacheMs: BOT_SUMMARY_CACHE_MS
    });
});

app.get('/api/manager/diagnostics', (req, res) => {
    const session = getSessionUser(req);
    if (!session || session.role !== 'admin') {
        return res.status(403).json({ error: 'Chỉ Quản trị viên mới có quyền xem thông tin chẩn đoán.' });
    }
    res.json({
        ok: true,
        platform: MANAGER_PLATFORM,
        httpPort: HTTP_PORT,
        storage: { provider: 'Supabase', ready: supabaseStorageReady, configured: supabaseAdapter.isEnabled() },
        botCount: BOT_CONFIG.length,
        bots: BOT_CONFIG.map(bot => ({
            id: bot.id,
            label: bot.label,
            url: bot.url,
            source: bot.source,
            cached: summaryCache.has(bot.id)
        }))
    });
});

app.get('/', (req, res) => {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');

    const session = getSessionUser(req);
    if (!session) {
        const trialGiftEnabled = registry.systemSettings?.trialGiftEnabled !== false;
        const trialDays = Math.max(1, Math.min(365, parseInt(registry.systemSettings?.trialDays, 10) || 1));
        let loginHtml = PUBLIC_LOGIN_HTML;
        if (!trialGiftEnabled) {
            loginHtml = loginHtml
                .replace('id="publicTrialCalloutBadge"', 'id="publicTrialCalloutBadge" style="display:none;"')
                .replace('(Để trống nếu dùng thử)', '(Cần nhập Key để kích hoạt)')
                .replace('placeholder="Để trống để nhận 1 ngày dùng thử miễn phí..."', 'placeholder="Nhập mã Key kích hoạt gói thuê (Bắt buộc)..."');
        } else if (trialDays !== 1) {
            loginHtml = loginHtml
                .replace('1 NGÀY DÙNG THỬ MIỄN PHÍ', `${trialDays} NGÀY DÙNG THỬ MIỄN PHÍ`)
                .replace('1 ngày dùng thử miễn phí...', `${trialDays} ngày dùng thử miễn phí...`);
        }
        return res.type('html').send(loginHtml);
    }

    const mem = process.memoryUsage();
    const rssMb = Math.round(mem.rss / (1024 * 1024));
    let renderedHtml = HTML
        .replace('id="globalManagerRam">-- MB', `id="globalManagerRam">${rssMb} MB`)
        .replace('id="managerRamUsage">-- MB', `id="managerRamUsage">${rssMb} MB`)
        .replace('id="detailManagerRamUsage">-- MB', `id="detailManagerRamUsage">${rssMb} MB`);

    if (session.role === 'admin') {
        const adminBadge = '👑 <strong>ADMIN (Toàn quyền)</strong>';
        const adminStyle = 'background:rgba(234,179,8,0.2);color:#eab308;border-color:rgba(234,179,8,0.4);';
        renderedHtml = renderedHtml
            .replace(/style="background:rgba\(148,163,184,0\.15\);color:#94a3b8;border-color:rgba\(148,163,184,0\.3\);">🔒 CHƯA ĐĂNG NHẬP<\/span>/g, `style="${adminStyle}">${adminBadge}</span>`);
    } else {
        const escapedU = escapeHtml(session.username);
        const userBadge = `👤 <strong>USER: ${escapedU}</strong>`;
        const userStyle = 'background:rgba(56,189,248,0.2);color:#38bdf8;border-color:rgba(56,189,248,0.4);';
        renderedHtml = renderedHtml
            .replace(/style="background:rgba\(148,163,184,0\.15\);color:#94a3b8;border-color:rgba\(148,163,184,0\.3\);">🔒 CHƯA ĐĂNG NHẬP<\/span>/g, `style="${userStyle}">${userBadge}</span>`)
            .replace(/<span class="user-profile-name" id="globalUserProfileName">admin<\/span>/g, `<span class="user-profile-name" id="globalUserProfileName">${escapedU}</span>`)
            .replace(/<span class="user-avatar-badge" id="globalUserAvatarBadge">👑<\/span>/g, '<span class="user-avatar-badge" id="globalUserAvatarBadge">👤</span>');
    }

    const sessionData = {
        username: session.username,
        role: session.role,
        assignedBotIds: session.assignedBotIds || [],
        planName: session.planName || (session.role === 'admin' ? 'Admin VIP' : 'Gói thường'),
        expiresAt: session.expiresAtRental || null,
        allowAccountChange: session.allowAccountChange !== false,
        status: session.status || 'active'
    };
    const serializedSession = JSON.stringify(sessionData)
        .replace(/</g, '\\u003c')
        .replace(/>/g, '\\u003e')
        .replace(/&/g, '\\u0026')
        .replace(/\u2028/g, '\\u2028')
        .replace(/\u2029/g, '\\u2029');
    renderedHtml = renderedHtml.replace(
        'window.__INITIAL_USER__ = null;',
        `window.__INITIAL_USER__ = ${serializedSession};`
    );
    res.type('html').send(renderedHtml);
});

// Express Catch-All Error Handler (Mounted after all route handlers)
app.use((err, req, res, next) => {
    // Keep the client response generic, but log the actual stack locally so
    // route failures (including the dashboard '/') can be diagnosed reliably.
    console.error(`[UNHANDLED_ERROR] ${req.method} ${req.path}:`, err?.stack || String(err?.message || err?.name || 'Error'));
    if (res.headersSent) {
        return next(err);
    }
    return res.status(500).json({ ok: false, error: 'Đã xảy ra lỗi máy chủ nội bộ.' });
});

let lastClientApiAccessAt = Date.now();
let summaryRefreshTimer = null;

function scheduleSummaryRefresh() {
    if (summaryRefreshTimer) clearTimeout(summaryRefreshTimer);
    const isClientActive = (Date.now() - lastClientApiAccessAt) < 60000;
    const interval = isClientActive ? Math.max(BOT_POLL_MS, BOT_SUMMARY_CACHE_MS) : 30000;
    summaryRefreshTimer = setTimeout(async () => {
        try {
            await refreshAllSummaries();
        } catch (_) {}
        finally {
            scheduleSummaryRefresh();
        }
    }, interval);
    if (typeof summaryRefreshTimer.unref === 'function') summaryRefreshTimer.unref();
}

scheduleSummaryRefresh();

let server = null;
listenHttpServer(app, HTTP_PORT, MANAGER_PLATFORM, (serverInstance, activePort) => {
    server = serverInstance;
    HTTP_PORT = activePort;
    const adminPass = getAdminPassword();
    console.log('================================================================================');
    console.log(`  🚀 KINGMC MULTI-BOT MANAGER (COMMANDER V7) ĐÃ KHỞI CHẠY THÀNH CÔNG!`);
    console.log(`  🌐 WEB DASHBOARD: http://localhost:${activePort} (hoặc domain VPS / Hosting)`);
    console.log(`  📦 NỀN TẢNG: ${MANAGER_PLATFORM.toUpperCase()} | PORT WEB: ${activePort}`);
    console.log(`  🔑 ADMIN AUTH: ${adminPass ? 'Đã cấu hình & kích hoạt (scrypt protected)' : 'Chưa cấu hình'}`);
    console.log(`  🤖 SỐ LƯỢNG BOT QUẢN LÝ: ${BOT_CONFIG.length}`);
    console.log('================================================================================');
    console.log(`[STORAGE] Supabase Cloud ${supabaseStorageReady ? 'sẵn sàng' : 'đang khởi tạo hoặc chưa cấu hình'}.`);
    console.log(`[CONFIG] Loaded ${BOT_CONFIG.length} bot(s).`);
    for (const bot of BOT_CONFIG) {
        console.log(`[CONFIG] ${bot.label} | ${bot.url || '(missing)'}`);
    }
    void refreshAllSummaries();
    const tryInitCloud = async (attempt = 1) => {
        try {
            const initialized = await initSupabaseCloud();
            if (initialized) {
                await ensureInitialSystemBackup();
                // P1-03: Chạy key rotation sau khi Supabase cloud storage đã sẵn sàng 100%
                void reencryptCredentialsOnKeyRotation().catch(e => console.error('[KEY-ROTATION] Error:', e.message));
                const authSync = await syncAuthToAllBotsDetailed(true);
                if (!authSync.ok) console.warn('[AUTH-SYNC] Supabase đã khôi phục; một số worker chưa nhận auth. Sẽ thử lại định kỳ:', authSync.results.filter(item => !item.ok).map(item => '#' + item.botId + ': ' + item.error).join('; '));
                await resumePendingCustomerResets();
                const resetRetryTimer = setInterval(() => {
                    if (supabaseStorageReady) {
                        void resumePendingCustomerResets().catch(err => console.error('[RESET_CUSTOMER] Lỗi retry định kỳ:', err.message));
                    }
                }, 60 * 1000);
                if (typeof resetRetryTimer.unref === 'function') resetRetryTimer.unref();
                return;
            }
        } catch (err) {
            console.error('[SUPABASE] Lỗi khởi tạo cloud (lần ' + attempt + '):', err.message);
        }
        if (!supabaseStorageReady && supabaseAdapter?.isEnabled()) {
            const delay = Math.min(60000, 3000 * Math.pow(1.5, Math.min(attempt - 1, 8)));
            console.log(`[SUPABASE] Sẽ tự động thử kết nối lại Supabase Cloud sau ${Math.round(delay / 1000)}s...`);
            const retryTimer = setTimeout(() => void tryInitCloud(attempt + 1), delay);
            if (typeof retryTimer.unref === 'function') retryTimer.unref();
        }
    };
    void tryInitCloud();
    if (!supabaseAdapter || !supabaseAdapter.isEnabled()) {
        void reencryptCredentialsOnKeyRotation().catch(e => console.error('[KEY-ROTATION] Error:', e.message));
    }

    // Memory Guard: Tự động chạy GC khi RAM vượt quá 220MB hoặc định kỳ mỗi 15 phút (Render Cloud Protection)
    const memoryGuardTimer = setInterval(() => {
        try {
            const mem = process.memoryUsage();
            const rssMb = Math.round(mem.rss / (1024 * 1024));
            if (rssMb > 220) {
                runGarbageCollection();
            }
        } catch (_) {}
    }, 60 * 1000);
    if (typeof memoryGuardTimer.unref === 'function') memoryGuardTimer.unref();
});

async function initSupabaseCloud() {
    if (!supabaseAdapter || !supabaseAdapter.isEnabled()) {
        supabaseStorageReady = false;
        console.warn('[SUPABASE] Chưa cấu hình Supabase. Dữ liệu ứng dụng sẽ chỉ được giữ trong RAM cho tới khi Cloud sẵn sàng.');
        return false;
    }
    const ping = await supabaseAdapter.testConnection();
    if (!ping.ok) {
        console.error('[SUPABASE] Cloud không sẵn sàng: ' + ping.error + '. Giữ nguyên trạng thái hiện tại; không ghi fallback lên file hoặc Cloud.');
        supabaseStorageReady = false;
        return false;
    }
    const previous = {
        registry: JSON.parse(JSON.stringify(registry)), bots: BOT_CONFIG,
        users: loadUsers(), keys: loadKeysFile(), sessions: [...activeSessions.values()],
        storageReady: supabaseStorageReady, registryNeedsSave,
        registryCloudBaseline: registryCloudBaseline ? JSON.parse(JSON.stringify(registryCloudBaseline)) : null
    };
    try {
        const [remoteReg, remoteUsers, remoteKeys, remoteSessions] = await Promise.all([
            supabaseAdapter.fetchRegistry(), supabaseAdapter.fetchUsers(), supabaseAdapter.fetchKeys(), supabaseAdapter.fetchSessions()
        ]);
        if (!remoteReg || typeof remoteReg !== 'object' ||
            !Array.isArray(remoteUsers) || !Array.isArray(remoteKeys) || !Array.isArray(remoteSessions)) {
            throw new Error('Không tải đủ manager_users/manager_keys/manager_sessions từ Supabase; không áp dụng đồng bộ một phần.');
        }
        registryCloudBaseline = JSON.parse(JSON.stringify(remoteReg));
        const hasAdminPasswordOverride = String(process.env.ADMIN_PASSWORD || process.env.MANAGER_ADMIN_PASSWORD || process.env.MANAGER_PASSWORD || MANAGER_CONFIG.ADMIN_PASSWORD || '').trim();
        {
            for (const key of ['dynamicBots','disabledEnvUrls','disabledEnvIds','overrides','orderUrls','order','botIdMap','botSecrets','botAliases','botTags','botRentalDisabled','systemSettings','announcement','webhook','lastBotId','mustChangePassword','pendingResets']) {
                if (remoteReg[key] !== undefined && remoteReg[key] !== null) registry[key] = remoteReg[key];
            }
            registry.botRentalDisabled = normalizeBotRentalDisabled(registry.botRentalDisabled);
            if (!hasAdminPasswordOverride && typeof remoteReg.adminPassword === 'string' && remoteReg.adminPassword.trim()) {
                registry.adminPassword = remoteReg.adminPassword;
            }
            initializeAdminPassword();
            BOT_CONFIG = buildManagerBotConfig();
        }
        setUsersCache(remoteUsers);
        setKeysCache(remoteKeys);
        // BUG-04: boot khôi phục snapshot Cloud — giữ lại phiên local young nếu có.
        setSessionsCache(remoteSessions, { preserveYoungLocalSessions: true });
        supabaseStorageReady = true;
        const bootstrapPersist = await persistAdminBootstrapIfNeeded();
        if (bootstrapPersist.persisted) registryNeedsSave = false;
        const remoteRegistryHasData = Object.keys(remoteReg).length > 0;
        if (registryNeedsSave && remoteRegistryHasData) {
            if (!(await saveRegistry())) throw new Error('Không lưu được ánh xạ BOT_ID vừa chuẩn hóa lên Supabase.');
            registryNeedsSave = false;
        }
        void flushPendingAuditLogs();
        console.log('[SUPABASE] Đã khôi phục ' + remoteUsers.length + ' users và ' + remoteKeys.length + ' keys từ Cloud. Không tự đẩy/xóa dữ liệu Cloud khi khởi động.');
        return true;
    } catch (err) {
        Object.keys(registry).forEach(key => delete registry[key]);
        Object.assign(registry, previous.registry);
        BOT_CONFIG = previous.bots;
        setUsersCache(previous.users);
        setKeysCache(previous.keys);
        // BUG-04: rollback về trạng thái local trước lỗi — giữ phiên young.
        setSessionsCache(previous.sessions, { preserveYoungLocalSessions: true });
        registryNeedsSave = previous.registryNeedsSave;
        registryCloudBaseline = previous.registryCloudBaseline;
        supabaseStorageReady = false;
        console.error('[SUPABASE] Không thể đồng bộ trạng thái từ Cloud:', err.message);
        return false;
    }
}

function shutdownProcess(signal) {
    console.log(`[PROCESS] Nhận ${signal}, đang shutdown...`);
    if (summaryRefreshTimer) {
        clearInterval(summaryRefreshTimer);
        summaryRefreshTimer = null;
    }
    if (server) {
        server.close(() => {
            console.log('[PROCESS] HTTP server closed.');
            process.exit(0);
        });
        setTimeout(() => process.exit(0), 5000);
    } else {
        process.exit(0);
    }
}

process.on('SIGTERM', () => shutdownProcess('SIGTERM'));
process.on('SIGINT', () => shutdownProcess('SIGINT'));

process.on('uncaughtException', (err) => {
    console.error('[PROCESS] Uncaught Exception:', err.message || err);
});

process.on('unhandledRejection', (reason) => {
    console.error('[PROCESS] Unhandled Rejection:', reason?.message || reason);
});
